const TUTTE_LE_DIRETTRICI = MODULI.flatMap((m) => m.direttrici.map((d) => ({ ...d, modulo: m.id })));
const direttricePerId = (id) => TUTTE_LE_DIRETTRICI.find((d) => d.id === id) || null;

/** Temi di Fase 0 che alimentano ciascun modulo: filtra il materiale da passare all'IA. */
const TEMI_PER_MODULO = {
  A: ["parti_correlate", "politiche_contabili", "natura_crediti", "composizione_debiti"],
  B: ["politiche_contabili", "natura_crediti", "eventi_straordinari", "contenzioso"],
  C: ["governance", "remunerazione", "covenants", "eventi_straordinari", "composizione_debiti", "liquidita"],
  D: ["governance", "revisione", "giudizio_revisione", "controllo_interno", "remunerazione", "parti_correlate", "politiche_contabili", "contenzioso"],
};


/* ==========================================================================
   [7-bis] CLUSTERING ALGORITMICO — domain/clustering.js  (Modulo A)
   --------------------------------------------------------------------------
   Il confronto di un'azienda con "il settore" vale quanto il gruppo con cui la
   si confronta. Questo motore costruisce il cluster dei pari — stesso settore,
   stessa fascia di capitalizzazione — e misura quanto l'azienda si allontana
   dalla media del gruppo, in unità di deviazione standard.

   Perché la σ e non uno scostamento percentuale fisso: una metrica con molta
   dispersione naturale (il margine lordo varia enormemente fra le aziende dello
   stesso settore) tollera scostamenti che per una metrica stabile sarebbero
   anomali. Il z-score normalizza rispetto a quanto quella metrica *tipicamente*
   varia in quel cluster. Oltre 2σ, l'azienda sta fuori dal comportamento del
   ~95% dei suoi pari: non è la prova di un problema, è il punto in cui si
   smette di poter dire "è normale per il settore".

   I peer possono arrivare da due fonti: i parametri esterni caricati in Fase 0
   (perimetro "peer"), oppure una tabella di riferimento settoriale di ripiego,
   dichiarata come tale. Non si inventano peer: se non ce ne sono abbastanza per
   una statistica, il confronto resta indisponibile.
   ========================================================================== */

/** Fasce di capitalizzazione: due aziende dello stesso settore ma di taglia
    diversa non sono pari. Il cluster incrocia settore e fascia. */
const FASCE_CAP = [
  { id: "micro", label: "Micro cap", max: 300e6 },
  { id: "small", label: "Small cap", max: 2e9 },
  { id: "mid", label: "Mid cap", max: 10e9 },
  { id: "large", label: "Large cap", max: Infinity },
];
const fasciaCap = (cap) => (cap === null || cap === undefined ? null : FASCE_CAP.find((f) => cap < f.max) || FASCE_CAP[FASCE_CAP.length - 1]);

/** Metriche su cui si misura la deviazione dal cluster. */
const METRICHE_CLUSTER = [
  { id: "dso", label: "Giorni medi di incasso (DSO)", indicatore: "dso", direzioneRischio: "alto", unita: "giorni" },
  { id: "margineLordo", label: "Margine lordo", indicatore: "margineEbitda", direzioneRischio: "entrambi", unita: "%" },
  { id: "inventoryTurnover", label: "Rotazione del magazzino", indicatore: "rotazioneMagazzino", direzioneRischio: "basso", unita: "x" },
];

/** Media e deviazione standard campionaria di una serie, ignorando i nulli. */
function statistica(valori) {
  const v = valori.filter((x) => typeof x === "number" && isFinite(x));
  if (v.length < 3) return { n: v.length, media: null, sigma: null };
  const media = v.reduce((s, x) => s + x, 0) / v.length;
  const varianza = v.reduce((s, x) => s + (x - media) ** 2, 0) / (v.length - 1);
  return { n: v.length, media, sigma: Math.sqrt(varianza) };
}

/**
 * Estrae dai parametri esterni di Fase 0 i valori dei peer per una metrica.
 * Si accettano solo i parametri con perimetro "peer" che portano una serie di
 * valori o più occorrenze della stessa metrica: un singolo numero "di settore"
 * non è un campione da cui ricavare una σ.
 */
function serieDaiPeer(parametriDerivati, metrica) {
  const righe = (parametriDerivati || []).filter((p) => p && p.metrica === metrica && (p.perimetro === "peer" || p.perimetro === "settore"));
  const serie = [];
  for (const r of righe) {
    if (Array.isArray(r.valori)) serie.push(...r.valori.filter((x) => typeof x === "number"));
    else if (typeof r.valore === "number") serie.push(r.valore);
  }
  return serie;
}

/**
 * CLUSTERING E Z-SCORE
 * @returns per ogni metrica: valore dell'azienda, statistica del cluster,
 *          z-score e livello di semaforo (rosso oltre 2σ).
 */
function clusterizza({ indicatori, parametriDerivati, settore, capitalizzazione, tabellaRiferimento }) {
  const fascia = fasciaCap(capitalizzazione);
  const valoreAzienda = (id) => {
    const map = { dso: indicatori?.dso, margineEbitda: indicatori?.margineEbitda, rotazioneMagazzino: indicatori?.rotazioneMagazzino };
    const ind = map[id];
    return ind && ind.disponibile ? ind.valore : null;
  };

  const risultati = METRICHE_CLUSTER.map((m) => {
    const azienda = valoreAzienda(m.indicatore);
    let serie = serieDaiPeer(parametriDerivati, m.id);
    let fonte = "peer esterni";
    if (serie.length < 3 && tabellaRiferimento?.[settore]?.[m.id]) {
      serie = tabellaRiferimento[settore][m.id];
      fonte = "tabella di riferimento settoriale";
    }
    const stat = statistica(serie);

    let z = null, livello = "non_determinabile", lettura = "";
    if (azienda === null) {
      lettura = "La metrica dell'azienda non è calcolabile dai riclassificati.";
    } else if (stat.sigma === null) {
      lettura = `Servono almeno tre peer per una statistica di cluster: ne risultano ${stat.n}.`;
    } else if (stat.sigma === 0) {
      livello = azienda === stat.media ? "verde" : "giallo";
      lettura = "I peer del cluster hanno tutti lo stesso valore: la deviazione è nulla e lo z-score non è definito.";
    } else {
      z = (azienda - stat.media) / stat.sigma;
      const az = Math.abs(z);
      // Il verso conta: un DSO molto sotto la media non è un rischio, un DSO
      // molto sopra sì. Per il margine entrambe le code meritano attenzione.
      const versoRischioso =
        m.direzioneRischio === "alto" ? z > 0 :
        m.direzioneRischio === "basso" ? z < 0 : true;
      if (az > 2 && versoRischioso) livello = "rosso";
      else if (az > 2) livello = "giallo";
      else if (az > 1 && versoRischioso) livello = "giallo";
      else livello = "verde";
      lettura = `L'azienda è a ${fmtNum(z, 2)}σ dalla media del cluster (${fmtNum(stat.media, 1)}${m.unita === "%" ? "%" : m.unita === "giorni" ? " gg" : ""}, σ ${fmtNum(stat.sigma, 1)}). ` +
        (az > 2 ? `Oltre due deviazioni standard: fuori dal comportamento di circa il 95% dei pari${versoRischioso ? ", nella direzione che segnala rischio" : ", ma nella direzione favorevole"}.` : "Dentro l'intervallo di normalità del cluster.");
    }

    return {
      id: m.id, label: m.label, unita: m.unita,
      valoreAzienda: azienda, cluster: stat, zScore: z, livello, lettura, fonte,
      soglia2Sigma: stat.sigma !== null ? { min: stat.media - 2 * stat.sigma, max: stat.media + 2 * stat.sigma } : null,
    };
  });

  return {
    cluster: { settore: settorePerId(settore).label, fascia: fascia ? fascia.label : "capitalizzazione non indicata" },
    metriche: risultati,
    livelloComplessivo: risultati.reduce((acc, r) => peggiore(acc, r.livello), "verde"),
    metricheOltre2Sigma: risultati.filter((r) => r.zScore !== null && Math.abs(r.zScore) > 2).length,
  };
}

/* --------------------------------------------------------------------------
   Tabella di riferimento settoriale di ripiego. Valori indicativi usati solo
   quando non ci sono abbastanza peer reali, e sempre dichiarati come tali in
   interfaccia: non sono dati di mercato, sono un ordine di grandezza.
-------------------------------------------------------------------------- */
const RIFERIMENTO_SETTORIALE = {
  manifatturiero: { dso: [62, 71, 58, 66, 75, 60], margineLordo: [21, 24, 19, 26, 22, 20], inventoryTurnover: [5.1, 4.6, 5.8, 4.2, 5.4, 4.9] },
  retail: { dso: [12, 18, 9, 22, 15, 11], margineLordo: [32, 28, 35, 30, 27, 33], inventoryTurnover: [8.2, 7.1, 9.4, 6.8, 7.9, 8.6] },
  software: { dso: [48, 55, 41, 60, 52, 45], margineLordo: [72, 78, 68, 81, 74, 70], inventoryTurnover: [40, 55, 32, 60, 48, 38] },
  costruzioni: { dso: [95, 110, 82, 120, 101, 88], margineLordo: [14, 17, 11, 19, 15, 13], inventoryTurnover: [3.1, 2.6, 3.8, 2.2, 3.4, 2.9] },
};

/* ==========================================================================
   [7-ter] SOFT SIGNALS — domain/softSignals.js  (Modulo D)
   --------------------------------------------------------------------------
   Alcuni dei segnali più affidabili non sono nel testo delle relazioni: sono
   nei metadati. Un cambio di revisore, un giudizio con rilievi, un deposito in
   ritardo sono fatti registrati, con una data, che non richiedono di leggere
   fra le righe. Questo estrattore li raccoglie dai metadati dei documenti già
   acquisiti in Fase 0 e li porta al Modulo D come segnali forti.

   Ciascun segnale è un fatto verificabile con la sua fonte: non "l'azienda
   sembra opaca" ma "il revisore è cambiato due volte in tre anni, ecco le date".
   ========================================================================== */

const FINESTRA_ANNI = 3;

/** Estrae l'anno da una stringa di data o dal nome di un documento. */
function annoDi(x) {
  if (!x) return null;
  const m = String(x).match(/(20\d{2})/);
  return m ? parseInt(m[1], 10) : null;
}

const RE_REVISORE = /(societ[àa] di revisione|independent (registered )?public accounting firm|auditor|revisore(?: legale)?)\s*[:\-]?\s*([A-Z][A-Za-z&.,'’\s]{2,60})/i;
const RE_NOMI_REVISORI = /\b(deloitte|pwc|pricewaterhousecoopers|kpmg|ernst\s*&?\s*young|ey|bdo|grant thornton|rsm|mazars|baker tilly|crowe)\b/gi;

/**
 * ESTRATTORE DI SOFT SIGNALS
 * @param documenti  metadati dei documenti di Fase 0 (tipo, data, revisore…)
 * @param estratti   estratti tradotti, per cogliere i giudizi con rilievi
 * @param oggi       data di riferimento (default: adesso), iniettabile per i test
 */
function estraiSoftSignals({ documenti = [], estratti = [], oggi = new Date() } = {}) {
  const annoCorrente = oggi.getFullYear();
  const segnali = [];

  /* 1 · Cambio di società di revisione negli ultimi 3 anni --------------- */
  const revisoriPerAnno = new Map();
  const fonteRevisore = new Map();
  for (const e of estratti) {
    const testo = `${e.traduzioneIt || ""} ${e.testoOriginale || ""}`;
    const anno = annoDi(e.documento) || annoDi(e.pagina) || null;
    const nomi = [...testo.matchAll(RE_NOMI_REVISORI)].map((m) => normalizza(m[1]).replace(/\s+/g, ""));
    if (!nomi.length) continue;
    const nome = nomi[0];
    const annoRif = anno || annoCorrente;
    if (annoCorrente - annoRif <= FINESTRA_ANNI) {
      revisoriPerAnno.set(annoRif, nome);
      if (!fonteRevisore.has(nome)) fonteRevisore.set(nome, { documento: e.documento || "documento", pagina: e.pagina ?? null });
    }
  }
  // Anche i metadati espliciti dei documenti, se presenti.
  for (const d of documenti) {
    if (d.revisore) {
      const anno = annoDi(d.data) || annoDi(d.nomeFile) || annoDi(d.etichetta) || annoDi(d.caricatoIl) || annoCorrente;
      if (annoCorrente - anno <= FINESTRA_ANNI) revisoriPerAnno.set(anno, normalizza(d.revisore).replace(/\s+/g, ""));
    }
  }
  const revisoriDistinti = new Set(revisoriPerAnno.values());
  if (revisoriDistinti.size > 1) {
    const cronologia = [...revisoriPerAnno.entries()].sort((a, b) => a[0] - b[0]);
    segnali.push({
      id: "cambio_revisore", livello: "rosso",
      titolo: "Cambio di società di revisione negli ultimi 3 anni",
      dettaglio: `Risultano ${revisoriDistinti.size} società di revisione distinte fra il ${cronologia[0][0]} e il ${cronologia[cronologia.length - 1][0]}. Un avvicendamento del revisore è tra i predittori più studiati di rischio contabile, specie se ravvicinato o non spiegato.`,
      fatti: cronologia.map(([anno]) => ({ etichetta: String(anno), valore: "revisore diverso rilevato" })),
      daVerificare: "Item 4.01 del Form 8-K o comunicazione Consob sul cambio di incarico, e la ragione dichiarata (dimissioni o revoca).",
    });
  }

  /* 2 · Giudizi con rilievi (qualified opinions) ------------------------- */
  const rilievi = [];
  for (const e of estratti) {
    const testo = `${e.traduzioneIt || ""} ${e.testoOriginale || ""}`;
    if (/(giudizio con rilievi|qualified opinion|except for|a eccezione di|impossibilit[àa] di esprimere|disclaimer of opinion|giudizio negativo|adverse opinion)/i.test(testo)) {
      rilievi.push({ documento: e.documento || "documento", pagina: e.pagina ?? null, citazione: (e.traduzioneIt || e.testoOriginale || "").slice(0, 200) });
    }
  }
  if (rilievi.length) {
    segnali.push({
      id: "qualified_opinion", livello: "rosso",
      titolo: "Giudizio del revisore con rilievi",
      dettaglio: `In ${plurale(rilievi.length, "documento risulta", "documenti risultano")} un giudizio diverso da quello positivo senza riserve. È la dichiarazione formale che una parte del bilancio non è approvata o non è stata verificabile.`,
      fatti: rilievi.slice(0, 3).map((r) => ({ etichetta: `${r.documento}${r.pagina ? `, p. ${r.pagina}` : ""}`, valore: r.citazione })),
      daVerificare: "Il tipo esatto di giudizio (con rilievi, negativo, o dichiarazione di impossibilità) e la posta interessata.",
    });
  }

  /* 3 · Ritardi nel deposito (late filings) ------------------------------ */
  const ritardi = [];
  for (const d of documenti) {
    if (d.late === true || d.ritardoDeposito === true || (d.tipo && /nt 10-k|nt 10-q|nt 20-f/i.test(d.tipo))) {
      ritardi.push({ tipo: d.tipo || d.etichetta || "documento", data: d.data || null });
    }
    // Un Form NT ("Notification of inability to timely file") è di per sé la prova del ritardo.
    if (d.etichetta && /\bNT\b/.test(d.etichetta)) ritardi.push({ tipo: d.etichetta, data: d.data || null });
  }
  for (const e of estratti) {
    const testo = `${e.traduzioneIt || ""} ${e.testoOriginale || ""}`;
    if (/(late filing|deposito tardivo|ritardo nel deposito|notification of (inability|late)|form nt|mancato deposito nei termini)/i.test(testo)) {
      ritardi.push({ tipo: "riferimento a deposito tardivo", data: annoDi(e.documento), fonte: e.documento });
    }
  }
  if (ritardi.length) {
    segnali.push({
      id: "late_filing", livello: "rosso",
      titolo: "Ritardo nel deposito dei documenti (late filing)",
      dettaglio: `${plurale(ritardi.length, "indizio di deposito tardivo", "indizi di deposito tardivo")} presso l'autorità di vigilanza (SEC/Consob). Un ritardo nel deposito accompagna spesso difficoltà nella chiusura dei conti o disaccordi con il revisore.`,
      fatti: ritardi.slice(0, 4).map((r) => ({ etichetta: r.tipo, valore: r.data ? String(r.data) : "data non precisata" })),
      daVerificare: "Il Form NT depositato e la motivazione addotta per il ritardo.",
    });
  }

  return {
    segnali,
    livello: segnali.reduce((acc, s) => peggiore(acc, s.livello), "verde"),
    quanti: segnali.length,
    finestraAnni: FINESTRA_ANNI,
    estrattiIl: new Date().toISOString(),
  };
}

/**
 * DOVE SI TROVA DI NORMA — mappa per direttrice.
 * -----------------------------------------------------------------------------
 * Quando una direttrice resta "non determinabile", dire soltanto che il dato non
 * risulta è vero ma inutile: il revisore vuole sapere dove andarlo a prendere.
 * Questa mappa alimenta l'indicazione mostrata sotto le direttrici scoperte ed è
 * anche il promemoria di che cosa la Fase 0 avrebbe dovuto estrarre — se il dato
 * esiste nel documento ma qui non è arrivato, il difetto è nell'estrazione, non
 * nella diagnosi.
 */
const DOVE_CERCARE = {
  // Direttrici che dipendono dai numeri: qui non manca una sezione di un
  // documento, manca un riclassificato o un parametro di confronto.
  A1: [["CE riclassificato", "EBITDA e ricavi di due esercizi consecutivi"], ["Analyst report / Banca dati", "margine di settore o dei comparabili (livello esterno di Fase 0)"]],
  A2: [["SP + CE riclassificati", "crediti verso clienti e ricavi di due esercizi"], ["Banca dati settoriale", "giorni medi di incasso del settore"]],
  B1: [["SP riclassificato", "posta sensibile del settore e totale attivo"], ["Nota integrativa", "criteri di stima della posta"]],
  B2: [["SP + CE riclassificati", "rimanenze e ricavi di due esercizi"]],
  B3: [["SP + CE riclassificati", "crediti e ricavi di due esercizi"], ["RF riclassificato", "flusso di cassa della gestione operativa"]],
  C2: [["Debt Agreement", "clausole finanziarie, soglie e date di verifica"], ["20-F", "Item 5.B — Liquidity and Capital Resources"], ["10-K", "note sui debt covenants"]],
  A3: [["20-F", "Item 7.B — Related Party Transactions"], ["10-K", "Part III Item 13"], ["Nota integrativa", "operazioni con parti correlate"]],
  A4: [["20-F", "Item 5 — Critical Accounting Estimates"], ["10-K", "Item 7 — MD&A, stime critiche"], ["Nota integrativa", "criteri di valutazione"]],
  B4: [["20-F", "Item 5.A — Operating Results, commesse"], ["Nota integrativa", "lavori in corso su ordinazione e SAL"]],
  C1: [["8-K / 6-K", "Item 5.02 — nomine e cessazioni"], ["20-F", "Item 6.A — Directors and Senior Management"]],
  C3: [["8-K / 6-K", "operazioni straordinarie annunciate"], ["20-F", "Item 4 — Information on the Company"], ["Business Plan", "operazioni previste"]],
  C4: [["DEF 14A", "Compensation Discussion & Analysis"], ["20-F", "Item 6.B — Compensation"]],
  D1: [["20-F", "Item 6.A e 6.C — organi e board practices"], ["DEF 14A", "Board Leadership Structure"], ["10-K", "Part III Item 10"]],
  D2: [["20-F", "Item 6.C — indipendenza e comitati"], ["20-F", "Item 16D — esenzioni sul comitato di controllo"], ["DEF 14A", "Director Independence"]],
  D3: [["20-F", "Item 15 — Controls and Procedures"], ["20-F", "Item 16A — Audit Committee Financial Expert"], ["10-K", "Item 9A"]],
  D4: [["20-F", "Item 16C e 16F — corrispettivi e cambio del revisore"], ["8-K", "Item 4.01 — cambio revisore"], ["Relazione di revisione", "giudizio, rilievi, key audit matters"]],
};

/* ==========================================================================
   [2] LETTURA DEI DATI NUMERICI — domain/indicatori.js
   --------------------------------------------------------------------------
   I JSON di SP, CE e RF arrivano da tre applicazioni diverse della suite e non
   hanno una forma garantita: possono essere alberi annidati, elenchi di righe
   { voce, corrente, precedente } o mappe piatte. Invece di pretendere uno
   schema, il lettore appiattisce qualunque struttura in un indice di coppie
   percorso → numero e poi cerca le voci per sinonimi.

   Ogni voce trovata porta con sé il percorso da cui proviene: è ciò che rende
   il calcolo ispezionabile. Un indicatore che non si può risalire alla riga di
   bilancio da cui nasce, in analisi forense, non vale nulla.
   ========================================================================== */

const normalizza = (s) =>
  String(s ?? "")
    // I JSON della suite usano indifferentemente camelCase ("risultatoNetto"),
    // snake_case e descrizioni estese: separare le maiuscole prima di tutto
    // rende le tre convenzioni equivalenti agli occhi della ricerca.
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    // Seconda passata, indispensabile in italiano: la regola sopra separa solo
    // una maiuscola preceduta da minuscola, e lascia quindi incollate le
    // congiunzioni e le preposizioni di una lettera che il camelCase porta con
    // sé. "debitiALungoTermine" diventava "debiti alungo termine" e
    // "costiGeneraliEAmministrativi" diventava "costi generali eamministrativi":
    // nessuno dei due corrispondeva più al proprio sinonimo, e la voce risultava
    // assente pur essendo scritta correttamente nel file. Vale anche per gli
    // acronimi attaccati a una parola ("totaleEBITDARettificato").
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();

/** Converte "1.234,56", "(1,234.56)", "12%" e numeri veri in Number. Il resto è null. */
function toNumero(x) {
  if (typeof x === "number") return isFinite(x) ? x : null;
  if (typeof x !== "string") return null;
  const grezzo = x.trim();
  if (!grezzo || !/\d/.test(grezzo)) return null;
  if (/^\d{4}-\d{2}-\d{2}/.test(grezzo)) return null; // è una data, non un importo
  const negativo = /^\(.*\)$/.test(grezzo) || /^-/.test(grezzo);
  let t = grezzo.replace(/[^\d.,]/g, "");
  if (!t) return null;
  const virgolaDecimale = /,\d{1,2}$/.test(t);
  if (virgolaDecimale) t = t.replace(/\./g, "").replace(",", ".");
  else t = t.replace(/,/g, "");
  const n = parseFloat(t);
  if (!isFinite(n)) return null;
  return negativo ? -Math.abs(n) : n;
}

/** Chiavi che in una riga tabellare contengono il valore, non l'etichetta. */
const CHIAVI_VALORE = ["corrente", "correnti", "precedente", "precedenti", "valore", "importo", "current", "prior", "previous", "attuale", "t", "t1", "n", "n1"];

/** Un anno a quattro cifre usato come chiave è un esercizio, non una voce. */
const eAnno = (parola) => /^(19|20)\d{2}$/.test(parola);

/**
 * Una chiave indica l'esercizio (e non una voce di bilancio) quando OGNI parola
 * che la compone è un termine di periodo o un anno. La regola è volutamente
 * generale: l'elenco chiuso precedente riconosceva "corrente" e "precedente" ma
 * non "valorePrecedente", "importo_2024", "esercizioPrecedente" o la chiave
 * anno secca "2024" — forme tutte diffuse negli esporti riclassificati. Con
 * l'elenco chiuso quelle chiavi finivano concatenate nel percorso e il valore
 * restava senza periodo: il comparativo spariva, e con esso ogni indice che
 * confronta due esercizi. È esattamente il caso in cui il modello di Beneish
 * non produce nulla pur essendo il dato presente nel file.
 * @returns la chiave normalizzata se è di periodo, altrimenti null.
 */
function chiaveDiEsercizio(k) {
  const norm = normalizza(k);
  if (!norm) return null;
  const parole = norm.split(" ").filter(Boolean);
  const tuttePeriodo = parole.every((p) => MARCATORI_PERIODO.includes(p) || eAnno(p));
  return tuttePeriodo ? norm : null;
}

/**
 * Traduce il periodo grezzo letto dalla struttura in "corrente" | "precedente".
 * Gli anni non si possono classificare uno per uno — 2024 è corrente in un
 * bilancio e comparativo in quello dopo — quindi si guarda l'insieme degli anni
 * presenti nel documento: il più recente è l'esercizio corrente, gli altri sono
 * comparativi. È l'unica lettura che non richiede all'utente di dichiarare nulla.
 */
function risolviPeriodo(periodo, annoCorrente) {
  if (!periodo) return null;
  const parole = periodo.split(" ").filter(Boolean);
  if (parole.some((p) => MARCATORI_PRECEDENTE.includes(p))) return "precedente";
  const anno = parole.find(eAnno);
  if (anno) return annoCorrente && Number(anno) < Number(annoCorrente) ? "precedente" : "corrente";
  return "corrente";
}

/**
 * Appiattisce l'albero in coppie { percorso, valore, periodo }.
 *
 * Quando incontra una riga tabellare con etichetta esplicita
 * ({ voce: "Rimanenze", corrente: 100 }), innesta l'etichetta nel percorso:
 * senza questo passaggio la riga sarebbe indistinguibile da qualunque altra e
 * la ricerca per sinonimi fallirebbe.
 *
 * La chiave che indica l'esercizio ("corrente", "precedente") viene però tenuta
 * FUORI dal percorso e riportata a parte. Concatenarla generava frasi che nel
 * bilancio non esistono: la riga { voce: "Totale attivo", corrente: … }
 * produceva il percorso "totale attivo corrente", che contiene la locuzione
 * "attivo corrente" e veniva quindi assegnata all'attivo circolante. L'esercizio
 * corrente finiva così su una voce e il comparativo su un'altra, e l'indice
 * costruito su quelle due grandezze era privo di significato pur avendo
 * l'aspetto di un numero regolare. È la classe di errore peggiore che questo
 * lettore possa produrre, perché non lascia tracce a valle.
 */
function appiattisci(nodo, prefisso = "", out = [], periodo = null) {
  if (nodo === null || nodo === undefined) return out;
  if (Array.isArray(nodo)) {
    nodo.forEach((v, i) => appiattisci(v, `${prefisso}.${i}`, out, periodo));
    return out;
  }
  if (typeof nodo === "object") {
    const etichetta = nodo.voce ?? nodo.descrizione ?? nodo.label ?? nodo.nome ?? nodo.item ?? nodo.titolo ?? nodo.denominazione ?? nodo.riga ?? null;
    for (const [k, v] of Object.entries(nodo)) {
      // Una chiave composta di soli termini d'esercizio non porta informazione
      // di voce, e questo vale sia quando è la colonna di una riga tabellare
      // ({ voce: "Totale attivo", "2025": … }) sia quando è un ramo dell'albero
      // ({ "2025": { totaleAttivo: … } }). Prima la si riconosceva solo nel
      // primo caso, e nel secondo l'anno finiva dentro il percorso: le due
      // annualità diventavano due voci distinte e il comparativo spariva.
      const periodoChiave = chiaveDiEsercizio(k);
      const percorso = periodoChiave
        ? (etichetta ? `${prefisso}.${etichetta}` : prefisso)
        : `${prefisso}.${k}`;
      appiattisci(v, percorso, out, periodoChiave || periodo);
    }
    return out;
  }
  const n = toNumero(nodo);
  if (n !== null) out.push({ percorso: String(prefisso).replace(/^\./, ""), valore: n, periodo });
  return out;
}

/** Marcatori che qualificano un valore come riferito all'esercizio comparativo. */
const MARCATORI_PRECEDENTE = ["precedente", "precedenti", "prior", "previous", "comparativo", "comparativa", "py", "n 1", "t 1", "anno 1", "esercizio 1"];

/** Tutti i termini che nel percorso indicano un esercizio e non una voce di bilancio. */
const MARCATORI_PERIODO = [...new Set([...CHIAVI_VALORE, ...MARCATORI_PRECEDENTE.flatMap((m) => m.split(" ")), "esercizio", "anno", "periodo"])];

/** Sinonimi per ciascuna voce cercata. Ordine ininfluente: vince la corrispondenza più lunga. */
const ALIAS = {
  ricavi: ["ricavi netti", "ricavi delle vendite e delle prestazioni", "ricavi vendite prestazioni", "ricavi caratteristici", "valore della produzione", "fatturato", "net revenues", "net sales", "total revenue", "revenue", "ricavi"],
  valoreAggiunto: ["valore aggiunto", "value added"],
  ebitda: ["ebitda", "margine operativo lordo", "mol"],
  ebit: ["ebit", "risultato operativo", "reddito operativo", "operating income"],
  risultatoNetto: ["risultato netto", "utile netto", "utile d esercizio", "risultato d esercizio", "net income", "net profit", "profit for the year"],
  oneriFinanziari: ["oneri finanziari", "interessi passivi", "interest expense", "financial charges"],
  acquisti: ["costo del venduto", "costo dei beni venduti", "acquisti di materie prime", "consumi di materie prime", "consumi di materie", "costi per materie prime", "costi della produzione esterni", "acquisti", "consumi", "cost of goods sold", "cogs", "cost of sales"],
  creditiClienti: ["crediti verso clienti", "crediti commerciali", "trade receivables", "accounts receivable", "crediti clienti"],
  rimanenze: ["rimanenze finali", "rimanenze di magazzino", "rimanenze", "magazzino", "inventories", "inventory", "scorte"],
  lavoriInCorso: ["lavori in corso su ordinazione", "lavori in corso", "work in progress", "contract assets", "sal"],
  debitiFornitori: ["debiti verso fornitori", "debiti commerciali", "trade payables", "accounts payable", "debiti fornitori"],
  debitiFinanziari: ["debiti finanziari", "debiti verso banche", "indebitamento finanziario", "borrowings", "financial debt", "long term debt"],
  disponibilita: ["disponibilita liquide", "cassa e banche", "cash and cash equivalents", "liquidita"],
  pfn: ["posizione finanziaria netta", "indebitamento finanziario netto", "net financial position", "net debt"],
  patrimonioNetto: ["patrimonio netto", "capitale proprio", "total equity", "shareholders equity"],
  attivoTotale: ["totale attivo", "totale attivita", "totale dell attivo", "attivo totale", "totale generale attivo", "totale impieghi", "capitale investito lordo", "capitale investito", "totale a pareggio", "total assets"],
  immobilizzazioni: ["immobilizzazioni materiali", "immobili impianti e macchinari", "impianti e macchinari", "attivo immobilizzato", "attivo fisso", "totale immobilizzazioni", "property plant and equipment", "terreni e fabbricati",
    // La sigla PP&E compare in tutte le grafie: normalizzata diventa "pp e",
    // ed è quella la forma da cercare. Sta in fondo all'elenco perché è la più
    // corta e deve cedere il passo a qualunque denominazione estesa.
    "ppe strumentale", "pp e ordinario", "immobilizzazioni", "ppe", "pp e"],
  immobilizzazioniImmateriali: ["immobilizzazioni immateriali", "avviamento", "goodwill", "intangible assets", "costi di sviluppo"],
  fondiRischi: ["fondi per rischi e oneri", "accantonamenti", "provisions"],
  flussoOperativo: ["flusso finanziario della gestione reddituale", "flusso finanziario dell attivita operativa", "flusso di cassa della gestione operativa", "flusso di cassa operativo", "flusso della gestione operativa", "flusso monetario operativo", "cash flow operativo", "net cash from operating activities", "cash flow from operations", "operating cash flow"],
  ammortamenti: ["ammortamenti e svalutazioni", "ammortamenti e accantonamenti", "ammortamento delle immobilizzazioni", "ammortamenti", "amortization and depreciation", "depreciation and amortization", "depreciation"],

  /* Voci richieste dai modelli statistici della Fase 2. Restano qui e non in un
     vocabolario separato: la mappatura dei nomi di bilancio è un problema solo,
     e duplicarla significherebbe correggere i sinonimi in due posti. */
  attivoCorrente: ["totale attivo circolante", "attivo circolante", "totale attivo corrente", "attivo corrente", "attivita correnti", "totale attivita correnti", "capitale circolante lordo", "total current assets", "current assets"],
  passivoCorrente: ["totale passivo corrente", "passivo corrente", "passivo circolante", "passivita correnti", "totale passivita correnti", "totale debiti a breve", "debiti a breve termine", "debiti correnti", "passivita a breve termine", "debiti entro l esercizio", "debiti entro 12 mesi", "total current liabilities", "current liabilities"],
  titoli: ["attivita finanziarie correnti", "titoli iscritti nell attivo circolante", "marketable securities", "short term investments"],
  sga: ["spese generali e amministrative", "costi commerciali e amministrativi", "spese commerciali e amministrative", "costi generali e amministrativi", "costi amministrativi e generali", "spese amministrative", "costi generali", "costi di struttura", "selling general and administrative", "sg a"],
  debitiLungo: ["debiti a medio e lungo termine", "debiti a medio lungo termine", "debiti a lungo termine", "passivita non correnti", "totale passivita non correnti", "passivita a lungo termine", "passivo consolidato", "debiti oltre l esercizio", "debiti oltre 12 mesi", "long term debt", "non current liabilities"],
  capitaleSociale: ["capitale sociale", "share capital", "common stock"],
  azioni: ["numero di azioni", "azioni in circolazione", "shares outstanding", "weighted average shares"],

  /* IFRS 16 — incrementi dell'esercizio per nuovi contratti di leasing.
     Non è una voce che serve a un indicatore: serve a toglierla da due delta
     patrimoniali che altrimenti raccontano un investimento e un indebitamento
     che non sono mai passati per la cassa. */
  nuoviLeasing: ["additions to right of use assets", "nuovi contratti di leasing", "incrementi per leasing", "additions to lease liabilities", "new leases"],
};

/**
 * Prospetto in cui ciascuna voce risiede per natura. Serve a dirimere le
 * omonimie fra prospetti diversi, che sono la seconda fonte di corrispondenze
 * sbagliate dopo le rettifiche: «Investments in property, plant and equipment»
 * è una riga di capex del rendiconto, e senza questa preferenza soppiantava
 * le immobilizzazioni materiali dello stato patrimoniale — un flusso di
 * periodo, per giunta negativo, al posto di un saldo.
 */
const SLOT_ATTESO = {
  creditiClienti: ["SP"], rimanenze: ["SP"], lavoriInCorso: ["SP"], debitiFornitori: ["SP"],
  debitiFinanziari: ["SP"], disponibilita: ["SP"], pfn: ["SP"], patrimonioNetto: ["SP"],
  attivoTotale: ["SP"], immobilizzazioni: ["SP"], immobilizzazioniImmateriali: ["SP"],
  fondiRischi: ["SP"], attivoCorrente: ["SP"], passivoCorrente: ["SP"], titoli: ["SP"],
  debitiLungo: ["SP"], capitaleSociale: ["SP"],
  ricavi: ["CE"], valoreAggiunto: ["CE"], ebitda: ["CE"], ebit: ["CE"], risultatoNetto: ["CE"],
  oneriFinanziari: ["CE"], acquisti: ["CE"], sga: ["CE"],
  // Gli ammortamenti stanno nel conto economico, ma il rendiconto per metodo
  // indiretto li riespone identici fra le rettifiche non monetarie: leggerli
  // di lì quando il CE non li isola è corretto, non un ripiego.
  ammortamenti: ["CE", "RF"],
  flussoOperativo: ["RF"],
  /* Gli incrementi per leasing stanno nella nota sui diritti d'uso, che i
     moduli riportano ora sotto il rendiconto (fra le operazioni non monetarie)
     ora sotto lo stato patrimoniale (movimentazione delle immobilizzazioni). */
  nuoviLeasing: ["RF", "SP"],
};

/**
 * Cerca una voce nell'indice appiattito.
 * @returns {{corrente: number|null, precedente: number|null, percorso: string|null, slot: string|null}}
 */
function cercaVoce(indice, aliasNormalizzati, annoCorrente = null, slotAmmessi = null) {
  /* Il filtro è rigido, non una preferenza: se la voce non compare nel proprio
     prospetto resta non risolta. Accettare un ripiego altrove significherebbe,
     nel caso concreto che ha motivato questa regola, usare la riga di capex
     «Investments in property, plant and equipment» — un flusso di periodo, per
     giunta negativo — al posto del saldo delle immobilizzazioni materiali. Un
     dato mancante ferma il modello e si vede; un dato sbagliato lo attraversa
     e ne esce come un numero qualunque. */
  const righe = slotAmmessi ? indice.filter((r) => slotAmmessi.includes(r.slot)) : indice;
  /* Ordine di preferenza fra due candidati, dal criterio più forte al più
     debole: la provenienza, poi il prospetto di competenza, poi la specificità
     del sinonimo. Un totale ricavato dagli aggregati della riclassificazione
     batte sempre una riga di dettaglio che per caso contiene le stesse parole,
     e una posta letta nel prospetto giusto batte l'omonima letta altrove. È la
     regola che impedisce a «Other current assets» di presentarsi come attivo
     corrente quando il totale vero è disponibile, e a una riga di capex del
     rendiconto di presentarsi come immobilizzazioni. */
  const migliore = (nuovo, attuale) => {
    if (!attuale) return true;
    if (nuovo.priorita !== attuale.priorita) return nuovo.priorita > attuale.priorita;
    if (slotAmmessi && slotAmmessi.length > 1) {
      const n = slotAmmessi.indexOf(nuovo.slot), a2 = slotAmmessi.indexOf(attuale.slot);
      if (n !== a2) return n < a2;
    }
    return nuovo.punteggio > attuale.punteggio;
  };
  let corrente = null, precedente = null;
  for (const riga of righe) {
    for (const a of aliasNormalizzati) {
      if (!riga.percorsoNorm.includes(a)) continue;
      // Il periodo dichiarato dalla struttura ha la precedenza: solo quando la
      // riga non lo porta con sé si torna a dedurlo dal percorso.
      const eComparativo = riga.periodo
        ? risolviPeriodo(riga.periodo, annoCorrente) === "precedente"
        : MARCATORI_PRECEDENTE.some((m) => riga.percorsoNorm.includes(` ${m} `) || riga.percorsoNorm.endsWith(` ${m}`));
      const candidato = { valore: riga.valore, percorso: riga.percorso, slot: riga.slot, punteggio: a.length, priorita: riga.priorita || 0 };
      if (eComparativo) {
        if (migliore(candidato, precedente)) precedente = candidato;
      } else if (migliore(candidato, corrente)) {
        corrente = candidato;
      }
      break;
    }
  }
  /* Un indice costruito su due righe di bilancio diverse è peggio di un indice
     mancante. Il confronto avviene però sul "nucleo" del percorso, cioè al
     netto dei segmenti che indicano l'esercizio: nella forma
     { correnti: {...}, precedenti: {...} } i due rami hanno per costruzione
     percorsi diversi, e trattarli come disallineati azzererebbe ogni
     comparativo. Conta che sia la stessa voce, non che sia lo stesso ramo. */
  const nucleo = (p) => normalizza(p).split(" ").filter((w) => w && !MARCATORI_PERIODO.includes(w) && !eAnno(w)).join(" ");
  const disallineate = corrente && precedente && nucleo(corrente.percorso) !== nucleo(precedente.percorso);
  return {
    corrente: corrente ? corrente.valore : null,
    precedente: disallineate ? null : (precedente ? precedente.valore : null),
    percorso: corrente ? corrente.percorso : precedente ? precedente.percorso : null,
    slot: corrente ? corrente.slot : precedente ? precedente.slot : null,
    disallineamento: disallineate ? { corrente: corrente.percorso, precedente: precedente.percorso } : null,
  };
}

/* --------------------------------------------------------------------------
   LETTORE DEI FORMATI DELLA SUITE
   --------------------------------------------------------------------------
   I riclassificati che arrivano qui non sono JSON qualunque: li produce la
   stessa suite (SP, CE, RF), hanno un formato dichiarato e una struttura
   canonica. Appiattirli alla cieca come un albero anonimo è ciò che finora
   faceva fallire i modelli, e per due ragioni distinte.

   La prima è il rumore. Un salvataggio SP contiene, oltre ai prospetti, la
   nota integrativa con i suoi estratti, i delta calcolati, le riallocazioni e
   un ramo `statoApplicazione` che duplica per intero l'albero. L'appiattimento
   generico indicizzava 1.872 righe per tre prospetti da 80 voci: la ricerca
   per sinonimi pescava «Other current assets» come attivo corrente e
   `deltaPatrimoniali.deltaPatrimonioNetto` — una variazione — come patrimonio
   netto. Numeri plausibili e sbagliati, che è la classe di errore peggiore.

   La seconda è l'esercizio. Dentro `esercizioPrecedente.voci[]` ogni riga ha
   la forma { nome, importo }: la chiave `importo` veniva riconosciuta come
   chiave di periodo e sovrascriveva il «precedente» ereditato dal ramo padre,
   facendo confluire l'intero esercizio comparativo nell'anno corrente. Da qui
   i «· esercizio precedente» mancanti in blocco.

   La risposta non è aggiungere sinonimi: è leggere il formato per quello che
   è. Le voci stanno in due array canonici, i totali stanno negli `aggregati`,
   e gli aggregati sono già il risultato della riclassificazione — non vanno
   ricostruiti sommando etichette.
   -------------------------------------------------------------------------- */

const nSuite = (x) => (typeof x === "number" && isFinite(x) ? x : null);

/**
 * Righe di rettifica: riallocazioni per natura, storni da nota integrativa,
 * special item. Non sono poste di bilancio ma le due gambe di una scrittura
 * che sposta un importo da una classe all'altra, e il loro nome contiene per
 * forza la denominazione della voce di destinazione. Lasciate alla pari con le
 * poste vere rubano la corrispondenza: nel bilancio 2023 lo storno
 * «Accantonamento fondo svalutazione crediti commerciali» si presentava come
 * crediti verso clienti con un saldo di −2.767 al posto di Trade receivables.
 */
const eRettifica = (nome) => /^\s*(riall\.?\s*natura|riallocazione|storno|special item|rettifica)\b/i.test(String(nome || ""));

/** Somma gli addendi disponibili; null se nessuno lo è (0 è un valore, non un'assenza). */
function sommaSuite(...xs) {
  const v = xs.map(nSuite).filter((x) => x !== null);
  return v.length ? v.reduce((a, b) => a + b, 0) : null;
}

/** Somma gli importi delle voci appartenenti a una classe della riclassificazione. */
function sommaClasse(voci, ...classi) {
  const set = classi.map((c) => String(c).toLowerCase());
  const v = (voci || []).filter((x) => set.includes(String(x?.classe || "").toLowerCase()));
  return v.length ? v.reduce((a, x) => a + (nSuite(x.importo) ?? 0), 0) : null;
}

/**
 * Riconosce il formato di un salvataggio della suite.
 * Prima l'identificativo dichiarato, poi — se un file più vecchio non lo porta —
 * la firma degli aggregati, che è la parte più stabile di questi formati.
 */
function riconosciFormatoSuite(dati) {
  if (!dati || typeof dati !== "object") return null;
  if (typeof dati.formato === "string" && dati.formato.startsWith("ce-riclassificato")) return "CE";
  if (dati.modulo === "rendiconto_finanziario") return "RF";
  if (typeof dati.applicazione === "string" && /riclassificazione\s+sp/i.test(dati.applicazione)) return "SP";
  const agg = dati.esercizioCorrente?.aggregati;
  if (agg && typeof agg === "object") {
    if ("totAttivoContab" in agg || "cinTot" in agg || "pfnBreve" in agg) return "SP";
    if ("utileNetto" in agg || "valoreAggiunto" in agg) return "CE";
    if ("flussoOperativoCorrente" in agg || "fcfo" in agg) return "RF";
  }
  return null;
}

/**
 * Totali canonici per formato, ricavati dagli aggregati già calcolati dalla
 * riclassificazione. Le denominazioni sono scelte per corrispondere al sinonimo
 * PIÙ LUNGO del vocabolario, così che anche a parità di priorità vincano su una
 * corrispondenza accidentale: «Totale generale attivo» e non «Totale attivo»,
 * perché quest'ultimo è contenuto in «Totale attivo corrente» e i due si
 * ruberebbero il valore a vicenda.
 *
 * Non tutti gli aggregati diventano un totale sintetico. `immobOper`, per
 * esempio, comprende immateriali e crediti finanziari a lungo: emetterlo come
 * «attivo immobilizzato» soppianterebbe la voce «Property, plant and equipment»
 * su cui Beneish calcola AQI e DEPI, che vogliono le sole immobilizzazioni
 * materiali. Meglio nessun sintetico che un sintetico che copre il dato giusto.
 */
const TOTALI_SUITE = {
  SP: (agg, voci) => [
    ["Totale generale attivo", nSuite(agg.totAttivoContab) ?? nSuite(agg.totImpieghi)],
    ["Totale attivo corrente", sommaSuite(agg.attOpCorr, agg.attOpMag, agg.liq, agg.finAltre)],
    ["Totale passivo corrente", sommaSuite(agg.passOpCorr, agg.debFinC)],
    ["Totale passivita non correnti", sommaSuite(agg.passOpNC, agg.debFinNC)],
    ["Patrimonio netto", nSuite(agg.pn)],
    ["Disponibilita liquide", nSuite(agg.liq)],
    ["Rimanenze di magazzino", nSuite(agg.attOpMag)],
    ["Debiti finanziari", sommaSuite(agg.debFinC, agg.debFinNC)],
    ["Posizione finanziaria netta", nSuite(agg.pfn)],
  ],
  CE: (agg, voci) => [
    ["Ricavi delle vendite e delle prestazioni", nSuite(agg.ricavi)],
    ["Valore della produzione", nSuite(agg.valoreProduzione)],
    ["Valore aggiunto", nSuite(agg.valoreAggiunto)],
    ["EBITDA", nSuite(agg.ebitda)],
    ["EBIT", nSuite(agg.ebit)],
    ["Risultato netto", nSuite(agg.utileNetto)],
    ["Ammortamenti e svalutazioni", sommaClasse(voci, "AMMORTAMENTI")],
    ["Oneri finanziari", sommaClasse(voci, "ONERI_FIN")],
  ],
  RF: (agg) => [
    ["Flusso finanziario della gestione reddituale", nSuite(agg.flussoOperativoCorrente)],
  ],
};

/**
 * Indicizza un salvataggio della suite: le voci dei due esercizi con il loro
 * nome, gli aggregati grezzi e i totali canonici derivati.
 *
 * `priorita` distingue le tre provenienze e vale più della lunghezza del
 * sinonimo nella scelta del candidato: un totale ricavato dagli aggregati è per
 * costruzione più affidabile di una singola riga di dettaglio che per caso
 * contiene le stesse parole.
 *
 * @returns {Array|null} righe indicizzate, oppure null se il formato non è riconosciuto.
 */
function indicizzaSuite(dati, slot) {
  const formato = riconosciFormatoSuite(dati);
  if (!formato) return null;

  const righe = [];
  const aggiungi = (percorso, valore, periodo, priorita) => {
    const v = nSuite(valore);
    if (v === null) return;
    righe.push({
      percorso, valore: v, periodo, slot, priorita,
      percorsoNorm: ` ${normalizza(`${slot} ${percorso}`)} `,
    });
  };

  for (const [ramo, periodo] of [["esercizioCorrente", "corrente"], ["esercizioPrecedente", "precedente"]]) {
    const es = dati?.[ramo];
    if (!es || typeof es !== "object") continue;
    const voci = Array.isArray(es.voci) ? es.voci : [];
    const agg = es.aggregati && typeof es.aggregati === "object" ? es.aggregati : {};

    /* Ramo vuoto. I salvataggi in modalità singolo anno conservano comunque la
       struttura del comparativo: `voci` resta un array vuoto e gli aggregati
       restano tutti a zero, con un'etichetta d'esercizio spesso incoerente.
       Indicizzarlo sarebbe il danno peggiore possibile — quegli zeri non sono
       dati assenti ma dati presenti e falsi, e `raccogliVoci` li accetterebbe
       come validi facendo calcolare a Beneish indici costruiti su un totale
       attivo di zero anziché dichiarare la variabile mancante. */
    const totaliDichiarati = nSuite(es.totaleAttivita) !== null || nSuite(es.utileNetto) !== null;
    const vuoto = !voci.length && !totaliDichiarati
      && !Object.values(agg).some((x) => nSuite(x) !== null && x !== 0);
    if (vuoto) continue;

    // 1 · Voci di dettaglio, con il nome come percorso. Priorità minima: sono
    //     righe singole e possono essere omonime di un aggregato.
    for (const v of voci) {
      const nome = v?.nome ?? v?.voce ?? v?.descrizione;
      if (nome) aggiungi(String(nome), v.importo, periodo, eRettifica(nome) ? 0 : 1);
    }
    // 2 · Aggregati con la loro chiave originale: servono a chi cerca «ebitda»,
    //     «pfn» o «capex» con il nome tecnico della riclassificazione.
    for (const [k, val] of Object.entries(agg)) aggiungi(`aggregati.${k}`, val, periodo, 2);
    // 3 · Totali canonici: la lettura autorevole, quella che i modelli usano.
    for (const [nome, val] of (TOTALI_SUITE[formato] || (() => []))(agg, voci)) aggiungi(nome, val, periodo, 3);
    /* 4 · Contratto di radice. Priorità sopra i totali canonici perché non è
           derivato da nulla: è il numero che il produttore del file dichiara
           come proprio, ed è quello su cui il gatekeeper si è già pronunciato.
           Farlo scavalcare da un aggregato ricalcolato significherebbe far
           lavorare Beneish su un totale attivo diverso da quello validato. */
    if (nSuite(es.totaleAttivita) !== null) aggiungi("Totale generale attivo", es.totaleAttivita, periodo, 4);
    if (nSuite(es.utileNetto) !== null) aggiungi("Risultato netto", es.utileNetto, periodo, 4);
  }
  return righe.length ? righe : null;
}

/** Costruisce l'indice e risolve tutte le voci del vocabolario. */
function leggiVoci(numerico) {
  const indice = [];
  for (const slot of ["SP", "CE", "RF"]) {
    const dati = numerico?.[slot]?.dati;
    if (!dati) continue;
    // Se il file è un salvataggio della suite lo si legge per quello che è.
    // L'appiattimento generico resta per i JSON di provenienza diversa, dove
    // non esiste una struttura nota su cui appoggiarsi.
    const suite = indicizzaSuite(dati, slot);
    if (suite) { indice.push(...suite); continue; }
    for (const v of appiattisci(dati)) {
      indice.push({ ...v, slot, priorita: 0, percorsoNorm: ` ${normalizza(`${slot} ${v.percorso}`)} ` });
    }
  }
  /* Anno di riferimento del documento: il più recente fra quelli comparsi come
     chiave d'esercizio. Serve a decidere quale colonna-anno sia il corrente e
     quale il comparativo, senza chiederlo all'utente. Se il file non usa chiavi
     ad anno resta null e la classificazione avviene sui marcatori testuali. */
  const anni = indice.map((r) => (r.periodo || "").split(" ").find(eAnno)).filter(Boolean).map(Number);
  const annoCorrente = anni.length ? String(Math.max(...anni)) : null;

  const voci = {};
  for (const [chiave, alias] of Object.entries(ALIAS)) {
    voci[chiave] = cercaVoce(indice, alias.map(normalizza), annoCorrente, SLOT_ATTESO[chiave] || null);
  }
  // PFN ricostruita se non dichiarata: debiti finanziari meno liquidità.
  if (voci.pfn.corrente === null && voci.debitiFinanziari.corrente !== null) {
    voci.pfn = {
      corrente: voci.debitiFinanziari.corrente - (voci.disponibilita.corrente ?? 0),
      precedente: voci.debitiFinanziari.precedente !== null ? voci.debitiFinanziari.precedente - (voci.disponibilita.precedente ?? 0) : null,
      percorso: "ricostruita: debiti finanziari − disponibilità liquide",
      slot: "SP",
    };
  }
  return { indice, voci, righeIndicizzate: indice.length };
}


/* ==========================================================================
   CONTRATTO DI ESTRAZIONE — il prompt che i moduli a monte devono rispettare
   --------------------------------------------------------------------------
   Questa applicazione non estrae i prospetti: li riceve già riclassificati dai
   moduli SP, CE e RF. Il prompt vive comunque qui, versionato insieme al
   lettore che lo consuma, perché prompt e lettore sono due metà dello stesso
   contratto: cambiarne una sola è il modo più rapido per rompere l'ingestione
   senza che nessun test se ne accorga.

   Due regole di riclassificazione meritano una nota, perché la loro versione
   ingenua produce un errore che va tutto nella stessa direzione — verso
   l'alto — e in un'analisi forense la direzione dell'errore conta quanto la
   sua ampiezza.

   TFR. Spostare l'intero accantonamento fra gli oneri finanziari sgonfia il
   costo del lavoro e gonfia l'EBITDA. Lo IAS 19 separa due componenti con
   natura diversa: il service cost è retribuzione differita maturata
   nell'esercizio e resta operativo; solo l'interest cost, che nasce
   dall'attualizzazione del debito già maturato, è onere finanziario. La
   regola qui sotto impone lo split e vieta il travaso in blocco.

   Captive finance. Portare gli oneri finanziari della captive fuori
   dall'operativo è corretto per la vista industriale, ma solo se si fa
   altrettanto con i proventi. Togliere il costo e lasciare l'interesse attivo
   fra i ricavi gonfia l'EBITDA due volte: una per il costo rimosso, una per
   il ricavo trattenuto. La regola impone la simmetria.
   ========================================================================== */

const VERSIONE_CONTRATTO_ESTRAZIONE = "qoe.estrazione.v4";

const PROMPT_ESTRAZIONE_NUMERICA = `Sei un estrattore e normalizzatore avanzato di dati finanziari, specializzato
nell'analisi di bilanci consolidati (IFRS e US GAAP) per attività di validazione
e accounting forensics. Analizza i prospetti forniti e restituisci un output
ESCLUSIVAMENTE in formato JSON.

════════════════════════════════════════════════════════════════════════
0 · PRINCIPIO CHE PRECEDE OGNI ALTRA REGOLA
════════════════════════════════════════════════════════════════════════
Il sistema a valle è uno strumento di accounting forensics. Il suo Gatekeeper
Algebrico esiste per ACCORGERSI che un bilancio non chiude, non per ricevere
bilanci che chiudono sempre.

Ne discende il divieto più importante di questo contratto:
NON forzare MAI una quadratura inserendo una posta di bilanciamento, un plug,
un residuo tecnico o una "differenza da quadratura" di importo pari allo
scarto. Una posta simile fa passare il Gatekeeper per costruzione e cancella
l'unico segnale che avrebbe dovuto emettere. Uno scarto non spiegato è
un'informazione, e va CONSEGNATO come tale, non fatto sparire.

Quando una quadratura non chiude hai due sole strade lecite:
  (a) cercare nel documento la voce realmente omessa e aggiungerla — è dato
      trovato, ed è sempre la strada da tentare per prima;
  (b) se non la trovi, DICHIARARE il residuo nel blocco "quadrature" con
      l'importo esatto e la descrizione del tentativo fatto, lasciando le voci
      come sono.
La strada (b) non è un fallimento dell'estrazione: è il suo esito corretto.

════════════════════════════════════════════════════════════════════════
1 · NODI DI QUADRATURA E PRINCIPIO CONTABILE
════════════════════════════════════════════════════════════════════════
Il Gatekeeper verifica tre identità di partita doppia: Attività = Passività +
Patrimonio Netto, il raccordo dell'utile fra Conto Economico, Rendiconto e
prospetto di Patrimonio Netto, e la coincidenza della cassa finale.

È TASSATIVO esporre queste due chiavi alla radice di OGNI ramo d'esercizio
("esercizioCorrente" ed "esercizioPrecedente"), come campi propri, separati
dall'array "voci":

  "totaleAttivita" — totale delle attività (Total Assets).
  "utileNetto"     — risultato netto d'esercizio (Net Income / Profit / Loss).

Regole:
- numeri interi, con il segno corretto (una perdita è negativa);
- vanno esposte in tutti e tre i prospetti (SP, CE, RF), non solo in quello di
  provenienza naturale: sono testimoni indipendenti dello stesso numero, ed è
  dal loro confronto che si scopre un file allineato a un esercizio sbagliato;
- OLTRE al campo di radice, inserisci la voce corrispondente anche nell'array
  "voci", così che resti leggibile nel corpo del prospetto;
- se il prospetto non riporta il totale in modo esplicito, calcolalo dalle voci
  estratte e marcalo come ricostruito, così:
      { "nome": "Total Assets (Auto-calculated)", "importo": 0, "autoCalcolato": true }
      { "nome": "Net Profit (Auto-calculated)",  "importo": 0, "autoCalcolato": true }
  Il flag "autoCalcolato" non è decorativo: a valle un totale ricostruito viene
  trattato come prova più debole di un totale dichiarato. Non ometterlo mai, e
  non usarlo mai su un totale che invece era scritto nel documento.

1.bis · PRINCIPIO CONTABILE — DICHIARATO, NON DEDOTTO
Aggiungi alla radice del JSON (non dentro i rami d'esercizio) l'oggetto
"schemaContabile" indicando il principio contabile applicato al bilancio.

NON indovinarlo dall'aspetto delle tabelle, dalla lingua del documento, dal
mercato di quotazione o dalla denominazione delle voci: cerca la dicitura
esatta nella sezione "Basis of Preparation" (equivalenti: "Basis of
accounting", "Statement of compliance", "Criteri di redazione", "Principi
contabili applicati", "Nota 1 — Basis of presentation").

  "principioDichiarato": "IFRS" | "US GAAP" | "Locale"
  "prova": la citazione letterale della frase su cui ti sei basato.

Perché è dichiarativo e non inferenziale: un emittente europeo quotato negli
Stati Uniti deposita con la modulistica SEC un bilancio redatto secondo gli
IFRS. Le voci hanno allora nomi da modulistica americana e principi europei,
e qualunque conteggio di parole chiave sbaglia. La frase di conformità, invece,
è una sola e non è ambigua.

Se la sezione non compare nella porzione che stai leggendo, ometti del tutto
l'oggetto "schemaContabile": un principio non trovato è un dato assente, e
va lasciato assente. Non riempirlo con l'ipotesi più probabile.

════════════════════════════════════════════════════════════════════════
2 · VERIFICHE INTERNE PRIMA DI EMETTERE IL JSON
════════════════════════════════════════════════════════════════════════
Esegui queste tre verifiche. L'esito di ciascuna va riportato in "quadrature",
sempre: sia quando chiude, sia quando non chiude.

2.1 STATO PATRIMONIALE — Totale Attività = Passività + Patrimonio Netto.
2.2 CONTO ECONOMICO — la somma algebrica di tutti i ricavi (positivi) meno
    tutti i costi, oneri e imposte (negativi) deve dare l'Utile Netto.
    Le voci più spesso omesse, da cercare PRIMA di dichiarare un residuo:
    utile di pertinenza di terzi (minority interests), imposte differite,
    risultato delle attività cessate (discontinued operations), componenti
    rilevate a conto economico e non a OCI.

    QUALE UTILE ESPORRE — l'"utileNetto" del punto 1 DEVE essere il RISULTATO
    NETTO CONSOLIDATO (Consolidated Net Income), cioè quello COMPRENSIVO delle
    quote di pertinenza di terzi, non l'utile di pertinenza del gruppo.
    In un consolidato le due righe sono entrambe presenti e vicine:
      "Net income" / "Profit for the year"                → è questo
      "attributable to owners of the parent" / "del Gruppo" → NON è questo
    Se esponi l'utile di gruppo, la quadratura a valle fallisce di un importo
    esattamente pari alla quota di terzi, e il sistema segnala come corrotto un
    bilancio che è invece perfettamente in ordine. Se il prospetto riporta solo
    la quota di gruppo, esponila e dichiaralo in "note" scrivendo quale delle
    due righe hai usato: la distinzione va detta, mai lasciata implicita.
    Vale la stessa regola per il patrimonio netto: espone il TOTALE, comprese
    le quote di terzi (non controlling interests).
2.3 CE ↔ RENDICONTO — l'Utile Netto del Conto Economico deve coincidere con la
    riga di partenza del Rendiconto per metodo indiretto.

Se una verifica non chiude: cerca la voce mancante (strada a). Se non la trovi,
dichiara il residuo (strada b) e FERMATI lì.
ATTENZIONE sul punto 2.3 in particolare: un disallineamento fra utile del CE e
utile del Rendiconto è uno dei segnali forensi più significativi che questo
sistema possa ricevere. Se lo appiattisci aggiungendo voci di raccordo non
presenti nel documento, distruggi proprio il dato che serviva. Un
disallineamento reale va consegnato, non risolto.

Formato del blocco:
  "quadrature": [
    { "verifica": "SP" | "CE" | "CE_RF",
      "chiude": true | false,
      "scarto": 0,
      "vociAggiunte": ["<voci realmente trovate nel documento e aggiunte>"],
      "nota": "<che cosa hai cercato e che cosa hai concluso>" }
  ]

════════════════════════════════════════════════════════════════════════
3 · REGOLE TASSATIVE DI MAPPATURA FORENSE
════════════════════════════════════════════════════════════════════════
Servono a non inquinare il reddito operativo (EBIT/EBITDA). Entrambe hanno una
versione ingenua diffusa che produce un errore sempre nella stessa direzione —
margini più alti — e per questo sono scritte con la loro condizione di
applicazione, non come semplice destinazione.

3.1 CAPTIVE FINANCE — simmetria obbligatoria.
Gli oneri finanziari della divisione captive vanno mappati fra gli oneri
finanziari, MAI nel costo del venduto o fra le spese operative.
La simmetria è parte della regola: se togli dall'operativo il costo, DEVI
togliere anche i proventi finanziari della stessa divisione (captive finance
interest income, proventi da locazione finanziaria, commissioni di
finanziamento), riclassificandoli fra i proventi finanziari e sottraendoli dai
ricavi. Togliere il costo e lasciare il ricavo gonfia l'EBITDA due volte.
Se non riesci a isolare i proventi captive, NON spostare nemmeno i costi:
dichiaralo in "note" e lascia entrambi nell'operativo.

3.2 TFR E BENEFICI AI DIPENDENTI — split IAS 19.
NON mappare l'intero accantonamento TFR fra gli oneri finanziari. Va scomposto
secondo la natura delle componenti:
- SERVICE COST (quota maturata nell'esercizio per il lavoro prestato) →
  COSTI DEL PERSONALE, natura operativa. È retribuzione differita: toglierla
  dall'operativo sottostima il costo del lavoro e sovrastima l'EBITDA.
- INTEREST COST (unwinding of discount sul debito già maturato) →
  ONERI FINANZIARI.
- REMEASUREMENT / utili e perdite attuariali → riserva di patrimonio netto
  (OCI), MAI a conto economico.
Se il prospetto riporta un importo unico e la nota integrativa non consente di
separarlo, lascialo INTERO fra i costi del personale e segnalalo in "note": la
classificazione prudente è quella operativa.

3.3 GENERALI
- Ogni voce conserva il segno del prospetto d'origine; non normalizzare i segni
  per far tornare i totali.
- Non creare voci non presenti nel documento, con la sola eccezione dei totali
  auto-calcolati del punto 1, che vanno marcati.
- Un dato assente resta assente: null, non zero.
- Ogni riclassificazione che sposta un importo fra classi va dichiarata in
  "note" con origine, destinazione e importo.

════════════════════════════════════════════════════════════════════════
4 · STRUTTURA JSON OBBLIGATORIA
════════════════════════════════════════════════════════════════════════
Nessun testo introduttivo, nessun delimitatore markdown, nessun commento: solo
l'oggetto JSON.

{
  "schemaContabile": { "principioDichiarato": "IFRS" | "US GAAP" | "Locale", "prova": "<citazione>" },
  "esercizioCorrente": {
    "esercizio": "YYYY",
    "totaleAttivita": 0,
    "utileNetto": 0,
    "voci": [
      { "nome": "<denominazione originale>", "importo": 0, "classe": "<classe di riclassificazione>", "autoCalcolato": false }
    ],
    "aggregati": {},
    "quadrature": [],
    "note": []
  },
  "esercizioPrecedente": {
    "esercizio": "YYYY",
    "totaleAttivita": 0,
    "utileNetto": 0,
    "voci": [],
    "aggregati": {},
    "quadrature": [],
    "note": []
  }
}`;

/* ==========================================================================
   [4-ter] ESTRAZIONE NUMERICA AUTOMATICA — ai/estrazioneNumerica.js
   --------------------------------------------------------------------------
   Il contratto di estrazione non è più un testo da copiare a mano in un altro
   programma: è il system prompt che questa applicazione manda al modello
   quando in uno dei nove slot arriva un PDF invece di un JSON. Il prompt e il
   lettore erano già due metà dello stesso contratto; ora stanno anche nello
   stesso processo, e la versione non può divergere perché è una sola.

   Resta possibile caricare il JSON prodotto altrove: il percorso manuale non
   viene tolto, viene reso non necessario. Un file .json entra come prima, un
   file .pdf passa da qui e produce lo stesso oggetto.

   Sulla fusione delle porzioni: un bilancio non sta in una sola chiamata, e
   ogni porzione vede una parte del prospetto. Le voci si concatenano, i totali
   di radice si prendono dalla prima porzione che li dichiara — ma se due
   porzioni dichiarano lo STESSO totale con valori DIVERSI la discordanza non
   viene arbitrata in silenzio: si tiene il primo e si scrive la contraddizione
   in "quadrature", perché a valle il Gatekeeper deve poterla vedere. È lo
   stesso principio del punto 0 del contratto: uno scarto è un'informazione.
   ========================================================================== */

const MAX_TOKEN_ESTRAZIONE = 8000;

/** Ancoraggio per slot: quale prospetto leggere e a quale bilancio riferirlo. */
const NOME_PROSPETTO = { SP: "Stato Patrimoniale", CE: "Conto Economico", RF: "Rendiconto Finanziario" };

function istruzioneSlot(slot, blocco) {
  const prospetto = prospettoSlot(slot);
  const anno = annoDiSlot(slot);
  /* Due modi di ancorare le colonne, e la differenza non è di stile.
     Quando l'esercizio è già noto — l'operatore ha caricato il PDF dentro una
     casella precisa della serie — lo si impone, perché quel posto nella serie
     è già stato deciso. Quando invece il file è stato semplicemente trascinato
     nell'area, l'anno NON si indovina: lo si fa dichiarare al documento. È lo
     stesso dato che il contratto chiede già in "esercizio", e leggerlo dal
     prospetto costa una riga di prompt mentre stimarlo costa un'attribuzione
     sbagliata ogni volta che l'operatore carica i bilanci fuori ordine. */
  const ancoraggio = anno !== null
    ? `Bilancio di riferimento: esercizio di chiusura ${anno}.
Mappatura obbligatoria delle due colonne del documento:
  "esercizioCorrente"   = colonna di chiusura  → annualità ${anno}
  "esercizioPrecedente" = colonna comparativa  → annualità ${anno - 1}
Se le annualità stampate nel documento fossero diverse da queste, riporta quelle
stampate nel campo "esercizio" di ciascun ramo: il documento vince sull'attesa.`
    : `Bilancio di riferimento: quello che il documento stesso dichiara.
Mappatura obbligatoria delle due colonne del documento:
  "esercizioCorrente"   = colonna di CHIUSURA, l'annualità più recente esposta
  "esercizioPrecedente" = colonna COMPARATIVA, l'annualità immediatamente anteriore
In "esercizio" scrivi l'anno a quattro cifre letto sull'intestazione della
colonna (es. "2025"), non un'etichetta relativa e non una stima: se l'anno non è
leggibile in questa porzione lascia "esercizio" a null.`;
  return `RICHIESTA SPECIFICA DI QUESTA ESTRAZIONE
Prospetto da estrarre: ${NOME_PROSPETTO[prospetto]} (${prospetto}).
${ancoraggio}
Non invertire le due colonne: a valle la stessa annualità viene letta da due
bilanci diversi e il confronto serve a scoprire un restatement. Se le colonne
fossero scambiate il restatement apparirebbe dove non c'è e sparirebbe dove c'è.

Porzione ${blocco.indice} di ${blocco.totale}${blocco.stimato ? " (taglio stimato: gli intervalli di pagina sono approssimativi)" : ` — pagine ${blocco.paginaIniziale}-${blocco.paginaFinale} del documento originale`}.
Estrai SOLO ciò che questa porzione contiene davvero. Se il ${NOME_PROSPETTO[prospetto]}
non compare in questa porzione, restituisci i due rami con "voci" vuoto e i
totali a null: un ramo vuoto è corretto, un ramo inventato no.
Anche i totali di radice vanno riportati solo se leggibili in questa porzione.`;
}

/** Chiave di confronto per non duplicare la stessa voce vista in due porzioni. */
const chiaveVoce = (v) => `${normalizza(String(v?.nome ?? ""))}|${v?.importo ?? "null"}`;

/** Ramo vuoto conforme al contratto. */
const ramoVuoto = () => ({
  esercizio: null, totaleAttivita: null, utileNetto: null,
  voci: [], aggregati: {}, quadrature: [], note: [],
});

/**
 * Fonde il ramo di una porzione dentro l'accumulatore.
 * I totali non vengono sovrascritti: il primo dichiarato vince e un secondo
 * valore discorde viene registrato come contraddizione, non risolto.
 */
function fondiRamo(acc, nuovo, indiceBlocco) {
  if (!nuovo || typeof nuovo !== "object") return acc;

  if (acc.esercizio == null && nuovo.esercizio != null) acc.esercizio = String(nuovo.esercizio);

  for (const campo of ["totaleAttivita", "utileNetto"]) {
    const v = typeof nuovo[campo] === "number" && isFinite(nuovo[campo]) ? nuovo[campo] : null;
    if (v === null) continue;
    if (acc[campo] === null) { acc[campo] = v; acc._origineTotali[campo] = indiceBlocco; continue; }
    if (Math.abs(acc[campo] - v) > 0.5) {
      acc.quadrature.push({
        verifica: campo === "totaleAttivita" ? "SP" : "CE",
        esito: "discorde",
        residuo: acc[campo] - v,
        descrizione: `Il campo «${campo}» è stato dichiarato due volte con valori diversi: ${acc[campo]} nella porzione ${acc._origineTotali[campo]}, ${v} nella porzione ${indiceBlocco}. È stato mantenuto il primo. Una delle due letture è sbagliata e la differenza non è stata azzerata: va verificata sul documento originale.`,
      });
    }
  }

  if (Array.isArray(nuovo.voci)) {
    for (const v of nuovo.voci) {
      if (!v || v.nome == null) continue;
      const k = chiaveVoce(v);
      if (acc._chiavi.has(k)) continue;
      acc._chiavi.add(k);
      acc.voci.push({ ...v, porzione: indiceBlocco });
    }
  }
  if (nuovo.aggregati && typeof nuovo.aggregati === "object") {
    acc.aggregati = { ...nuovo.aggregati, ...acc.aggregati };
  }
  if (Array.isArray(nuovo.quadrature)) acc.quadrature.push(...nuovo.quadrature.filter(Boolean));
  if (Array.isArray(nuovo.note)) acc.note.push(...nuovo.note.filter(Boolean));
  return acc;
}

/** Toglie gli appoggi interni alla fusione prima di consegnare il ramo. */
function ripulisciRamo(acc) {
  const { _chiavi, _origineTotali, _schemaContabile, ...pulito } = acc;
  return pulito;
}

/**
 * Estrae il JSON numerico di un prospetto da un PDF, applicando il contratto
 * di estrazione come system prompt. Restituisce l'oggetto nella stessa forma
 * che avrebbe avuto il file esportato a mano dai moduli SP/CE/RF.
 *
 * @param {File} file        il PDF del bilancio
 * @param {string} slot      SP | CE | RF | *_t1 | *_t2
 * @param {Function} onProgresso  ({fase, blocco, totale}) → void
 */
async function estraiNumericoDaPdf(file, slot, onProgresso = () => {}) {
  onProgresso({ fase: "Suddivisione del PDF", blocco: 0, totale: 0 });
  const blocchi = await suddividiPdf(file);

  const corrente = { ...ramoVuoto(), _chiavi: new Set(), _origineTotali: {} };
  const precedente = { ...ramoVuoto(), _chiavi: new Set(), _origineTotali: {} };
  const porzioniPerse = [];

  for (const blocco of blocchi) {
    onProgresso({ fase: "Lettura del prospetto", blocco: blocco.indice, totale: blocchi.length });
    let testo;
    try {
      testo = await chiamataIA({
        system: PROMPT_ESTRAZIONE_NUMERICA,
        contenuto: [
          { type: "document", source: { type: "base64", media_type: "application/pdf", data: blocco.base64 } },
          { type: "text", text: istruzioneSlot(slot, blocco) },
        ],
        maxTokens: MAX_TOKEN_ESTRAZIONE,
      });
    } catch (err) {
      /* Una porzione persa non viene nascosta: entra nelle note del prospetto,
         perché l'assenza di una voce che stava lì è indistinguibile, a valle,
         da una voce che il bilancio non aveva. */
      porzioniPerse.push({ blocco: blocco.indice, errore: err?.message || String(err) });
      if (err?.definitivo) break;
      continue;
    }

    const json = parseJsonRobusto(testo);
    /* Il principio contabile è dichiarato una volta sola, nella nota sui
       criteri di redazione: la porzione che la contiene è una sola fra molte,
       e la prima dichiarazione trovata vale per l'intero documento. Le porzioni
       successive non la sovrascrivono — se due porzioni dichiarassero principi
       diversi si tratterebbe di due bilanci distinti, non di due letture. */
    if (json?.schemaContabile?.principioDichiarato && !corrente._schemaContabile) {
      corrente._schemaContabile = json.schemaContabile;
    }
    if (!json) {
      porzioniPerse.push({ blocco: blocco.indice, errore: "risposta non interpretabile come JSON" });
      continue;
    }
    fondiRamo(corrente, json.esercizioCorrente, blocco.indice);
    fondiRamo(precedente, json.esercizioPrecedente, blocco.indice);
  }

  if (porzioniPerse.length) {
    const avviso = `Estrazione incompleta: ${plurale(porzioniPerse.length, "porzione non letta", "porzioni non lette")} su ${blocchi.length} (${porzioniPerse.map((p) => `porzione ${p.blocco}: ${p.errore}`).join("; ")}). Le voci contenute in queste pagine non sono nel file: un totale che non quadra può dipendere da qui e non dal bilancio.`;
    corrente.note.push(avviso);
    precedente.note.push(avviso);
  }

  if (!corrente.voci.length && !precedente.voci.length) {
    throw new Error(
      `Nessuna voce di ${NOME_PROSPETTO[prospettoSlot(slot)]} riconosciuta nel PDF. Verificare che il file contenga il prospetto richiesto` +
      (porzioniPerse.length ? " — tutte le porzioni sono andate perse, quindi l'esito non dice nulla sul contenuto del documento." : ".")
    );
  }

  /* L'esercizio di chiusura: quello letto sul documento, se il documento lo
     dichiara; altrimenti quello imposto dalla casella in cui il PDF è stato
     caricato. Se nessuno dei due esiste il campo resta null e il file finirà
     in attesa di attribuzione, che è il modo onesto di dire «non lo so». */
  const annoAtteso = annoDiSlot(slot);
  if (corrente.esercizio == null && annoAtteso !== null) corrente.esercizio = String(annoAtteso);
  if (precedente.esercizio == null && corrente.esercizio != null) {
    const a = Number(String(corrente.esercizio).match(/(19|20)\d{2}/)?.[0]);
    if (Number.isFinite(a)) precedente.esercizio = String(a - 1);
  }
  const annoLetto = Number(String(corrente.esercizio ?? "").match(/(19|20)\d{2}/)?.[0]);

  return {
    /* Alla radice, non dentro un ramo d'esercizio: il principio contabile è
       una proprietà del bilancio, non di una delle sue due colonne. È qui che
       `riconosciPrincipio` viene a cercarlo. */
    schemaContabile: corrente._schemaContabile || null,
    esercizioCorrente: ripulisciRamo(corrente),
    esercizioPrecedente: ripulisciRamo(precedente),
    _estrazione: {
      contratto: VERSIONE_CONTRATTO_ESTRAZIONE,
      slot,
      prospetto: prospettoSlot(slot),
      bilancio: Number.isFinite(annoLetto) ? String(annoLetto) : bilancioSlot(slot),
      colonne: Number.isFinite(annoLetto) ? `${annoLetto} / ${annoLetto - 1}` : esercizioSlot(slot),
      annoDichiaratoDalDocumento: Number.isFinite(annoLetto) ? annoLetto : null,
      porzioni: blocchi.length,
      porzioniPerse: porzioniPerse.length,
      provider: configIA.provider,
      modello: configIA.modelli?.[configIA.provider] || MODELLI_PREDEFINITI?.[configIA.provider] || null,
      eseguitaIl: new Date().toISOString(),
      automatica: true,
    },
  };
}

/* ==========================================================================
   [4-bis] GATEKEEPER ALGEBRICO — domain/gatekeeper.js
   --------------------------------------------------------------------------
   Un controllo che precede tutto il resto. Prima che l'IA legga una sola riga
   e prima che si calcoli un solo indice, si verifica che i tre prospetti si
   parlino fra loro: se non quadrano, ogni analisi a valle lavorerebbe su un
   dato corrotto e produrrebbe un giudizio dall'aria autorevole e dal contenuto
   falso. Meglio fermarsi qui, dove l'errore ha un nome preciso.

   Le tre identità non sono opinioni: sono vincoli della partita doppia. Se una
   salta, non è l'azienda a essere rischiosa — è il file a essere sbagliato,
   e va corretto prima, non interpretato dopo.

   Una tolleranza esiste, ed è volutamente piccola: i riclassificati possono
   portarsi dietro arrotondamenti al migliaio. Si tollera lo 0,5% del totale
   attivo (con un minimo assoluto), non un centesimo di più: una tolleranza
   larga trasformerebbe il gatekeeper in un timbro che approva tutto.
   ========================================================================== */

/**
 * Riconosce se una riga appiattita appartiene all'esercizio comparativo.
 *
 * Il campo `periodo` prodotto dall'appiattitore non è sempre un marcatore
 * d'esercizio: quando la riga è un oggetto {nome, importo} — la forma di gran
 * lunga più diffusa nei riclassificati e in tutti gli export IFRS/US GAAP —
 * la chiave che porta il valore è «importo», e `periodo` vale «importo».
 * Fidarsi di quel campo significava dichiarare CORRENTE ogni riga di ogni
 * esercizio, comparativo compreso: la ricerca per sinonimi restituiva
 * indifferentemente il 2024 o il 2023, e l'identità veniva verificata fra due
 * anni diversi senza che nulla lo segnalasse.
 *
 * La regola qui è più prudente: il campo `periodo` vale solo se contiene
 * davvero un marcatore di comparativo; altrimenti decide il percorso, che porta
 * il ramo `esercizioPrecedente` da cui la riga proviene. Nel dubbio una riga
 * finisce nel comparativo e resta fuori dalla verifica dell'anno corrente:
 * è la direzione giusta in cui sbagliare, perché produce un «non verificabile»
 * e non un confronto fra numeri di esercizi diversi.
 */
function rigaEComparativa(riga) {
  // Il ramo d'esercizio, quando c'è, è l'unica autorità: viene dalla struttura
  // del file e non da un'inferenza sul nome.
  if (riga.periodoRamo === "precedente") return true;
  if (riga.periodoRamo === "corrente") return false;
  const p = riga.periodo ? ` ${normalizza(riga.periodo)} ` : "";
  if (p && MARCATORI_PRECEDENTE.some((m) => p.includes(` ${m} `))) return true;
  return MARCATORI_PRECEDENTE.some((m) => riga.percorsoNorm.includes(` ${m} `));
}

/**
 * Legge un valore da un JSON di bilancio già appiattito, per sinonimi.
 *
 * `escludiNorm` è l'antidoto alla trappola dei totali compositi. In un bilancio
 * IFRS la riga «Total equity and liabilities» contiene alla lettera sia
 * «total equity» sia «total liabilities»: senza esclusioni verrebbe letta come
 * patrimonio netto E come totale passivo, e in entrambi i casi con il valore
 * dell'intero stato patrimoniale. L'identità non risulterebbe «non
 * verificabile» — risulterebbe FALSA, che è l'esito peggiore: il gatekeeper
 * bloccherebbe un file corretto dichiarandolo corrotto.
 */
function valoreDa(indiceSlot, aliasNormalizzati, periodo = "corrente", escludiNorm = []) {
  let migliore = null;
  const vuoiComparativo = periodo === "precedente";
  for (const riga of indiceSlot) {
    if (escludiNorm.length && escludiNorm.some((e) => e && riga.percorsoNorm.includes(e))) continue;
    for (const a of aliasNormalizzati) {
      if (!riga.percorsoNorm.includes(a)) continue;
      if (rigaEComparativa(riga) !== vuoiComparativo) continue;
      if (!migliore || a.length > migliore.punteggio) migliore = { valore: riga.valore, punteggio: a.length, percorso: riga.percorso };
      break;
    }
  }
  return migliore ? migliore.valore : null;
}

/**
 * Costruisce l'indice appiattito di un singolo prospetto.
 *
 * I due rami d'esercizio vengono appiattiti SEPARATAMENTE e il periodo viene
 * stampigliato sulla riga dal ramo di provenienza. Non è un dettaglio: nella
 * forma {nome, importo} — quella di ogni riclassificato e di ogni estrazione
 * IFRS — la chiave che porta il valore è «importo», l'appiattitore la riconosce
 * come chiave di periodo e la sovrascrive a quella ereditata dal ramo. Il
 * risultato era che «esercizioPrecedente» spariva sia dal percorso sia dal
 * periodo, e ogni riga del comparativo si presentava alla ricerca come riga
 * dell'esercizio corrente: su un bilancio a due colonne il gatekeeper poteva
 * leggere il totale attivo del 2024 e il totale passivo del 2023 e dichiarare
 * corrotto un file perfettamente quadrato. Il ramo, qui, è l'unica autorità.
 */
function indicizzaProspetto(dati, slot) {
  if (!dati || typeof dati !== "object") return [];
  const righe = [];
  const aggiungi = (nodo, periodoRamo) => {
    for (const v of appiattisci(nodo)) {
      righe.push({ ...v, slot, periodoRamo, percorsoNorm: ` ${normalizza(`${v.percorso}`)} ` });
    }
  };
  for (const [ramo, periodo] of [["esercizioCorrente", "corrente"], ["esercizioPrecedente", "precedente"]]) {
    if (dati[ramo] && typeof dati[ramo] === "object") aggiungi(dati[ramo], periodo);
  }
  /* Quanto sta fuori dai due rami (formati più vecchi, tabelle a colonne) resta
     senza timbro e continua a essere classificato dal percorso, come prima. */
  const resto = {};
  for (const [k, v] of Object.entries(dati)) {
    if (k !== "esercizioCorrente" && k !== "esercizioPrecedente") resto[k] = v;
  }
  if (Object.keys(resto).length) aggiungi(resto, null);
  return righe;
}

/**
 * CONTRATTO DI RADICE — totali esposti fuori dagli array di voci.
 * -----------------------------------------------------------------------------
 * I moduli di riclassificazione espongono `totaleAttivita` e `utileNetto` come
 * campi propri di ciascun ramo d'esercizio, non come righe dentro `voci`. La
 * ragione è che il gatekeeper non deve andarli a cercare: cercarli significa
 * riconoscerli da un nome, e un nome può mancare, essere tradotto o coincidere
 * con quello di un aggregato intermedio. Un campo a posizione fissa non ha
 * nessuno di questi problemi.
 *
 * Perché la ricerca per alias non basta, in concreto: l'appiattitore generico
 * produce il percorso `totaleAttivita` in camelCase, mentre gli alias sono
 * scritti a parole separate («totale attivita»). Le due forme non si
 * corrispondono, e senza questo lettore i totali di radice resterebbero
 * invisibili proprio ai controlli per cui sono stati introdotti.
 *
 * Il contratto è additivo: se i campi mancano — file di formato precedente,
 * export parziale — si torna alla ricerca per alias e nulla si rompe.
 */
/**
 * POSTE DI BILANCIAMENTO — il difetto che un gatekeeper non può permettersi.
 * -----------------------------------------------------------------------------
 * Se l'estrattore, davanti a uno stato patrimoniale che non chiude, inserisce
 * una riga di importo pari allo scarto, il bilancio quadra e il gatekeeper
 * passa. Il file diventa formalmente perfetto e sostanzialmente muto: l'unico
 * segnale che l'ingestione doveva produrre è stato cancellato dal produttore
 * del file, spesso in buona fede e con l'intenzione di essere d'aiuto.
 *
 * Questo controllo esiste perché la quadratura ottenuta con un plug non è una
 * quadratura. Non blocca — la posta potrebbe essere una legittima voce
 * residuale del bilancio originale — ma la porta in superficie con il suo
 * importo, così che chi legge sappia che l'identità ha chiuso grazie a quella
 * riga e possa decidere se accettarla.
 */
const NOMI_DI_BILANCIAMENTO = /\b(quadratur|squadratur|bilanciament|plug\b|differenz[ae]\s+(tecnic|da\s+quadratur|residu)|residu[oi]\s+tecnic|posta\s+di\s+chiusur|balancing\s+(item|figure)|rounding\s+difference|to\s+balance\b)/i;

function postediBilanciamento(dati) {
  const trovate = [];
  for (const [ramo, periodo] of [["esercizioCorrente", "corrente"], ["esercizioPrecedente", "precedente"]]) {
    const voci = dati?.[ramo]?.voci;
    if (!Array.isArray(voci)) continue;
    for (const v of voci) {
      const nome = String(v?.nome ?? v?.voce ?? v?.descrizione ?? "");
      if (nome && NOMI_DI_BILANCIAMENTO.test(nome)) {
        trovate.push({ nome, importo: nSuite(v?.importo), periodo });
      }
    }
  }
  return trovate;
}

/** Totali dichiarati nel documento contro totali ricostruiti dall'estrattore. */
function totaliRicostruiti(dati) {
  const out = [];
  for (const [ramo, periodo] of [["esercizioCorrente", "corrente"], ["esercizioPrecedente", "precedente"]]) {
    const voci = dati?.[ramo]?.voci;
    if (!Array.isArray(voci)) continue;
    for (const v of voci) {
      const nome = String(v?.nome ?? v?.voce ?? "");
      if (v?.autoCalcolato === true || /\(auto[-\s]?calculated\)/i.test(nome)) {
        out.push({ nome, importo: nSuite(v?.importo), periodo });
      }
    }
  }
  return out;
}

/** Primo campo presente fra quelli indicati. Lettura per posizione, non per nome
 *  inferito: un campo a posizione fissa non si può tradurre, e quindi non si
 *  può perdere quando il bilancio è redatto in inglese. */
function campoStrutturale(oggetto, ...chiavi) {
  if (!oggetto || typeof oggetto !== "object") return null;
  for (const k of chiavi) {
    const v = nSuite(oggetto[k]);
    if (v !== null) return v;
  }
  return null;
}

/** Gli aggregati già calcolati dal modulo di riclassificazione, per ramo. */
function aggregatiRamo(dati, ramo = "esercizioCorrente") {
  const agg = dati?.[ramo]?.aggregati;
  return agg && typeof agg === "object" ? agg : {};
}

/**
 * Somma che esiste solo se TUTTI gli addendi esistono.
 * `sommaSuite` tollera i buchi, e va benissimo dove il risultato è un ordine di
 * grandezza; qui no. Un totale passivo ricomposto da tre classi su quattro non
 * è un totale più piccolo: è un numero sbagliato con l'aspetto di un totale, e
 * farebbe fallire l'identità patrimoniale su un bilancio perfettamente in
 * ordine. Meglio nessun valore — e un «non verificabile» onesto.
 */
function sommaCompleta(...xs) {
  const v = xs.map(nSuite);
  if (!v.length || v.some((x) => x === null)) return null;
  return v.reduce((a, b) => a + b, 0);
}

/**
 * Contratto di radice esteso.
 * Oltre a `totaleAttivita` e `utileNetto` — i due campi storici — si leggono qui
 * anche gli altri totali che i moduli di riclassificazione e gli estrattori
 * IFRS/US GAAP espongono alla radice del ramo d'esercizio. Sono tutti opzionali:
 * dove mancano si ricade sugli aggregati e, in ultima istanza, sui sinonimi.
 */
function contrattoRadice(dati) {
  const ramo = (chiave) => {
    const es = dati?.[chiave];
    if (!es || typeof es !== "object") {
      return { totaleAttivita: null, totalePassivita: null, patrimonioNetto: null, patrimonioTerzi: null,
        disponibilitaLiquide: null, cassaFinale: null, utileNetto: null, esercizio: null };
    }
    return {
      totaleAttivita: campoStrutturale(es, "totaleAttivita", "totaleAttivo", "totalAssets"),
      totalePassivita: campoStrutturale(es, "totalePassivita", "totalePassivo", "totalLiabilities"),
      patrimonioNetto: campoStrutturale(es, "patrimonioNetto", "totalePatrimonioNetto", "totalEquity"),
      patrimonioTerzi: campoStrutturale(es, "patrimonioTerzi", "patrimonioNettoTerzi", "interessiDiMinoranza", "nonControllingInterests", "minorityInterests"),
      disponibilitaLiquide: campoStrutturale(es, "disponibilitaLiquide", "cassaEquivalenti", "cashAndCashEquivalents"),
      cassaFinale: campoStrutturale(es, "cassaFinale", "disponibilitaLiquideFinali", "liquiditaFinale", "saldoFinaleCassa", "cashAtEndOfPeriod"),
      utileNetto: campoStrutturale(es, "utileNetto", "risultatoNetto", "netIncome", "netProfit"),
      esercizio: typeof es.esercizio === "string" ? es.esercizio : null,
    };
  };
  return { corrente: ramo("esercizioCorrente"), precedente: ramo("esercizioPrecedente") };
}

/**
 * VOCABOLARIO DEL GATEKEEPER — italiano e inglese sullo stesso piano.
 * -----------------------------------------------------------------------------
 * Un bilancio IFRS o US GAAP non ha meno identità contabili di un bilancio
 * civilistico: ha le stesse, scritte in un'altra lingua. Finché il vocabolario
 * era solo italiano il gatekeeper dichiarava «non verificabile» ciò che non
 * sapeva leggere, e un consolidato Ferrari perfettamente quadrato usciva in
 * stato «parziale» — un difetto del lettore raccontato come un difetto del file.
 *
 * I sinonimi inglesi sono qui accanto agli italiani perché la lingua del
 * documento non è un'informazione che il gatekeeper debba possedere in anticipo:
 * la verifica algebrica precede il routing e la mappatura tassonomica, e deve
 * funzionare prima che qualcuno abbia dichiarato sotto quale principio si legge.
 */
const ALIAS_GATEKEEPER = {
  attivoTotale: [
    "totale attivo", "totale attivita", "attivo totale", "totale generale attivo", "capitale investito",
    "total assets", "total current and non current assets", "total consolidated assets",
  ],
  /* Attenzione: «total liabilities and equity» NON è un totale passivo, è il
     totale generale dello stato patrimoniale, e vale quanto l'attivo. Sta nella
     sua chiave (`passivoEPatrimonio`) e viene tenuto fuori di qui dalle
     esclusioni: letto come passivo farebbe fallire l'identità per un importo
     pari al patrimonio netto. */
  passivoTotale: [
    "totale passivo", "totale passivita", "passivo totale", "totale debiti", "totale passivo consolidato",
    "total liabilities", "total current and non current liabilities", "total liabilities excluding equity",
  ],
  /* Il totale generale del passivo comprensivo del patrimonio netto: nei
     prospetti IFRS è spesso l'unica riga di chiusura esposta, e senza di essa
     l'identità patrimoniale resterebbe non verificabile pur essendo il bilancio
     quadrato per costruzione. */
  passivoEPatrimonio: [
    "total liabilities and equity", "total equity and liabilities",
    "total liabilities and shareholders equity", "total liabilities and stockholders equity",
    "totale passivo e patrimonio netto", "totale passivita e patrimonio netto",
  ],
  patrimonioNetto: [
    "patrimonio netto", "totale patrimonio netto", "capitale proprio", "mezzi propri",
    "total equity", "shareholders equity", "stockholders equity", "total shareholders equity",
    "total stockholders equity", "equity attributable to owners of the parent",
  ],
  /* Quote di pertinenza di terzi. Nei consolidati stanno dentro il patrimonio
     netto totale ma fuori dal patrimonio netto di gruppo, e a seconda di quale
     delle due righe l'estrattore ha letto la quadratura patrimoniale chiude o
     manca esattamente di questo importo. */
  patrimonioTerzi: [
    "non controlling interests", "noncontrolling interests", "minority interests", "minority interest",
    "patrimonio di terzi", "patrimonio netto di terzi", "interessi di minoranza", "quote di pertinenza di terzi",
  ],
  utileNetto: [
    "risultato netto", "utile netto", "utile netto consolidato", "utile d esercizio", "risultato d esercizio",
    "net income", "net profit", "profit for the year", "net income loss", "net earnings",
    "profit loss for the period", "net income attributable",
  ],
  utileRF: [
    "risultato netto", "utile netto", "utile d esercizio", "risultato prima delle imposte", "utile prima delle imposte",
    "net income", "net profit", "profit for the year", "net income loss", "profit before tax",
  ],
  utilePN: [
    "risultato d esercizio", "risultato netto", "utile d esercizio", "utile di periodo", "risultato dell esercizio",
    "net income", "net profit", "profit for the year", "net income loss",
  ],
  cassaFinaleRF: [
    "disponibilita liquide finali", "cassa finale", "saldo finale di cassa", "liquidita a fine",
    "disponibilita a fine periodo", "disponibilita liquide a fine esercizio",
    "cash and cash equivalents", "cash and cash equivalents at the end of the year",
    "cash and cash equivalents at end", "cash at end of period", "cash and cash equivalents at end of period",
  ],
  disponibilitaSP: [
    "disponibilita liquide", "cassa e banche", "cassa e disponibilita", "liquidita",
    "cash and cash equivalents", "cash and equivalents", "cash and short term deposits",
  ],
};

/**
 * SINONIMI SECONDARI — letture parziali, ammesse solo in mancanza del totale.
 * -----------------------------------------------------------------------------
 * «Equity attributable to owners of the parent» è patrimonio netto, ma è il
 * patrimonio netto DI GRUPPO: sta nel vocabolario perché su molti consolidati è
 * l'unica riga disponibile, e non deve però scavalcare «Total equity» quando
 * entrambe ci sono. La scelta per lunghezza del sinonimo, da sola, farebbe
 * esattamente il contrario: quel nome è lungo trentacinque caratteri e vincerebbe
 * sempre. Da qui la gerarchia esplicita — prima i totali, poi le quote di gruppo,
 * e la riconciliazione delle minoranze più a valle a colmare la differenza.
 */
const ALIAS_SECONDARI_GATEKEEPER = {
  patrimonioNetto: ["equity attributable to owners of the parent"],
};

/**
 * ESCLUSIONI — righe che contengono il sinonimo ma non sono quella voce.
 * Il confronto è per sottostringa sul percorso normalizzato, quindi ogni totale
 * composito «pesca» i sinonimi delle sue componenti. Queste sono le composizioni
 * che in un bilancio internazionale si incontrano davvero.
 */
/** Nomi leggibili delle letture del gatekeeper, per la traccia di provenienza. */
const ETICHETTE_LETTURE_GATEKEEPER = {
  attivo: "Totale attivo",
  passivo: "Totale passivo",
  passivoEPatrimonio: "Totale passivo e PN",
  patrimonioNetto: "Patrimonio netto",
  patrimonioTerzi: "Quote di terzi",
  utileCE: "Utile netto (CE)",
  utileRF: "Utile netto (RF)",
  utilePN: "Utile netto (prospetto PN)",
  cassaRF: "Cassa finale (RF)",
  cassaSP: "Disponibilità liquide (SP)",
};

const ESCLUSIONI_GATEKEEPER = {
  attivoTotale: ["held for sale", "destinate alla vendita", "net assets", "attivo netto"],
  passivoTotale: ["and equity", "and shareholders equity", "and stockholders equity", "and total equity",
    "equity and liabilities", "equity and total liabilities", "e patrimonio netto",
    "associated with assets held for sale"],
  patrimonioNetto: ["and liabilities", "liabilities and", "e passivo", "e passivita",
    "attributable to owners", "attributable to shareholders", "attributable to equity holders",
    "di gruppo", "di pertinenza del gruppo", "non controlling", "noncontrolling", "minority",
    "di terzi", "di pertinenza di terzi"],
  patrimonioTerzi: ["attributable to owners", "attributable to shareholders"],
  disponibilitaSP: ["restricted", "vincolate", "restricted cash"],
};

/**
 * Le tre identità contabili assolute.
 * Ciascuna restituisce: se è verificabile (ci sono i dati), se quadra, i due
 * membri dell'uguaglianza e lo scarto. "Non verificabile" non è "superata":
 * un'identità che non si può controllare resta un buco, segnalato come tale.
 */
function verificaIdentita(numerico) {
  const spI = indicizzaProspetto(numerico?.SP?.dati, "SP");
  const ceI = indicizzaProspetto(numerico?.CE?.dati, "CE");
  const rfI = indicizzaProspetto(numerico?.RF?.dati, "RF");
  const pnI = indicizzaProspetto(numerico?.PN?.dati, "PN");

  const escl = (k) => (ESCLUSIONI_GATEKEEPER[k] || []).map(normalizza);
  /* I sinonimi primari sono tutto il vocabolario meno le letture parziali. */
  const al = (k) => ALIAS_GATEKEEPER[k]
    .filter((a) => !(ALIAS_SECONDARI_GATEKEEPER[k] || []).includes(a))
    .map(normalizza);
  const alSecondari = (k) => (ALIAS_SECONDARI_GATEKEEPER[k] || []).map(normalizza);

  /* Il contratto di radice viene prima della ricerca per alias: è dichiarato
     dal produttore del file, mentre l'alias è un'inferenza sul nome. Quando
     entrambi ci sono e divergono vince il contratto, e la divergenza non va
     persa — è essa stessa un difetto del file, riportato più sotto. */
  const contrSP = contrattoRadice(numerico?.SP?.dati);
  const contrCE = contrattoRadice(numerico?.CE?.dati);
  const contrRF = contrattoRadice(numerico?.RF?.dati);

  /* Gli aggregati della riclassificazione sono la seconda fonte strutturale:
     sono numeri già calcolati dal modulo che ha prodotto il file, esposti sotto
     chiavi tecniche fisse. Non hanno lingua, non hanno sinonimi e non si possono
     confondere con una riga di dettaglio omonima. */
  const aggSP = aggregatiRamo(numerico?.SP?.dati);
  const aggCE = aggregatiRamo(numerico?.CE?.dati);
  const aggRF = aggregatiRamo(numerico?.RF?.dati);

  /* SCALA DI PRIORITÀ DELLE LETTURE — una sola regola, applicata a ogni voce.
     1 · contratto di radice   → dichiarato dal produttore del file
     2 · aggregati del modulo  → calcolato, ma per chiave tecnica e non per nome
     3 · sinonimi (it/en)      → inferenza sul nome della riga
     4 · sinonimi secondari    → letture dichiaratamente parziali (PN di gruppo)
     La ricerca testuale resta l'ultima risorsa e non la prima: è l'unico
     passaggio che dipende dalla lingua del documento, ed è quello che sui
     bilanci IFRS e US GAAP faceva uscire il gatekeeper in stato «parziale» su
     conti che quadravano perfettamente. */
  const fonti = {};
  const primo = (nome, ...candidati) => {
    for (const [etichetta, valore] of candidati) {
      const v = nSuite(valore);
      if (v !== null) { fonti[nome] = etichetta; return v; }
    }
    fonti[nome] = "assente";
    return null;
  };

  const attivoAlias = valoreDa(spI, al("attivoTotale"), "corrente", escl("attivoTotale"));
  const attivo = primo("attivo",
    ["contratto di radice (totaleAttivita)", contrSP.corrente.totaleAttivita],
    ["aggregati (totAttivoContab)", aggSP.totAttivoContab],
    ["aggregati (totImpieghi)", aggSP.totImpieghi],
    ["sinonimi", attivoAlias]);

  /* Totale passivo. L'aggregato non esiste come campo unico: si ricompone dalle
     quattro classi della riclassificazione, e solo se ci sono tutte e quattro. */
  const passivo = primo("passivo",
    ["contratto di radice (totalePassivita)", contrSP.corrente.totalePassivita],
    ["aggregati (passivo corrente + non corrente + debiti finanziari)",
      sommaCompleta(aggSP.passOpCorr, aggSP.debFinC, aggSP.passOpNC, aggSP.debFinNC)],
    ["sinonimi", valoreDa(spI, al("passivoTotale"), "corrente", escl("passivoTotale"))]);

  /* Totale generale del passivo: la riga di chiusura dei prospetti IFRS. */
  const passivoEPn = primo("passivoEPatrimonio",
    ["sinonimi", valoreDa(spI, al("passivoEPatrimonio"), "corrente")]);

  let pnSP = primo("patrimonioNetto",
    ["contratto di radice (patrimonioNetto)", contrSP.corrente.patrimonioNetto],
    ["aggregati (pn)", aggSP.pn],
    ["sinonimi", valoreDa(spI, al("patrimonioNetto"), "corrente", escl("patrimonioNetto"))],
    ["sinonimi (patrimonio netto di gruppo)", valoreDa(spI, alSecondari("patrimonioNetto"), "corrente")]);

  const patrimonioTerzi = primo("patrimonioTerzi",
    ["contratto di radice (patrimonioTerzi)", contrSP.corrente.patrimonioTerzi],
    ["sinonimi", valoreDa(spI, al("patrimonioTerzi"), "corrente", escl("patrimonioTerzi"))]) || 0;

  const utileCE = primo("utileCE",
    ["contratto di radice (utileNetto)", contrCE.corrente.utileNetto],
    ["aggregati (utileNetto)", aggCE.utileNetto],
    ["sinonimi", valoreDa(ceI, al("utileNetto"), "corrente")]);

  const utileRF = primo("utileRF",
    ["contratto di radice (utileNetto)", contrRF.corrente.utileNetto],
    ["aggregati (utileNetto)", aggRF.utileNetto],
    ["sinonimi", valoreDa(rfI, al("utileRF"), "corrente")]);

  /* Lo stato patrimoniale porta anch'esso l'utile per contratto: è un quarto
     testimone dello stesso numero, gratuito, e ignorarlo significherebbe non
     accorgersi di un file SP allineato a un esercizio diverso dagli altri due. */
  const utileSP = contrSP.corrente.utileNetto;
  const utilePN = primo("utilePN",
    ["sinonimi", valoreDa(pnI.concat(spI), al("utilePN"), "corrente")]);

  const cassaRF = primo("cassaRF",
    ["contratto di radice (cassaFinale)", contrRF.corrente.cassaFinale],
    ["aggregati", campoStrutturale(aggRF, "cassaFinale", "disponibilitaLiquideFinali", "liquiditaFinale", "cassaFine")],
    ["sinonimi", valoreDa(rfI, al("cassaFinaleRF"), "corrente")]);

  const cassaSP = primo("cassaSP",
    ["contratto di radice (disponibilitaLiquide)", contrSP.corrente.disponibilitaLiquide],
    ["aggregati (liq)", aggSP.liq],
    ["sinonimi", valoreDa(spI, al("disponibilitaSP"), "corrente", escl("disponibilitaSP"))]);

  // Tolleranza: 0,5% del totale attivo, minimo 1.000 unità di conto.
  const tolleranza = Math.max(1000, Math.abs(attivo || 0) * 0.005);
  const quadra = (a, b) => a !== null && b !== null && Math.abs(a - b) <= tolleranza;

  /* GATEKEEPER PARZIALE — le quote di terzi.
     Se il patrimonio netto letto è quello di GRUPPO, l'identità patrimoniale
     manca esattamente della quota di terzi: il bilancio è in ordine, è la
     lettura a essere parziale. La riassegnazione avviene a una sola
     condizione, ed è una condizione stretta: che l'equazione NON chiuda com'è
     e chiuda invece aggiungendo le quote di terzi. È la prova che quel numero
     mancava davvero e non è un aggiustamento comodo — se l'identità già chiude
     non si tocca nulla, perché sommare le quote di terzi a un patrimonio netto
     che le comprende già le conterebbe due volte e romperebbe una quadratura
     sana. */
  let pnComprendeTerzi = false;
  if (attivo !== null && passivo !== null && pnSP !== null && patrimonioTerzi !== 0
      && !quadra(attivo, passivo + pnSP)
      && quadra(attivo, passivo + pnSP + patrimonioTerzi)) {
    pnSP = pnSP + patrimonioTerzi;
    pnComprendeTerzi = true;
  }

  /* MEMBRO DESTRO DELL'IDENTITÀ PATRIMONIALE.
     La forma canonica è Passivo + Patrimonio netto. Quando però il prospetto
     espone solo la riga di chiusura — «Total equity and liabilities», tipica dei
     bilanci IFRS, dove le due componenti sono sommate a monte e non ricompaiono
     mai come totali separati — quella riga è l'identità stessa, già scritta dal
     redattore. Usarla non allenta il controllo: confronta comunque due letture
     indipendenti dello stesso stato patrimoniale, l'attivo e il totale a
     pareggio, e sostituisce un «non verificabile» che non era un difetto del
     bilancio ma del vocabolario con cui lo si leggeva. */
  const dxComposto = passivo !== null && pnSP !== null ? passivo + pnSP : null;
  const dxDaComposito = dxComposto === null && passivoEPn !== null;
  const membroDxSP = dxComposto !== null ? dxComposto : passivoEPn;

  /* Scostamenti fra il totale dichiarato per contratto e quello ricavato dai
     nomi delle voci. Non bloccano — il contratto resta autorevole — ma vanno
     detti: significano che dentro lo stesso file due letture dello stesso
     numero non coincidono, e prima o poi qualcuno leggerà quella sbagliata. */
  const contraddizioni = [];
  if (pnComprendeTerzi) {
    contraddizioni.push(`Patrimonio netto: la voce letta nello Stato Patrimoniale era quella di pertinenza del gruppo. L'identità patrimoniale non chiudeva per ${fmtImporto(patrimonioTerzi)}, importo pari alle quote di pertinenza di terzi, e chiude sommandole. Il patrimonio netto è stato quindi assunto al totale comprensivo delle minoranze. Il bilancio non è in errore: lo era la lettura. Verificare comunque che l'estrazione riporti il patrimonio netto TOTALE, perché ogni indicatore che usa il patrimonio netto (leva, ROE, copertura) sta lavorando sulla riga di gruppo.`);
  }
  /* Il secondo testimone non è la ricerca per alias — sui file della suite le
     voci sono oggetti {nome, importo} e il nome non finisce nel percorso
     appiattito, quindi l'alias non le raggiunge quasi mai. Il confronto utile
     è con l'aggregato calcolato dal modulo di riclassificazione, che è una
     lettura indipendente dello stesso numero. */
  const attivoAggregato = nSuite(aggSP?.totAttivoContab) ?? nSuite(aggSP?.totImpieghi) ?? attivoAlias;
  if (contrSP.corrente.totaleAttivita !== null && attivoAggregato !== null
      && Math.abs(contrSP.corrente.totaleAttivita - attivoAggregato) > tolleranza) {
    contraddizioni.push(`Totale attività: il campo dichiarato alla radice vale ${fmtImporto(contrSP.corrente.totaleAttivita)}, l'aggregato calcolato dal modulo di riclassificazione ${fmtImporto(attivoAggregato)}. È stato usato il campo dichiarato, ma le due letture dello stesso numero non coincidono e una delle due è sbagliata.`);
  }

  /* Poste di bilanciamento e totali ricostruiti su tutti e tre i prospetti.
     Non incidono sull'esito delle identità: incidono su quanto ci si può
     fidare del fatto che abbiano chiuso. */
  const plug = [];
  const ricostruiti = [];
  for (const [slot, dati] of [["SP", numerico?.SP?.dati], ["CE", numerico?.CE?.dati], ["RF", numerico?.RF?.dati]]) {
    for (const x of postediBilanciamento(dati)) plug.push({ ...x, slot });
    for (const x of totaliRicostruiti(dati)) ricostruiti.push({ ...x, slot });
  }
  for (const x of plug.filter((y) => y.periodo === "corrente")) {
    contraddizioni.push(`Posta di bilanciamento nel prospetto ${x.slot}: «${x.nome}» per ${fmtImporto(x.importo)}. Se un'identità chiude grazie a questa riga, non sta chiudendo: verifica che sia una voce reale del bilancio originale e non un residuo inserito per far quadrare i totali.`);
  }
  for (const x of ricostruiti.filter((y) => y.periodo === "corrente")) {
    contraddizioni.push(`Totale ricostruito nel prospetto ${x.slot}: «${x.nome}» (${fmtImporto(x.importo)}) non era dichiarato nel documento ed è stato calcolato dall'estrattore. È una prova più debole di un totale scritto in bilancio.`);
  }

  const utileAggregato = nSuite(aggCE?.utileNetto);
  if (contrCE.corrente.utileNetto !== null && utileAggregato !== null
      && Math.abs(contrCE.corrente.utileNetto - utileAggregato) > tolleranza) {
    contraddizioni.push(`Utile netto nel Conto Economico: il campo dichiarato alla radice vale ${fmtImporto(contrCE.corrente.utileNetto)}, l'aggregato del modulo ${fmtImporto(utileAggregato)}.`);
  }

  /* Terzo testimone dello stato patrimoniale: quando il prospetto espone sia le
     due componenti sia la riga di chiusura, le due letture devono coincidere.
     Se divergono l'identità è stata verificata sulla forma canonica — ma il file
     contiene comunque due versioni dello stesso totale, e va detto. */
  if (dxComposto !== null && passivoEPn !== null && Math.abs(dxComposto - passivoEPn) > tolleranza) {
    contraddizioni.push(`Chiusura dello Stato Patrimoniale: passivo più patrimonio netto vale ${fmtImporto(dxComposto)}, mentre la riga di totale generale del prospetto («totale passivo e patrimonio netto») vale ${fmtImporto(passivoEPn)}. È stata usata la somma delle componenti, ma le due letture dello stesso totale non coincidono.`);
  }

  /* Quali letture mancano DAVVERO. Non tutte le assenze sono buchi: se il
     prospetto espone passivo e patrimonio netto separati, la riga di chiusura
     composita non serve e la sua assenza non è una lacuna. Elencare anche quelle
     riempirebbe l'avvertenza di rumore e le toglierebbe ogni valore diagnostico. */
  const lettureMancanti = [];
  if (attivo === null) lettureMancanti.push("totale attivo");
  if (dxComposto === null && passivoEPn === null) {
    if (passivo === null) lettureMancanti.push("totale passivo");
    if (pnSP === null) lettureMancanti.push("patrimonio netto");
  }
  if (utileCE === null) lettureMancanti.push("utile netto (Conto Economico)");
  if (utileRF === null && utilePN === null && utileSP === null) lettureMancanti.push("utile netto come riscontro (Rendiconto / Prospetto PN / SP)");
  if (cassaRF === null) lettureMancanti.push("saldo finale di cassa (Rendiconto)");
  if (cassaSP === null) lettureMancanti.push("disponibilità liquide (Stato Patrimoniale)");

  return {
    tolleranza,
    contratto: { SP: contrSP, CE: contrCE, RF: contrRF },
    contraddizioni,
    bilanciamenti: plug,
    ricostruiti,
    /* Provenienza di ogni lettura. Serve a rendere ispezionabile il gatekeeper:
       davanti a un «non verificabile» si vede subito se la voce mancava davvero
       o se è stata cercata nel posto sbagliato. */
    fonti,
    lettureMancanti,
    identita: [
      {
        id: "quadratura_sp",
        nome: "Attività = Passività + Patrimonio Netto",
        spiega: "L'equazione fondamentale dello stato patrimoniale. Se non chiude, il prospetto non è bilanciato.",
        verificabile: attivo !== null && membroDxSP !== null,
        membroSx: attivo, membroDx: membroDxSP,
        etichettaSx: "Totale attivo",
        etichettaDx: dxDaComposito
          ? "Totale passivo e patrimonio netto (riga di chiusura del prospetto)"
          : pnComprendeTerzi
            ? "Totale passivo + Patrimonio netto (comprese le quote di terzi)"
            : "Totale passivo + Patrimonio netto",
        quadra: quadra(attivo, membroDxSP),
        scarto: attivo !== null && membroDxSP !== null ? attivo - membroDxSP : null,
        dettaglio: { passivo, patrimonioNetto: pnSP, passivoEPatrimonio: passivoEPn, quoteTerzi: patrimonioTerzi },
      },
      {
        id: "utile_coerente",
        nome: "Utile netto: Conto Economico = Rendiconto Finanziario = Prospetto PN",
        spiega: "Lo stesso utile deve comparire come risultato del conto economico, come riga di partenza del rendiconto finanziario indiretto e come incremento nel prospetto delle variazioni di patrimonio netto.",
        verificabile: utileCE !== null && (utileRF !== null || utilePN !== null || utileSP !== null),
        membroSx: utileCE,
        membroDx: utileRF !== null ? utileRF : (utilePN !== null ? utilePN : utileSP),
        etichettaSx: "Utile da Conto Economico",
        etichettaDx: utileRF !== null ? "Utile a partenza del Rendiconto" : (utilePN !== null ? "Utile nel Prospetto PN" : "Utile dichiarato nello Stato Patrimoniale"),
        quadra: (utileRF === null || quadra(utileCE, utileRF))
          && (utilePN === null || quadra(utileCE, utilePN))
          && (utileSP === null || quadra(utileCE, utileSP))
          && (utileRF !== null || utilePN !== null || utileSP !== null),
        scarto: utileCE !== null && utileRF !== null ? utileCE - utileRF
          : (utileCE !== null && utilePN !== null ? utileCE - utilePN
            : (utileCE !== null && utileSP !== null ? utileCE - utileSP : null)),
        dettaglio: { ce: utileCE, rf: utileRF, pn: utilePN, sp: utileSP },
      },
      {
        id: "cassa_coerente",
        nome: "Saldo finale di cassa (Rendiconto) = Disponibilità liquide (Stato Patrimoniale)",
        spiega: "La cassa a cui approda il rendiconto finanziario deve coincidere con la cassa iscritta nello stato patrimoniale alla stessa data.",
        verificabile: cassaRF !== null && cassaSP !== null,
        membroSx: cassaRF, membroDx: cassaSP,
        etichettaSx: "Saldo finale di cassa (RF)", etichettaDx: "Disponibilità liquide (SP)",
        quadra: quadra(cassaRF, cassaSP),
        scarto: cassaRF !== null && cassaSP !== null ? cassaRF - cassaSP : null,
      },
    ],
  };
}

/**
 * GATEKEEPER — il verdetto che decide se l'ingestione può proseguire.
 * Tre esiti:
 *   corrotto → almeno un'identità verificabile è fallita. L'ingestione si
 *              blocca: "Dato Corrotto" con l'identità che non torna e lo scarto.
 *   parziale → nessuna fallita, ma qualcuna non verificabile per dati mancanti.
 *              Si prosegue, con l'avvertenza che il controllo è incompleto.
 *   superato → tutte verificate e quadrate.
 */
function gatekeeperAlgebrico(numerico) {
  const presenti = ["SP", "CE", "RF"].filter((s) => numerico?.[s]?.dati);
  if (!presenti.length) {
    return { stato: "assente", bloccante: false, messaggio: "Nessun prospetto numerico caricato: il gatekeeper non ha nulla da verificare.", identita: [], verificateIl: new Date().toISOString() };
  }

  const { identita, tolleranza, contraddizioni, contratto, bilanciamenti, ricostruiti, fonti, lettureMancanti } = verificaIdentita(numerico);
  const fallite = identita.filter((i) => i.verificabile && !i.quadra);
  const nonVerificabili = identita.filter((i) => !i.verificabile);

  let stato, bloccante, messaggio;
  if (fallite.length) {
    stato = "corrotto"; bloccante = true;
    const prima = fallite[0];
    messaggio = `Dato Corrotto — ${prima.nome}: ${fmtImporto(prima.membroSx)} contro ${fmtImporto(prima.membroDx)}, scarto ${fmtImporto(Math.abs(prima.scarto))} (oltre la tolleranza di ${fmtImporto(tolleranza)}). L'ingestione è bloccata: correggi il riclassificato prima di procedere.`;
  } else if (nonVerificabili.length) {
    stato = "parziale"; bloccante = false;
    /* Dire QUALI letture mancano, e non solo che il controllo è incompleto: senza
       questo, di fronte a un bilancio che quadra ma esce «parziale», non c'è modo
       di distinguere una voce davvero assente dal file da una voce presente che
       il lettore non ha saputo riconoscere. */
    const assenti = lettureMancanti || [];
    messaggio = `Gatekeeper superato sui dati disponibili, ma ${plurale(nonVerificabili.length, "identità non è verificabile", "identità non sono verificabili")} per voci mancanti: ${nonVerificabili.map((i) => i.nome.split(":")[0].split("=")[0].trim()).join("; ")}.`
      + (assenti.length ? ` Letture non trovate nei riclassificati: ${assenti.join(", ")}.` : "")
      + " Il controllo è incompleto.";
  } else {
    stato = "superato"; bloccante = false;
    messaggio = "Gatekeeper superato: le tre identità contabili quadrano. I dati sono internamente coerenti.";
  }

  return { stato, bloccante, messaggio, tolleranza, identita, contraddizioni, contratto, bilanciamenti, ricostruiti, fonti, lettureMancanti, verificateIl: new Date().toISOString() };
}

/* ==========================================================================
   [4-ter] MAPPATURA TASSONOMICA — domain/tassonomia.js
   --------------------------------------------------------------------------
   IFRS e US GAAP chiamano cose uguali con nomi diversi e cose diverse con nomi
   uguali. Prima che l'IA faccia il routing, i JSON in entrata vengono
   normalizzati su un piano dei conti proprietario: così le fasi a valle non
   devono sapere sotto quale principio è redatto il bilancio, e un confronto fra
   un'azienda IFRS e una US GAAP diventa lecito.

   La normalizzazione non distrugge l'originale: ogni voce mappata conserva il
   nome di partenza e il principio da cui proviene. Una mappatura che si
   nasconde è una mappatura che non si può contestare.
   ========================================================================== */

/**
 * PIANO DEI CONTI PROPRIETARIO
 * Ogni conto elenca i sinonimi nei due principi. Le divergenze vere — non
 * lessicali ma sostanziali — sono annotate: sono i punti in cui la
 * normalizzazione compie una scelta, e va detto.
 */
const PIANO_CONTI = [
  { id: "ricavi", label: "Ricavi netti", ifrs: ["revenue", "revenue from contracts with customers", "ricavi delle vendite"], usgaap: ["net sales", "total revenues", "net revenues"], prospetto: "CE" },
  { id: "costoVenduto", label: "Costo del venduto", ifrs: ["cost of sales"], usgaap: ["cost of goods sold", "cogs", "cost of revenue"], prospetto: "CE" },
  { id: "utileNetto", label: "Risultato netto", ifrs: ["profit for the year", "profit attributable to owners"], usgaap: ["net income", "net earnings"], prospetto: "CE" },
  { id: "rimanenze", label: "Rimanenze", ifrs: ["inventories"], usgaap: ["inventory", "inventories net"], prospetto: "SP",
    nota: "US GAAP ammette il LIFO, vietato in IFRS: un magazzino a LIFO non è confrontabile con uno a FIFO senza la riserva LIFO, che va cercata a parte." },
  { id: "creditiClienti", label: "Crediti verso clienti", ifrs: ["trade receivables"], usgaap: ["accounts receivable", "receivables net"], prospetto: "SP" },
  { id: "immobilizzazioni", label: "Immobilizzazioni materiali", ifrs: ["property plant and equipment"], usgaap: ["property plant and equipment net", "fixed assets"], prospetto: "SP" },
  { id: "avviamento", label: "Avviamento", ifrs: ["goodwill"], usgaap: ["goodwill"], prospetto: "SP",
    nota: "In US GAAP l'avviamento si può ammortizzare (privately held); in IFRS mai, solo impairment. La voce esiste in entrambi ma la sua dinamica no." },
  { id: "immateriali", label: "Immobilizzazioni immateriali", ifrs: ["intangible assets", "development costs"], usgaap: ["intangible assets net", "capitalized software"], prospetto: "SP",
    nota: "IFRS impone di capitalizzare i costi di sviluppo che soddisfano i criteri; US GAAP di norma li spesa. La stessa spesa può stare all'attivo sotto un principio e a conto economico sotto l'altro." },
  { id: "debitiFinanziari", label: "Debiti finanziari", ifrs: ["borrowings", "lease liabilities"], usgaap: ["long term debt", "short term borrowings", "notes payable"], prospetto: "SP",
    nota: "Dopo IFRS 16 quasi tutti i leasing operativi stanno fra i debiti finanziari IFRS; in US GAAP (ASC 842) restano distinti fra finance e operating lease. La leva non è confrontabile senza rettifica." },
  { id: "patrimonioNetto", label: "Patrimonio netto", ifrs: ["total equity", "equity attributable to owners"], usgaap: ["stockholders equity", "shareholders equity"], prospetto: "SP" },
  { id: "attivoTotale", label: "Totale attivo", ifrs: ["total assets"], usgaap: ["total assets"], prospetto: "SP" },
  { id: "flussoOperativo", label: "Flusso di cassa operativo", ifrs: ["net cash from operating activities", "cash generated from operations"], usgaap: ["net cash provided by operating activities", "cash flow from operations"], prospetto: "RF" },
];

/**
 * Riporta una dicitura di conformità alla forma usata dal piano dei conti.
 * Il modello scrive quello che ha letto — "International Financial Reporting
 * Standards as issued by the IASB", "U.S. GAAP", "OIC" — e qui si riduce alle
 * tre etichette che il resto del programma sa trattare.
 */
function normalizzaPrincipioDichiarato(grezzo) {
  if (typeof grezzo !== "string") return null;
  const t = normalizza(grezzo);
  if (!t) return null;
  if (t.includes("us gaap") || t.includes("u s gaap") || t.includes("usgaap")
      || t.includes("united states generally accepted") || t.includes("fasb")) return "US GAAP";
  if (t.includes("ifrs") || t.includes("international financial reporting")
      || t.includes("ias") || t.includes("iasb")) return "IFRS";
  if (t.includes("locale") || t.includes("local gaap") || t.includes("oic")
      || t.includes("codice civile") || t.includes("principi contabili nazionali")) return "Locale";
  return null;
}

/** Ordine di interrogazione degli slot: prima i tre prospetti del bilancio
 *  corrente, poi le annualità precedenti, che possono essere state redatte
 *  sotto un principio diverso e non fanno testo per l'esercizio in corso. */
const ordineSlotPrincipio = (k) => {
  const i = ["SP", "CE", "RF"].indexOf(String(k).split("_")[0]);
  const eta = String(k).includes("_t2") ? 2 : String(k).includes("_t1") ? 1 : 0;
  return eta * 10 + (i < 0 ? 9 : i);
};

/**
 * Riconosce il principio contabile.
 *
 * Prima strada: la dichiarazione esplicita che l'estrattore ha copiato dalla
 * "Basis of Preparation" (contratto v4). È una frase scritta dal redattore del
 * bilancio, e su cosa applica il redattore non c'è inferenza da fare.
 *
 * Seconda strada, solo se la prima non ha prodotto nulla: il conteggio dei
 * marcatori lessicali. Resta come ripiego per i JSON prodotti dai moduli SP,
 * CE e RF o dai contratti precedenti alla v4, che il campo non lo portano. Il
 * suo limite è noto ed è la ragione per cui non viene più per prima: un
 * emittente europeo che deposita con la modulistica SEC — Ferrari N.V. è il
 * caso che ha fatto emergere il problema — usa nomi di voce americani su un
 * bilancio IFRS, e il conteggio lo attribuisce agli US GAAP con sicurezza.
 */
function riconosciPrincipio(numerico) {
  const chiavi = Object.keys(numerico || {}).sort((a, b) => ordineSlotPrincipio(a) - ordineSlotPrincipio(b));
  for (const slot of chiavi) {
    const dichiarazione = numerico?.[slot]?.dati?.schemaContabile;
    const principio = normalizzaPrincipioDichiarato(dichiarazione?.principioDichiarato);
    if (!principio) continue;
    return {
      principio,
      confidenza: "alta",
      origine: "dichiarato",
      slot,
      prova: typeof dichiarazione.prova === "string" ? dichiarazione.prova : null,
      segnaliUsGaap: null,
      segnaliIfrs: null,
    };
  }

  const testo = normalizza(JSON.stringify(numerico || {}));
  const segnaliUsGaap = ["net sales", "cost of goods sold", "stockholders equity", "net income", "10 k", "us gaap", "asc "].filter((s) => testo.includes(normalizza(s))).length;
  const segnaliIfrs = ["revenue from contracts", "profit for the year", "ifrs", "borrowings", "20 f", "trade receivables"].filter((s) => testo.includes(normalizza(s))).length;
  const base = { origine: "dedotto", slot: null, prova: null, segnaliUsGaap, segnaliIfrs };
  /* La confidenza del ripiego non sale mai oltre "media": il conteggio può
     essere netto ed essere comunque sbagliato, ed è esattamente ciò che
     succede sui bilanci ibridi. */
  if (segnaliUsGaap > segnaliIfrs) return { ...base, principio: "US GAAP", confidenza: segnaliUsGaap >= 2 ? "media" : "bassa" };
  if (segnaliIfrs > segnaliUsGaap) return { ...base, principio: "IFRS", confidenza: segnaliIfrs >= 2 ? "media" : "bassa" };
  return { ...base, principio: "indeterminato", confidenza: "bassa" };
}

/**
 * Normalizza i JSON in entrata sul piano dei conti proprietario.
 * @returns mappa { idConto → { valore, origine, principio } } più il registro
 *          delle divergenze rilevanti e l'elenco delle voci non mappate.
 */
function mappaTassonomia(numerico) {
  const principio = riconosciPrincipio(numerico);
  const conti = {};
  const divergenze = [];
  const nonMappate = [];

  for (const conto of PIANO_CONTI) {
    const slotI = indicizzaProspetto(numerico?.[conto.prospetto]?.dati, conto.prospetto);
    const alias = [...conto.ifrs, ...conto.usgaap].map(normalizza);
    let trovato = null, ramoOrigine = null;
    for (const riga of slotI) {
      for (const a of alias) {
        if (!riga.percorsoNorm.includes(a)) continue;
        if (!trovato || a.length > trovato.punteggio) {
          trovato = { valore: riga.valore, punteggio: a.length, percorso: riga.percorso };
          ramoOrigine = conto.ifrs.map(normalizza).some((x) => riga.percorsoNorm.includes(x)) ? "IFRS" : "US GAAP";
        }
        break;
      }
    }
    if (trovato) {
      conti[conto.id] = { label: conto.label, valore: trovato.valore, origine: trovato.percorso, ramo: ramoOrigine };
      if (conto.nota) divergenze.push({ conto: conto.id, label: conto.label, nota: conto.nota, valore: trovato.valore });
    } else {
      nonMappate.push({ conto: conto.id, label: conto.label, prospetto: conto.prospetto });
    }
  }

  return {
    principio, conti,
    // Le divergenze rilevanti si mostrano solo se toccano voci effettivamente
    // presenti: avvertire su un LIFO quando non c'è magazzino è rumore.
    divergenze,
    nonMappate,
    contiMappati: Object.keys(conti).length,
    contiTotali: PIANO_CONTI.length,
    normalizzatoIl: new Date().toISOString(),
  };
}

/* --------------------------------------------------------------------------
   INDICATORI
   Ogni indicatore dichiara la formula e le componenti effettivamente usate:
   la scheda di dettaglio in dashboard le mostra così come sono, senza
   arrotondamenti nascosti. Se manca una componente l'indicatore non viene
   stimato: resta indisponibile e la direttrice che ne dipende diventa
   "non determinabile". Un indicatore inventato è peggio di un indicatore
   assente, perché sembra vero.
   -------------------------------------------------------------------------- */

const GIORNI = 365;
const rapporto = (a, b) => (a === null || b === null || !isFinite(a) || !isFinite(b) || b === 0 ? null : a / b);
const variazionePct = (ora, prima) => (ora === null || prima === null || prima === 0 ? null : ((ora - prima) / Math.abs(prima)) * 100);

function indicatore(id, label, unita, valore, precedente, formula, componenti) {
  const disponibile = valore !== null && isFinite(valore);
  return {
    id, label, unita,
    valore: disponibile ? valore : null,
    precedente: precedente !== null && isFinite(precedente) ? precedente : null,
    variazione: disponibile ? variazionePct(valore, precedente) : null,
    delta: disponibile && precedente !== null ? valore - precedente : null,
    formula, componenti, disponibile,
  };
}

function calcolaIndicatori(voci) {
  const v = voci;
  const usa = (...chiavi) => chiavi.map((k) => ({ voce: k, percorso: v[k]?.percorso || null, corrente: v[k]?.corrente ?? null, precedente: v[k]?.precedente ?? null }));

  const margineEbitda = indicatore("margine_ebitda", "Margine EBITDA", "%",
    rapporto(v.ebitda.corrente, v.ricavi.corrente) !== null ? rapporto(v.ebitda.corrente, v.ricavi.corrente) * 100 : null,
    rapporto(v.ebitda.precedente, v.ricavi.precedente) !== null ? rapporto(v.ebitda.precedente, v.ricavi.precedente) * 100 : null,
    "EBITDA ÷ ricavi netti", usa("ebitda", "ricavi"));

  const margineEbit = indicatore("margine_ebit", "Margine EBIT", "%",
    rapporto(v.ebit.corrente, v.ricavi.corrente) !== null ? rapporto(v.ebit.corrente, v.ricavi.corrente) * 100 : null,
    rapporto(v.ebit.precedente, v.ricavi.precedente) !== null ? rapporto(v.ebit.precedente, v.ricavi.precedente) * 100 : null,
    "EBIT ÷ ricavi netti", usa("ebit", "ricavi"));

  const crescitaRicavi = indicatore("crescita_ricavi", "Crescita dei ricavi", "%",
    variazionePct(v.ricavi.corrente, v.ricavi.precedente), null,
    "(ricavi − ricavi esercizio precedente) ÷ ricavi esercizio precedente", usa("ricavi"));

  const crescitaMagazzino = indicatore("crescita_magazzino", "Crescita delle rimanenze", "%",
    variazionePct(v.rimanenze.corrente, v.rimanenze.precedente), null,
    "(rimanenze − rimanenze esercizio precedente) ÷ rimanenze esercizio precedente", usa("rimanenze"));

  const crescitaCrediti = indicatore("crescita_crediti", "Crescita dei crediti verso clienti", "%",
    variazionePct(v.creditiClienti.corrente, v.creditiClienti.precedente), null,
    "(crediti − crediti esercizio precedente) ÷ crediti esercizio precedente", usa("creditiClienti"));

  const dso = indicatore("dso", "Giorni medi di incasso (DSO)", "giorni",
    rapporto(v.creditiClienti.corrente, v.ricavi.corrente) !== null ? rapporto(v.creditiClienti.corrente, v.ricavi.corrente) * GIORNI : null,
    rapporto(v.creditiClienti.precedente, v.ricavi.precedente) !== null ? rapporto(v.creditiClienti.precedente, v.ricavi.precedente) * GIORNI : null,
    "(crediti verso clienti ÷ ricavi netti) × 365", usa("creditiClienti", "ricavi"));

  const baseAcquisti = v.acquisti.corrente !== null ? "acquisti" : "ricavi";
  const dpo = indicatore("dpo", "Giorni medi di pagamento (DPO)", "giorni",
    rapporto(v.debitiFornitori.corrente, v[baseAcquisti].corrente) !== null ? rapporto(v.debitiFornitori.corrente, v[baseAcquisti].corrente) * GIORNI : null,
    rapporto(v.debitiFornitori.precedente, v[baseAcquisti].precedente) !== null ? rapporto(v.debitiFornitori.precedente, v[baseAcquisti].precedente) * GIORNI : null,
    `(debiti verso fornitori ÷ ${baseAcquisti === "acquisti" ? "costo del venduto" : "ricavi netti, in mancanza del costo del venduto"}) × 365`,
    usa("debitiFornitori", baseAcquisti));

  const dio = indicatore("dio", "Giorni di giacenza del magazzino (DIO)", "giorni",
    rapporto(v.rimanenze.corrente, v[baseAcquisti].corrente) !== null ? rapporto(v.rimanenze.corrente, v[baseAcquisti].corrente) * GIORNI : null,
    rapporto(v.rimanenze.precedente, v[baseAcquisti].precedente) !== null ? rapporto(v.rimanenze.precedente, v[baseAcquisti].precedente) * GIORNI : null,
    `(rimanenze ÷ ${baseAcquisti === "acquisti" ? "costo del venduto" : "ricavi netti"}) × 365`, usa("rimanenze", baseAcquisti));

  const ciclo = indicatore("ciclo_circolante", "Ciclo del circolante", "giorni",
    dso.disponibile && dio.disponibile && dpo.disponibile ? dso.valore + dio.valore - dpo.valore : null,
    dso.precedente !== null && dio.precedente !== null && dpo.precedente !== null ? dso.precedente + dio.precedente - dpo.precedente : null,
    "DSO + DIO − DPO", usa("creditiClienti", "rimanenze", "debitiFornitori"));

  const leva = indicatore("leva_finanziaria", "Leva finanziaria (PFN ÷ EBITDA)", "x",
    rapporto(v.pfn.corrente, v.ebitda.corrente),
    rapporto(v.pfn.precedente, v.ebitda.precedente),
    "posizione finanziaria netta ÷ EBITDA", usa("pfn", "ebitda"));

  const costoDebito = indicatore("costo_debito", "Costo apparente del debito", "%",
    rapporto(v.oneriFinanziari.corrente, v.debitiFinanziari.corrente) !== null ? rapporto(v.oneriFinanziari.corrente, v.debitiFinanziari.corrente) * 100 : null,
    rapporto(v.oneriFinanziari.precedente, v.debitiFinanziari.precedente) !== null ? rapporto(v.oneriFinanziari.precedente, v.debitiFinanziari.precedente) * 100 : null,
    "oneri finanziari ÷ debiti finanziari", usa("oneriFinanziari", "debitiFinanziari"));

  /* Qualità dell'utile: quanto dell'utile dichiarato è arrivato in cassa.
     È l'indicatore che smaschera più in fretta i ricavi anticipati: un utile che
     non diventa mai flusso operativo è un utile che vive solo nelle stime. */
  const qualitaUtile = indicatore("qualita_utile", "Copertura di cassa dell'utile", "x",
    rapporto(v.flussoOperativo.corrente, v.risultatoNetto.corrente),
    rapporto(v.flussoOperativo.precedente, v.risultatoNetto.precedente),
    "flusso di cassa operativo ÷ risultato netto", usa("flussoOperativo", "risultatoNetto"));

  const incidenzaMagazzino = indicatore("incidenza_magazzino", "Incidenza delle rimanenze sull'attivo", "%",
    rapporto(v.rimanenze.corrente, v.attivoTotale.corrente) !== null ? rapporto(v.rimanenze.corrente, v.attivoTotale.corrente) * 100 : null,
    rapporto(v.rimanenze.precedente, v.attivoTotale.precedente) !== null ? rapporto(v.rimanenze.precedente, v.attivoTotale.precedente) * 100 : null,
    "rimanenze ÷ totale attivo", usa("rimanenze", "attivoTotale"));

  /* Rotazione del magazzino: quante volte l'anno le scorte si rinnovano.
     È una delle metriche su cui il clustering della Fase 1 misura la deviazione
     dai pari; una rotazione molto più bassa del cluster segnala scorte ferme. */
  const baseRotazione = v.acquisti.corrente !== null ? "acquisti" : "ricavi";
  const rotazioneMagazzino = indicatore("rotazione_magazzino", "Rotazione del magazzino", "x",
    rapporto(v[baseRotazione].corrente, v.rimanenze.corrente),
    rapporto(v[baseRotazione].precedente, v.rimanenze.precedente),
    `${baseRotazione === "acquisti" ? "costo del venduto" : "ricavi netti"} ÷ rimanenze`, usa(baseRotazione, "rimanenze"));

  return {
    margineEbitda, margineEbit, crescitaRicavi, crescitaMagazzino, crescitaCrediti,
    dso, dpo, dio, ciclo, leva, costoDebito, qualitaUtile, incidenzaMagazzino, rotazioneMagazzino,
  };
}

const ELENCO_INDICATORI = (ind) => Object.values(ind);

/* --------------------------------------------------------------------------
   Δ PATRIMONIALI
   Blocco separato e conservato nel salvataggio: le fasi successive (rendiconto
   finanziario indiretto, analisi del circolante) ricostruiscono i flussi
   proprio dalle variazioni delle poste patrimoniali. Calcolarle qui una volta
   sola evita che ogni modulo le ricalcoli con convenzioni diverse.
   -------------------------------------------------------------------------- */

const VOCI_DELTA = [
  { voce: "creditiClienti", label: "Crediti verso clienti", natura: "attivo circolante", assorbe: true },
  { voce: "rimanenze", label: "Rimanenze", natura: "attivo circolante", assorbe: true },
  { voce: "lavoriInCorso", label: "Lavori in corso su ordinazione", natura: "attivo circolante", assorbe: true },
  { voce: "debitiFornitori", label: "Debiti verso fornitori", natura: "passivo corrente", assorbe: false },
  { voce: "fondiRischi", label: "Fondi per rischi e oneri", natura: "passivo", assorbe: false },
  { voce: "immobilizzazioni", label: "Immobilizzazioni materiali", natura: "attivo fisso", assorbe: true },
  { voce: "immobilizzazioniImmateriali", label: "Immobilizzazioni immateriali", natura: "attivo fisso", assorbe: true },
  { voce: "debitiFinanziari", label: "Debiti finanziari", natura: "fonte finanziaria", assorbe: false },
  { voce: "disponibilita", label: "Disponibilità liquide", natura: "cassa", assorbe: true },
  { voce: "patrimonioNetto", label: "Patrimonio netto", natura: "fonte propria", assorbe: false },
  { voce: "attivoTotale", label: "Totale attivo", natura: "totale", assorbe: null },
];

/* Le due poste che un nuovo contratto di leasing gonfia simultaneamente: il
   diritto d'uso entra fra le immobilizzazioni, la passività per leasing fra i
   debiti finanziari. Nessuna delle due è passata per la cassa. */
const VOCI_STERILIZZABILI_IFRS16 = ["immobilizzazioni", "debitiFinanziari"];

function calcolaDeltaPatrimoniali(voci) {
  /* RUMORE IFRS 16.
     La rilevazione di un nuovo contratto di leasing iscrive un'attività per
     diritto d'uso e una passività di pari importo. Letta come variazione
     patrimoniale, quella coppia dice due cose false nello stesso momento: che
     l'azienda ha investito in immobilizzazioni e che si è indebitata sul
     mercato. Non è successo né l'uno né l'altro — è una scrittura senza cassa,
     e l'anno di prima applicazione del principio la fa esplodere.
     Sterilizzarla non è una rettifica di comodo: è la condizione perché il
     CAPEX implicito e la raccolta di debito misurino ciò che dicono di
     misurare. Se la voce non è stata estratta l'importo è zero e non succede
     nulla: nessun delta viene toccato al buio. */
  const additionsIFRS16 = voci.nuoviLeasing?.corrente || 0;

  return VOCI_DELTA.map((d) => {
    const v = voci[d.voce] || {};
    const corrente = v.corrente ?? null;
    const precedente = v.precedente ?? null;
    let delta = corrente !== null && precedente !== null ? corrente - precedente : null;

    let notaSterilizzazione = null;
    if (delta !== null && additionsIFRS16 !== 0 && VOCI_STERILIZZABILI_IFRS16.includes(d.voce)) {
      delta = delta - additionsIFRS16;
      notaSterilizzazione = `Depurato di ${fmtImporto(additionsIFRS16)} per nuovi contratti leasing (non cash)`;
    }

    return {
      voce: d.voce, label: d.label, natura: d.natura,
      corrente, precedente, delta,
      variazionePct: variazionePct(corrente, precedente),
      // Segno dell'effetto sulla cassa: un credito che cresce assorbe liquidità,
      // un debito verso fornitori che cresce la rilascia.
      effettoCassa: delta === null || d.assorbe === null ? null : (d.assorbe ? -delta : delta),
      percorso: v.percorso || null,
      notaSterilizzazione,
    };
  }).filter((d) => d.corrente !== null || d.precedente !== null);
}

/* --------------------------------------------------------------------------
   BENCHMARK ESTERNI
   Provengono dal livello "informazione derivata" della Fase 0. Regola non
   negoziabile: le stime di terzi sulla società analizzata (perimetro "societa")
   non sono un metro di paragone — sono un'opinione sul soggetto. Solo peer,
   settore e mercato entrano qui come riferimento.
   -------------------------------------------------------------------------- */

function estraiBenchmark(parametriDerivati) {
  const out = {};
  for (const p of parametriDerivati || []) {
    if (!p || !p.metrica || typeof p.valore !== "number") continue;
    const perimetro = p.perimetro || "settore";
    if (perimetro === "societa") continue;
    out[p.metrica] = out[p.metrica] || {};
    if (!out[p.metrica][perimetro]) {
      out[p.metrica][perimetro] = {
        valore: p.valore, unita: p.unita || null, periodo: p.periodo || null,
        fonti: Array.isArray(p.fonti) ? p.fonti : (p.fonte ? [p.fonte] : []),
        confermatoDa: p.confermatoDa || 1,
      };
    }
  }
  return out;
}

/** Riferimento preferito per una metrica: settore, poi peer, poi mercato. */
function riferimento(benchmark, metrica) {
  const b = benchmark?.[metrica];
  if (!b) return null;
  for (const perimetro of ["settore", "peer", "mercato"]) {
    if (b[perimetro]) return { ...b[perimetro], perimetro };
  }
  return null;
}

/* ==========================================================================
   [3] VALUTAZIONE DETERMINISTICA — domain/trigger.js
   --------------------------------------------------------------------------
   Tutto ciò che si può decidere con l'aritmetica viene deciso qui, prima di
   qualunque chiamata al modello. Le soglie sono raccolte in un'unica tabella:
   sono convenzioni di analisi, non verità, e devono restare leggibili e
   modificabili da chi conduce la revisione.
   ========================================================================== */

const SOGLIE = {
  margineScostamentoPP: { attenzione: 3, criticita: 6 },      // punti percentuali sopra il riferimento
  dsoScostamentoPct: { attenzione: 15, criticita: 35 },        // scostamento % dal DSO di settore
  dsoPeggioramentoGiorni: { attenzione: 8, criticita: 20 },    // allungamento anno su anno
  forbiceMagazzinoPP: { attenzione: 10, criticita: 25 },       // crescita rimanenze − crescita ricavi
  forbiceCreditiPP: { attenzione: 8, criticita: 20 },          // crescita crediti − crescita ricavi
  coperturaCassaUtile: { attenzione: 0.8, criticita: 0.4 },    // flusso operativo ÷ utile
  covenantMarginePct: { attenzione: 15, criticita: 7 },        // spazio residuo prima della violazione
};

const arrotonda = (n, d = 1) => (n === null || n === undefined || !isFinite(n) ? null : Math.round(n * 10 ** d) / 10 ** d);
const segno = (n) => (n > 0 ? "+" : "");
const fmtNum = (n, d = 1) => (n === null || n === undefined || !isFinite(n) ? "—" : new Intl.NumberFormat("it-IT", { minimumFractionDigits: d, maximumFractionDigits: d }).format(n));
const fmtImporto = (n) => (n === null || n === undefined || !isFinite(n) ? "—" : new Intl.NumberFormat("it-IT", { maximumFractionDigits: 0 }).format(n));

function fmtIndicatore(ind) {
  if (!ind || !ind.disponibile) return "—";
  // Il segno esplicito ha senso su una variazione ("+38,6%"), non su un livello
  // ("18,4% di margine"): mostrarlo ovunque farebbe leggere ogni margine come
  // se fosse una crescita.
  if (ind.unita === "%") return `${ind.id.startsWith("crescita") ? segno(ind.valore) : ""}${fmtNum(ind.valore)}%`;
  if (ind.unita === "giorni") return `${fmtNum(ind.valore, 0)} gg`;
  if (ind.unita === "x") return `${fmtNum(ind.valore, 2)}x`;
  return fmtNum(ind.valore);
}

/** Esito di una singola direttrice prodotto dal calcolo. */
function esito(id, livello, sintesi, dati = [], fonti = [], extra = {}) {
  return { id, livello, sintesi, dati, fonti, origine: "calcolo", ...extra };
}
const nonDeterminabile = (id, motivo) => esito(id, "non_determinabile", motivo, [], []);

/* --- Ricerca di soglie contrattuali dentro gli estratti di Fase 0 ---------
   Un covenant è un numero scritto in un contratto: se il testo lo dichiara,
   confrontarlo con la leva calcolata è aritmetica, non interpretazione. Si
   cerca sia la soglia sia, quando presente, il valore misurato dalla società
   alla data di riferimento — le due cifre spesso convivono nella stessa frase.
-------------------------------------------------------------------------- */
const RE_SOGLIA = /(?:non superiore a|non in eccesso di|not\s+(?:in\s+)?excess of|maximum(?:\s+of)?|max(?:imum)?|no\s+greater\s+than|inferiore a|entro|non oltre)[^0-9]{0,24}(\d+(?:[.,]\d+)?)\s*x/i;
const RE_MISURATO = /(?:era pari a|era|risultava|si attestava a|was|stood at|amounted to|pari a)[^0-9]{0,24}(\d+(?:[.,]\d+)?)\s*x/i;

function estraiSoglieCovenant(estratti) {
  const trovate = [];
  for (const e of estratti) {
    if (e.tema !== "covenants") continue;
    const testo = `${e.traduzioneIt || ""} ${e.testoOriginale || ""}`;
    const s = testo.match(RE_SOGLIA);
    if (!s) continue;
    const m = testo.match(RE_MISURATO);
    trovate.push({
      soglia: toNumero(s[1]),
      misurato: m ? toNumero(m[1]) : null,
      documento: e.documento || e.nomeFile || "documento non identificato",
      tipo: e.tipoDocumento || null,
      pagina: e.pagina ?? null,
      citazione: (e.traduzioneIt || e.testoOriginale || "").slice(0, 220),
    });
  }
  return trovate;
}

/** Conta gli estratti di un tema, restituendo anche le fonti per la scheda. */
function perTema(estratti, tema) {
  return estratti.filter((e) => e.tema === tema).map((e) => ({
    documento: e.documento || e.nomeFile || "documento non identificato",
    pagina: e.pagina ?? null,
    citazione: (e.traduzioneIt || e.testoOriginale || "").slice(0, 220),
    rilevanza: e.rilevanza || "media",
  }));
}

/**
 * MOTORE DETERMINISTICO
 * @returns {Object} mappa idDirettrice → esito. Le direttrici non coperte dal
 *                   calcolo semplicemente non compaiono: le riempie l'IA.
 */
function valutazioneDeterministica({ indicatori, benchmark, estratti, settore, voci }) {
  const out = {};
  const I = indicatori;

  /* --- A1 · Margini contro comparabili -------------------------------- */
  const rifMargine = riferimento(benchmark, "margine_ebitda");
  if (!I.margineEbitda.disponibile) {
    out.A1 = nonDeterminabile("A1", "EBITDA o ricavi non presenti nei JSON riclassificati: il margine non è calcolabile.");
  } else if (!rifMargine) {
    out.A1 = esito("A1", "non_determinabile",
      `Margine EBITDA calcolato al ${fmtNum(I.margineEbitda.valore)}%, ma nessun riferimento di settore o di peer è stato caricato in Fase 0: il confronto non è possibile.`,
      [{ etichetta: "Margine EBITDA", valore: fmtIndicatore(I.margineEbitda) },
       { etichetta: "Variazione anno su anno", valore: I.margineEbitda.delta !== null ? `${segno(I.margineEbitda.delta)}${fmtNum(I.margineEbitda.delta)} p.p.` : "—" }]);
  } else {
    const scarto = I.margineEbitda.valore - rifMargine.valore;
    const livello = scarto >= SOGLIE.margineScostamentoPP.criticita ? "rosso"
      : Math.abs(scarto) >= SOGLIE.margineScostamentoPP.attenzione ? "giallo" : "verde";
    out.A1 = esito("A1", livello,
      scarto >= SOGLIE.margineScostamentoPP.attenzione
        ? `Il margine EBITDA supera il riferimento di ${fmtNum(scarto)} punti percentuali. Una redditività stabilmente superiore ai comparabili va spiegata con un vantaggio competitivo verificabile, altrimenti indica politiche contabili più liberali.`
        : scarto <= -SOGLIE.margineScostamentoPP.attenzione
          ? `Il margine EBITDA è inferiore al riferimento di ${fmtNum(Math.abs(scarto))} punti percentuali: impostazione prudente o problema di competitività, da distinguere.`
          : `Il margine EBITDA è allineato al riferimento (scarto ${fmtNum(scarto)} p.p.).`,
      [
        { etichetta: "Margine EBITDA società", valore: fmtIndicatore(I.margineEbitda) },
        { etichetta: `Riferimento ${rifMargine.perimetro}`, valore: `${fmtNum(rifMargine.valore)}%${rifMargine.periodo ? ` (${rifMargine.periodo})` : ""}` },
        { etichetta: "Scostamento", valore: `${segno(scarto)}${fmtNum(scarto)} p.p.` },
        { etichetta: "Margine anno precedente", valore: I.margineEbitda.precedente !== null ? `${fmtNum(I.margineEbitda.precedente)}%` : "—" },
      ],
      (rifMargine.fonti || []).map((f) => ({ documento: f, pagina: null, citazione: "Parametro di confronto acquisito dal livello esterno di Fase 0." })));
  }

  /* --- A2 · Ciclo di incasso ------------------------------------------ */
  const rifDso = riferimento(benchmark, "dso");
  if (!I.dso.disponibile) {
    out.A2 = nonDeterminabile("A2", "Crediti verso clienti o ricavi non presenti: il DSO non è calcolabile.");
  } else {
    const scostamentoPct = rifDso ? ((I.dso.valore - rifDso.valore) / rifDso.valore) * 100 : null;
    const allungamento = I.dso.delta;
    let livello = "verde";
    if (scostamentoPct !== null && scostamentoPct >= SOGLIE.dsoScostamentoPct.criticita) livello = "rosso";
    else if (allungamento !== null && allungamento >= SOGLIE.dsoPeggioramentoGiorni.criticita) livello = "rosso";
    else if (scostamentoPct !== null && scostamentoPct >= SOGLIE.dsoScostamentoPct.attenzione) livello = "giallo";
    else if (allungamento !== null && allungamento >= SOGLIE.dsoPeggioramentoGiorni.attenzione) livello = "giallo";
    else if (scostamentoPct === null && allungamento === null) livello = "non_determinabile";

    const parti = [];
    if (scostamentoPct !== null) parti.push(`il DSO è di ${fmtNum(I.dso.valore, 0)} giorni contro ${fmtNum(rifDso.valore, 0)} del ${rifDso.perimetro} (${segno(scostamentoPct)}${fmtNum(scostamentoPct, 0)}%)`);
    if (allungamento !== null) parti.push(`rispetto all'esercizio precedente l'incasso ${allungamento >= 0 ? "si allunga" : "si accorcia"} di ${fmtNum(Math.abs(allungamento), 0)} giorni`);
    out.A2 = esito("A2", livello,
      parti.length
        ? `${parti.join("; ")}. Un incasso più lento del settore può segnalare crediti di dubbia esigibilità o ricavi riconosciuti prima della loro effettiva realizzabilità.`
        : "Il DSO è calcolabile ma manca sia il riferimento di settore sia il dato comparativo: nessun giudizio possibile.",
      [
        { etichetta: "DSO società", valore: fmtIndicatore(I.dso) },
        { etichetta: "DSO esercizio precedente", valore: I.dso.precedente !== null ? `${fmtNum(I.dso.precedente, 0)} gg` : "—" },
        { etichetta: rifDso ? `DSO ${rifDso.perimetro}` : "DSO di riferimento", valore: rifDso ? `${fmtNum(rifDso.valore, 0)} gg` : "non disponibile" },
        { etichetta: "Ciclo del circolante", valore: fmtIndicatore(I.ciclo) },
      ],
      rifDso ? (rifDso.fonti || []).map((f) => ({ documento: f, pagina: null, citazione: "Parametro di confronto acquisito dal livello esterno di Fase 0." })) : []);
  }

  /* --- A3 · Parti correlate (indizio quantitativo, giudizio all'IA) ---- */
  const fontiCorrelate = perTema(estratti, "parti_correlate");
  if (fontiCorrelate.length) {
    out.A3 = esito("A3", "giallo",
      fontiCorrelate.length === 1
        ? "Nei documenti acquisiti compare un passaggio su operazioni con parti correlate: la valutazione di merito è affidata alla lettura del contesto."
        : `Nei documenti acquisiti compaiono ${fontiCorrelate.length} passaggi su operazioni con parti correlate: la valutazione di merito è affidata alla lettura del contesto.`,
      [{ etichetta: "Passaggi rilevati", valore: String(fontiCorrelate.length) },
       { etichetta: "Fonti distinte", valore: String(new Set(fontiCorrelate.map((f) => f.documento)).size) }],
      fontiCorrelate.slice(0, 4));
  }

  /* --- B1 · Posta sensibile del settore -------------------------------- */
  const s = settorePerId(settore);
  const vocePosta = voci[s.voce] || {};
  const incidenza = vocePosta.corrente !== null && voci.attivoTotale?.corrente
    ? (vocePosta.corrente / voci.attivoTotale.corrente) * 100 : null;
  out.B1 = esito("B1",
    incidenza === null ? "non_determinabile" : incidenza >= 35 ? "giallo" : "verde",
    `Per il settore «${s.label}» la voce a massima soggettività è: ${s.posta}. ${s.perche}` +
      (incidenza !== null ? ` Nel bilancio in esame pesa il ${fmtNum(incidenza)}% dell'attivo.` : " L'incidenza sull'attivo non è calcolabile dai JSON caricati."),
    [
      { etichetta: "Posta sensibile", valore: s.posta },
      { etichetta: "Valore corrente", valore: fmtImporto(vocePosta.corrente) },
      { etichetta: "Valore precedente", valore: fmtImporto(vocePosta.precedente) },
      { etichetta: "Incidenza sull'attivo", valore: incidenza !== null ? `${fmtNum(incidenza)}%` : "—" },
    ]);

  /* --- B2 · Forbice magazzino / vendite (il trigger classico) ---------- */
  if (!I.crescitaMagazzino.disponibile || !I.crescitaRicavi.disponibile) {
    out.B2 = nonDeterminabile("B2", "Servono rimanenze e ricavi di due esercizi consecutivi: nei JSON caricati manca almeno uno dei quattro valori.");
  } else {
    const forbice = I.crescitaMagazzino.valore - I.crescitaRicavi.valore;
    const livello = forbice >= SOGLIE.forbiceMagazzinoPP.criticita ? "rosso"
      : forbice >= SOGLIE.forbiceMagazzinoPP.attenzione ? "giallo" : "verde";
    out.B2 = esito("B2", livello,
      forbice >= SOGLIE.forbiceMagazzinoPP.attenzione
        ? `Le rimanenze crescono di ${fmtNum(forbice)} punti percentuali più delle vendite. Le due spiegazioni possibili sono opposte e vanno separate: costi di produzione trattenuti a magazzino per non passare dal conto economico, oppure merce che non si sta vendendo e attende una svalutazione.`
        : `Rimanenze e vendite si muovono in modo coerente (scarto ${fmtNum(forbice)} p.p.).`,
      [
        { etichetta: "Vendite", valore: fmtIndicatore(I.crescitaRicavi) },
        { etichetta: "Magazzino", valore: fmtIndicatore(I.crescitaMagazzino) },
        { etichetta: "Forbice", valore: `${segno(forbice)}${fmtNum(forbice)} p.p.` },
        { etichetta: "Giorni di giacenza (DIO)", valore: fmtIndicatore(I.dio) },
      ]);
  }

  /* --- B3 · Forbice crediti / vendite ---------------------------------- */
  if (!I.crescitaCrediti.disponibile || !I.crescitaRicavi.disponibile) {
    out.B3 = nonDeterminabile("B3", "Servono crediti verso clienti e ricavi di due esercizi consecutivi.");
  } else {
    const forbice = I.crescitaCrediti.valore - I.crescitaRicavi.valore;
    const livello = forbice >= SOGLIE.forbiceCreditiPP.criticita ? "rosso"
      : forbice >= SOGLIE.forbiceCreditiPP.attenzione ? "giallo" : "verde";
    const cassa = I.qualitaUtile.disponibile
      ? ` La copertura di cassa dell'utile è ${fmtNum(I.qualitaUtile.valore, 2)}x${I.qualitaUtile.valore < SOGLIE.coperturaCassaUtile.attenzione ? ": l'utile dichiarato non sta arrivando in cassa" : ""}.`
      : "";
    out.B3 = esito("B3", livello,
      (forbice >= SOGLIE.forbiceCreditiPP.attenzione
        ? `I crediti verso clienti crescono di ${fmtNum(forbice)} punti percentuali più dei ricavi: i ricavi contabilizzati non si stanno trasformando in incassi allo stesso ritmo.`
        : `Crediti e ricavi crescono in modo allineato (scarto ${fmtNum(forbice)} p.p.).`) + cassa,
      [
        { etichetta: "Ricavi", valore: fmtIndicatore(I.crescitaRicavi) },
        { etichetta: "Crediti verso clienti", valore: fmtIndicatore(I.crescitaCrediti) },
        { etichetta: "Forbice", valore: `${segno(forbice)}${fmtNum(forbice)} p.p.` },
        { etichetta: "Copertura di cassa dell'utile", valore: fmtIndicatore(I.qualitaUtile) },
      ]);
  }

  /* --- C2 · Spazio residuo sui covenants ------------------------------- */
  const soglieTrovate = estraiSoglieCovenant(estratti);
  if (!soglieTrovate.length) {
    if (I.leva.disponibile) {
      out.C2 = esito("C2", "non_determinabile",
        `La leva finanziaria calcolata è ${fmtNum(I.leva.valore, 2)}x, ma nei documenti acquisiti non è stata individuata alcuna soglia contrattuale con cui confrontarla.`,
        [{ etichetta: "Leva calcolata", valore: fmtIndicatore(I.leva) },
         { etichetta: "Leva esercizio precedente", valore: I.leva.precedente !== null ? `${fmtNum(I.leva.precedente, 2)}x` : "—" }]);
    }
  } else {
    const conMargine = soglieTrovate.map((t) => {
      const misurato = t.misurato !== null ? t.misurato : (I.leva.disponibile ? I.leva.valore : null);
      const margine = misurato !== null && t.soglia ? ((t.soglia - misurato) / t.soglia) * 100 : null;
      return { ...t, misurato, margine };
    });
    const piuStretto = conMargine.reduce((a, b) => (a.margine === null ? b : b.margine === null ? a : (b.margine < a.margine ? b : a)));
    const livello = piuStretto.margine === null ? "non_determinabile"
      : piuStretto.margine <= 0 ? "rosso"
      : piuStretto.margine <= SOGLIE.covenantMarginePct.criticita ? "rosso"
      : piuStretto.margine <= SOGLIE.covenantMarginePct.attenzione ? "giallo" : "verde";
    out.C2 = esito("C2", livello,
      piuStretto.margine === null
        ? "Individuata una soglia contrattuale ma nessun valore misurato con cui confrontarla."
        : piuStretto.margine <= 0
          ? `Il parametro contrattuale risulta già violato: valore ${fmtNum(piuStretto.misurato, 2)}x contro un massimo di ${fmtNum(piuStretto.soglia, 2)}x.`
          : `Restano ${fmtNum(piuStretto.margine, 0)} punti percentuali di spazio prima della violazione (${fmtNum(piuStretto.misurato, 2)}x contro un massimo di ${fmtNum(piuStretto.soglia, 2)}x). Quanto più il margine si assottiglia, tanto maggiore è la convenienza a sostenere l'EBITDA con scelte contabili.`,
      [
        { etichetta: "Soglia contrattuale", valore: `${fmtNum(piuStretto.soglia, 2)}x` },
        { etichetta: "Valore misurato", valore: `${fmtNum(piuStretto.misurato, 2)}x` },
        { etichetta: "Spazio residuo", valore: piuStretto.margine !== null ? `${fmtNum(piuStretto.margine, 0)}%` : "—" },
        { etichetta: "Leva ricalcolata sui JSON", valore: fmtIndicatore(I.leva) },
      ],
      conMargine.slice(0, 3).map((t) => ({ documento: t.documento, pagina: t.pagina, citazione: t.citazione })),
      { soglieRilevate: conMargine.map((t) => ({ soglia: t.soglia, misurato: t.misurato, margine: arrotonda(t.margine, 1) })) });
  }

  return out;
}

/* ==========================================================================
   [4] IL CERVELLO — ai/promptForense.js
   --------------------------------------------------------------------------
   Il prompt è costruito attorno a un vincolo: il modello non deve mai poter
   inventare una fonte. Gli estratti vengono numerati ([E1], [E2], …) e l'unico
   modo ammesso per citare è richiamare quegli identificativi. Una citazione
   che non corrisponde a un identificativo esistente viene scartata a valle
   dalla normalizzazione, non discussa.
   ========================================================================== */

const SYSTEM_FORENSE = `Sei un analista forense di bilancio incaricato di una valutazione di Quality of
Earnings. Il tuo compito non è dire se l'azienda è buona: è dire quanto ci si
può fidare dei numeri che dichiara, e perché.

COSA STAI VALUTANDO
Il contesto, non il bilancio. Cerchi le condizioni che rendono possibile e
conveniente una rappresentazione contabile addolcita: politiche contabili
liberali, poste discrezionali che si muovono in modo anomalo, pressioni sul
management, assenza di un controllo indipendente.

REGOLE NON NEGOZIABILI
1. FONTI. Ogni affermazione su un fatto documentale deve citare uno o più
   identificativi tra quelli forniti nel formato [E1], [E7]. Non esistono altre
   fonti ammesse. Se non hai un identificativo a sostegno, non puoi affermare
   il fatto: puoi solo dichiarare che il dato non risulta.
2. NIENTE CONGETTURE. Se il materiale non permette di rispondere a una
   direttrice, il livello è "non_determinabile" e il ragionamento spiega quale
   documento servirebbe. "Non determinabile" è una risposta corretta e attesa,
   non un fallimento.
3. FATTI E STIME NON SI MESCOLANO. I dati di bilancio e gli estratti dai
   documenti societari sono dichiarazioni della società. I parametri di
   settore, di peer e di consensus sono opinioni di terzi: usali come metro di
   paragone, mai come prova di un fatto.
4. NIENTE GIUDIZI SULLE PERSONE. Descrivi ruoli, incarichi e incentivi come
   risultano dai documenti. Non attribuire intenzioni, non usare qualificazioni
   morali, non ipotizzare condotte illecite. Il tuo prodotto è un elenco di
   circostanze da verificare, non un'accusa.
5. IL CALCOLO HA GIÀ PARLATO. Gli indicatori che ti vengono forniti sono già
   calcolati e verificati: non ricalcolarli e non contraddirli. Il tuo lavoro è
   spiegare che cosa possono significare alla luce dei documenti.

SCALA DEI LIVELLI
- "verde": nessun elemento di rischio; il materiale disponibile è sufficiente
  a dirlo.
- "giallo": esiste una circostanza che aumenta il rischio o un dato anomalo
  privo di spiegazione documentale. Richiede un approfondimento.
- "rosso": circostanza che compromette l'attendibilità dei numeri, oppure
  concorso di più elementi che si rafforzano a vicenda.
- "non_determinabile": il materiale non consente di rispondere.

STILE
Italiano, registro tecnico e asciutto. Ragionamenti da 2 a 5 frasi, concreti,
sempre ancorati a un numero o a una citazione. Nessuna formula di cortesia,
nessuna premessa, nessuna raccomandazione generica.

FORMATO DI USCITA
Esclusivamente un oggetto JSON valido, senza testo introduttivo e senza
delimitatori markdown.`;

/** Righe leggibili degli indicatori, con la formula accanto: il modello vede da dove nasce il numero. */
function tabellaIndicatori(indicatori) {
  return ELENCO_INDICATORI(indicatori)
    .map((i) => {
      if (!i.disponibile) return `- ${i.label}: non calcolabile (dati mancanti nei riclassificati)`;
      const prec = i.precedente !== null ? ` | esercizio precedente: ${fmtNum(i.precedente, 2)}` : "";
      return `- ${i.label}: ${fmtNum(i.valore, 2)} ${i.unita}${prec}  [${i.formula}]`;
    })
    .join("\n");
}

function tabellaDelta(delta) {
  if (!delta.length) return "- nessuna variazione patrimoniale calcolabile";
  return delta
    .map((d) => `- ${d.label}: ${fmtImporto(d.precedente)} → ${fmtImporto(d.corrente)} (Δ ${segno(d.delta ?? 0)}${fmtImporto(d.delta)}${d.variazionePct !== null ? `, ${segno(d.variazionePct)}${fmtNum(d.variazionePct)}%` : ""})`)
    .join("\n");
}

function tabellaBenchmark(benchmark) {
  const righe = [];
  for (const [metrica, perimetri] of Object.entries(benchmark || {})) {
    for (const [perimetro, dato] of Object.entries(perimetri)) {
      righe.push(`- ${metrica} (${perimetro}): ${fmtNum(dato.valore, 2)}${dato.unita || ""}${dato.periodo ? ` — ${dato.periodo}` : ""}${dato.fonti?.length ? ` — fonte: ${dato.fonti.join(", ")}` : ""}`);
    }
  }
  return righe.length ? righe.join("\n") : "- nessun parametro esterno di confronto disponibile";
}

/** Numera gli estratti e restituisce sia il testo per il prompt sia la mappa per la verifica delle citazioni. */
function preparaEstratti(estratti, temiAmmessi) {
  const selezionati = estratti.filter((e) => !temiAmmessi || temiAmmessi.includes(e.tema));
  const mappa = {};
  const righe = selezionati.map((e, i) => {
    const id = `E${i + 1}`;
    mappa[id] = e;
    const provenienza = `${e.tipoDocumento || "documento"} · ${e.documento || "senza nome"}${e.pagina ? `, p. ${e.pagina}` : ""}`;
    return `[${id}] (${e.tema || "n.d."} — ${provenienza})\n${(e.traduzioneIt || e.testoOriginale || "").slice(0, 600)}`;
  });
  return { testo: righe.length ? righe.join("\n\n") : "(nessun estratto disponibile per i temi di questo modulo)", mappa, quanti: selezionati.length };
}

/**
 * PROMPT DI ANALISI FORENSE
 * -----------------------------------------------------------------------------
 * @param modulo  se valorizzato ("A"|"B"|"C"|"D") il modello lavora su un solo
 *                modulo per volta: risposte più lunghe e più esaustive per
 *                direttrice, e materiale documentale filtrato per tema. Se
 *                null, produce l'esito completo sui quattro moduli in un colpo
 *                solo — la forma richiesta dal brief.
 */
function promptForense({ azienda, settore, asa = [], indicatori, delta, benchmark, estratti, esitiCalcolo = {}, modulo = null, estrattiPreparati = null }) {
  const s = settorePerId(settore);
  const moduliRichiesti = modulo ? MODULI.filter((m) => m.id === modulo) : MODULI;
  const temi = modulo ? TEMI_PER_MODULO[modulo] : null;
  // Il chiamante può fornire la selezione già fatta: così la mappa degli
  // identificativi [E1..En] con cui il modello cita è esattamente la stessa
  // che normalizzaEsitoIA userà per risolvere le citazioni. Ricalcolarla due
  // volte darebbe lo stesso risultato (la funzione è pura), ma passarla evita
  // che una futura modifica del filtro le faccia divergere in silenzio.
  const { testo: testoEstratti, quanti } = estrattiPreparati || preparaEstratti(estratti, temi);

  // Perimetro dichiarato: il modello deve sapere che il materiale non è stato
  // troncato per caso ma selezionato, e che il silenzio su un tema fuori
  // perimetro non è un'assenza di informazione su cui possa concludere.
  const perimetro = modulo
    ? `PERIMETRO DOCUMENTALE DI QUESTO MODULO
Stai valutando ESCLUSIVAMENTE il modulo ${modulo}. Il materiale al punto 4 è già
stato filtrato a monte sui soli temi di competenza di questo modulo:
${temi.map((t) => `  · ${TEMI[t] || t}`).join("\n")}
Gli estratti sugli altri temi esistono ma ti sono stati deliberatamente
sottratti: verranno valutati dai rispettivi moduli. Da questo discende che:
- non desumere nulla dalla loro assenza e non dichiarare mancante un documento
  solo perché non compare qui;
- non rispondere a direttrici di altri moduli, nemmeno se il materiale te lo
  consentirebbe;
- se una direttrice di QUESTO modulo resta priva di riscontro nel materiale
  fornito, il livello corretto è "non_determinabile" con confidenza bassa.

`
    : "";

  const specModuli = moduliRichiesti
    .map((m) => {
      const dir = m.direttrici
        .map((d) => {
          const gia = esitiCalcolo[d.id];
          const nota = gia && gia.livello !== "non_determinabile"
            ? `\n      · esito già calcolato: ${gia.livello} — ${gia.sintesi}`
            : "";
          return `  ${d.id} · ${d.titolo}\n      → ${d.domanda}${nota}`;
        })
        .join("\n");
      return `MODULO ${m.id} — ${m.titolo.toUpperCase()} (${m.occhiello})\nDomanda di fondo: ${m.domandaChiave}\n${dir}`;
    })
    .join("\n\n");

  const schemaDirettrici = moduliRichiesti
    .map((m) => `        { "id": "${m.direttrici[0].id}", "livello": "verde|giallo|rosso|non_determinabile", "ragionamento": "<2-5 frasi>", "dati_a_supporto": [{ "etichetta": "<voce>", "valore": "<valore formattato>" }], "fonti": ["E1"], "confidenza": "alta|media|bassa" }`)
    .join(",\n");

  const elencoAsa = asa.length
    ? asa.map((a) => `- ${a.nome}: ${fmtNum(a.quota, 0)}% dei ricavi, settore di riferimento «${settorePerId(a.settore).label}», posta sensibile «${settorePerId(a.settore).posta}»`).join("\n")
    : "- nessuna area strategica d'affari configurata: l'azienda è trattata come mono-business";

  return `AZIENDA ANALIZZATA: ${azienda || "non dichiarata"}
SETTORE PREVALENTE: ${s.label}
POSTA A MASSIMA SOGGETTIVITÀ PER QUESTO SETTORE: ${s.posta}
${s.perche}

AREE STRATEGICHE D'AFFARI (ASA)
${elencoAsa}

${perimetro}

════════════════════════════════════════════════════════════════════════
1 · INDICATORI GIÀ CALCOLATI SUI RICLASSIFICATI (non ricalcolarli)
════════════════════════════════════════════════════════════════════════
${tabellaIndicatori(indicatori)}

════════════════════════════════════════════════════════════════════════
2 · VARIAZIONI PATRIMONIALI (Δ)
════════════════════════════════════════════════════════════════════════
${tabellaDelta(delta)}

════════════════════════════════════════════════════════════════════════
3 · PARAMETRI ESTERNI DI CONFRONTO (opinioni di terzi, non fatti societari)
════════════════════════════════════════════════════════════════════════
${tabellaBenchmark(benchmark)}

════════════════════════════════════════════════════════════════════════
4 · ESTRATTI DOCUMENTALI TRADOTTI (${quanti}${modulo ? `, selezionati sui temi del modulo ${modulo}` : ""}) — unica fonte citabile
════════════════════════════════════════════════════════════════════════
${testoEstratti}

════════════════════════════════════════════════════════════════════════
5 · DIRETTRICI A CUI DEVI RISPONDERE, UNA PER UNA
════════════════════════════════════════════════════════════════════════
${specModuli}

REGOLE DI COMPILAZIONE
- Rispondi a OGNI direttrice elencata sopra, nessuna esclusa, nello stesso ordine.
- "fonti" contiene solo identificativi presenti al punto 4 (formato "E3"). Se non
  ne hai, lascia l'array vuoto e abbassa la confidenza.
- "dati_a_supporto" riporta i numeri già forniti ai punti 1-3, formattati come li
  mostreresti in una scheda (es. { "etichetta": "Vendite", "valore": "+5,0%" }).
- Dove trovi un "esito già calcolato", non contraddirlo: spiegalo, oppure
  segnala che i documenti lo ridimensionano e alza o abbassa il livello di
  conseguenza, motivando.
- "sintesi_modulo": una frase che dica al revisore che cosa guardare per primo.

RESTITUISCI ESATTAMENTE QUESTA STRUTTURA:
{
  "azienda": "${azienda || ""}",
  "settore_riconosciuto": "<settore che ricavi dai documenti, se diverso da quello dichiarato>",
  "moduli": [
    {
      "modulo": "${moduliRichiesti[0].id}",
      "livello": "verde|giallo|rosso|non_determinabile",
      "sintesi_modulo": "<una frase>",
      "direttrici": [
${schemaDirettrici}
      ]
    }
  ],
  "sintesi_esecutiva": "<3-5 frasi: che cosa rende questo bilancio più o meno attendibile>",
  "domande_al_management": ["<domanda puntuale e verificabile>"],
  "documenti_mancanti": ["<documento che servirebbe per sciogliere un non_determinabile>"]
}`;
}

/* --- Chiamata al modello e normalizzazione dell'esito --------------------- */

/**
 * Riporta l'esito del modello dentro il perimetro consentito:
 * livelli fuori scala, direttrici inventate e citazioni che non corrispondono a
 * un estratto reale vengono eliminate qui. Ciò che sopravvive è verificabile.
 */
function normalizzaEsitoIA(json, mappaEstratti) {
  if (!json || !Array.isArray(json.moduli)) return { direttrici: {}, moduli: {}, sintesi: null, domande: [], mancanti: [] };
  const direttrici = {};
  const moduli = {};

  for (const m of json.moduli) {
    if (!m || !MODULI.some((x) => x.id === m.modulo)) continue;
    moduli[m.modulo] = {
      livello: LIVELLI_VALIDI.includes(m.livello) ? m.livello : "non_determinabile",
      sintesi: typeof m.sintesi_modulo === "string" ? m.sintesi_modulo : null,
    };
    for (const d of Array.isArray(m.direttrici) ? m.direttrici : []) {
      const spec = direttricePerId(d?.id);
      if (!spec || spec.modulo !== m.modulo) continue;
      const fonti = (Array.isArray(d.fonti) ? d.fonti : [])
        .map((rif) => mappaEstratti[String(rif).replace(/[[\]]/g, "").trim()])
        .filter(Boolean)
        .map((e) => ({
          documento: e.documento || e.nomeFile || "documento non identificato",
          tipo: e.tipoDocumento || null,
          pagina: e.pagina ?? null,
          citazione: (e.traduzioneIt || e.testoOriginale || "").slice(0, 220),
        }));
      direttrici[spec.id] = {
        id: spec.id,
        livello: LIVELLI_VALIDI.includes(d.livello) ? d.livello : "non_determinabile",
        ragionamento: typeof d.ragionamento === "string" ? d.ragionamento : "",
        dati: (Array.isArray(d.dati_a_supporto) ? d.dati_a_supporto : [])
          .filter((x) => x && x.etichetta)
          .map((x) => ({ etichetta: String(x.etichetta), valore: String(x.valore ?? "—") })),
        fonti,
        confidenza: ["alta", "media", "bassa"].includes(d.confidenza) ? d.confidenza : "media",
        origine: "ia",
      };
    }
  }

  return {
    direttrici, moduli,
    sintesi: typeof json.sintesi_esecutiva === "string" ? json.sintesi_esecutiva : null,
    settoreRiconosciuto: typeof json.settore_riconosciuto === "string" ? json.settore_riconosciuto : null,
    domande: (Array.isArray(json.domande_al_management) ? json.domande_al_management : []).filter((x) => typeof x === "string").slice(0, 12),
    mancanti: (Array.isArray(json.documenti_mancanti) ? json.documenti_mancanti : []).filter((x) => typeof x === "string").slice(0, 12),
  };
}

/** Analisi di un singolo modulo: prompt mirato, materiale filtrato per tema. */
async function analizzaModulo(contesto, modulo) {
  const preparati = preparaEstratti(contesto.estratti, TEMI_PER_MODULO[modulo]);
  const testo = await chiamataIA({
    system: SYSTEM_FORENSE,
    contenuto: promptForense({ ...contesto, modulo, estrattiPreparati: preparati }),
    maxTokens: 4000,
  });
  return normalizzaEsitoIA(parseJsonRobusto(testo), preparati.mappa);
}

/**
 * ORCHESTRATORE DELLA DIAGNOSI — un modulo per volta, in sequenza.
 * -----------------------------------------------------------------------------
 * Vive fuori da React perché ha due chiamanti che non devono divergere: il
 * pulsante «Avvia analisi forense» della Fase 1 e la cascata automatica del
 * guscio. Non conosce reducer né dispatch: riceve il contesto già derivato e
 * comunica l'avanzamento tramite callback, restituendo l'esito. Chi lo chiama
 * decide che cosa farne.
 *
 * Ogni modulo è una chiamata separata al modello con il proprio perimetro
 * documentale: è questo che costringe l'IA a leggere i documenti in funzione
 * di ciò che la sezione richiede, invece di produrre una lettura unica e
 * generica poi ritagliata a valle.
 *
 * @throws propaga l'errore della prima chiamata fallita: la valutazione parziale
 *         non è un esito valido e il chiamante deve poterla distinguere.
 */
async function eseguiDiagnosiForense({ contesto, esitiCalcolo, onProgresso, onLog }) {
  const unione = { direttrici: {}, moduli: {}, sintesi: null, settoreRiconosciuto: null, domande: [], mancanti: [] };
  for (const [i, m] of MODULI.entries()) {
    onProgresso?.({ modulo: m.id, titolo: m.titolo, indice: i + 1, totale: MODULI.length });
    const esito = await analizzaModulo(contesto, m.id);
    Object.assign(unione.direttrici, esito.direttrici);
    Object.assign(unione.moduli, esito.moduli);
    if (esito.sintesi) unione.sintesi = esito.sintesi;
    if (esito.settoreRiconosciuto) unione.settoreRiconosciuto = esito.settoreRiconosciuto;
    unione.domande.push(...esito.domande);
    unione.mancanti.push(...esito.mancanti);
    onLog?.({
      livello: "ok",
      testo: `Modulo ${m.id} — ${m.titolo}: ${Object.keys(esito.direttrici).length} direttrici valutate su ${preparaEstratti(contesto.estratti, TEMI_PER_MODULO[m.id]).quanti} estratti di competenza.`,
    });
  }
  return { esiti: componiValutazione({ esitiCalcolo, esitoIA: unione }), esitoIA: unione };
}

/* ==========================================================================
   [5] FUSIONE E PUNTEGGIO — domain/valutazione.js
   ========================================================================== */

/**
 * Unisce, per ciascuna direttrice, l'esito del calcolo e quello del modello.
 * Il calcolo porta i numeri e le soglie; l'IA porta il ragionamento e le fonti.
 * Il livello finale è il più severo dei due, con "non_determinabile" trattato
 * come neutro (vedi combinaLivelli).
 */
function fondiDirettrice(spec, det, ia) {
  if (!det && !ia) {
    return { id: spec.id, livello: "non_determinabile", ragionamento: "Direttrice non ancora valutata.", dati: [], fonti: [], confidenza: "bassa", origine: "assente" };
  }
  const livello = combinaLivelli(det?.livello, ia?.livello);
  const dati = [...(det?.dati || []), ...(ia?.dati || []).filter((x) => !(det?.dati || []).some((y) => y.etichetta === x.etichetta))];
  const fonti = [...(det?.fonti || []), ...(ia?.fonti || [])].filter((f, i, arr) =>
    arr.findIndex((g) => g.documento === f.documento && g.pagina === f.pagina) === i).slice(0, 6);
  const ragionamento = [ia?.ragionamento, det?.sintesi].filter(Boolean).join(det && ia ? "\n\n" : "");
  return {
    id: spec.id, livello, ragionamento, dati, fonti,
    confidenza: ia?.confidenza || (det ? "alta" : "bassa"),
    origine: det && ia ? "misto" : det ? "calcolo" : (ia ? "ia" : "assente"),
    divergenza: det && ia && det.livello !== ia.livello && det.livello !== "non_determinabile" && ia.livello !== "non_determinabile"
      ? `Calcolo: ${RISCHIO[det.livello].breve} · Lettura documentale: ${RISCHIO[ia.livello].breve}`
      : null,
    soglieRilevate: det?.soglieRilevate || null,
  };
}

/** Livello di modulo: il più severo delle sue direttrici, con gli N.D. neutri. */
function livelloModulo(direttrici) {
  const livelli = direttrici.map((d) => d.livello);
  const espliciti = livelli.filter((l) => l !== "non_determinabile");
  if (!espliciti.length) return "non_determinabile";
  return espliciti.reduce((a, b) => peggiore(a, b), "verde");
}

const FASCE = [
  { min: 80, label: "Contesto affidabile", nota: "Nessun elemento impedisce di procedere ai modelli statistici.", colore: C.baseline },
  { min: 60, label: "Contesto con riserve", nota: "Procedere solo dopo aver sciolto le direttrici in attenzione.", colore: C.ambra },
  { min: 40, label: "Contesto critico", nota: "I numeri vanno trattati come non confermati finché le Red Flag non sono chiarite.", colore: C.flag },
  { min: 0, label: "Contesto ad alto rischio", nota: "L'analisi quantitativa su questi dati produrrebbe risultati privi di significato.", colore: C.flag },
];

/**
 * QUALITY SCORE
 * Media pesata delle penalità, non conteggio dei rossi: una direttrice con
 * peso 4 vale il doppio di una con peso 2. Gli N.D. pesano poco ma non zero:
 * un'analisi piena di buchi non può risultare affidabile quanto una completa.
 *
 * Vincolo di governance: se il modulo D è rosso, il punteggio non può superare
 * 55. Senza un presidio capace di opporsi, ogni altro risultato è un'ipotesi
 * appoggiata sulla parola del management.
 */
function calcolaPunteggio(direttrici, livelliModulo) {
  let pesoTotale = 0, penalita = 0, valutate = 0, rosse = 0, gialle = 0;
  for (const spec of TUTTE_LE_DIRETTRICI) {
    const e = direttrici[spec.id];
    const liv = e?.livello || "non_determinabile";
    pesoTotale += spec.peso;
    penalita += spec.peso * RISCHIO[liv].penalita;
    if (liv !== "non_determinabile") valutate++;
    if (liv === "rosso") rosse++;
    if (liv === "giallo") gialle++;
  }
  let punteggio = Math.round(100 * (1 - penalita / pesoTotale));
  const vincoloGovernance = livelliModulo.D === "rosso" && punteggio > 55;
  if (vincoloGovernance) punteggio = 55;
  const fascia = FASCE.find((f) => punteggio >= f.min) || FASCE[FASCE.length - 1];
  return {
    punteggio,
    copertura: Math.round((valutate / TUTTE_LE_DIRETTRICI.length) * 100),
    direttriciValutate: valutate,
    direttriciTotali: TUTTE_LE_DIRETTRICI.length,
    rosse, gialle, vincoloGovernance,
    fascia: fascia.label, notaFascia: fascia.nota, colore: fascia.colore,
  };
}

/** Compone l'esito completo mostrato in dashboard e salvato su file. */
function componiValutazione({ esitiCalcolo, esitoIA }) {
  const direttrici = {};
  for (const spec of TUTTE_LE_DIRETTRICI) {
    direttrici[spec.id] = fondiDirettrice(spec, esitiCalcolo?.[spec.id] || null, esitoIA?.direttrici?.[spec.id] || null);
  }
  const moduli = {};
  const livelli = {};
  for (const m of MODULI) {
    const suoi = m.direttrici.map((d) => direttrici[d.id]);
    const livello = livelloModulo(suoi);
    livelli[m.id] = livello;
    moduli[m.id] = {
      id: m.id,
      livello,
      sintesi: esitoIA?.moduli?.[m.id]?.sintesi || null,
      rosse: suoi.filter((d) => d.livello === "rosso").length,
      gialle: suoi.filter((d) => d.livello === "giallo").length,
      nonDeterminabili: suoi.filter((d) => d.livello === "non_determinabile").length,
    };
  }
  const punteggio = calcolaPunteggio(direttrici, livelli);
  return {
    direttrici, moduli, punteggio,
    sintesiEsecutiva: esitoIA?.sintesi || null,
    settoreRiconosciuto: esitoIA?.settoreRiconosciuto || null,
    domande: esitoIA?.domande || [],
    documentiMancanti: esitoIA?.mancanti || [],
    eseguitaIl: new Date().toISOString(),
  };
}

/* ==========================================================================
   [6] STATE MANAGEMENT — reducerFase1
   --------------------------------------------------------------------------
   Tre contenitori separati, come in Fase 0:
     ingresso  → ciò che arriva da fuori (JSON numerici, estratti di Fase 0,
                 parametri esterni). È materiale di input: nessuna azione lo
                 modifica, si può solo sostituire in blocco.
     analisi   → l'anagrafica del lavoro: azienda, settore, configurazione ASA.
     esiti     → il prodotto della valutazione. Ricalcolabile in qualunque
                 momento senza toccare l'ingresso.
   Tenerli separati è ciò che rende il ricalcolo sicuro: rifare l'analisi non
   può mai corrompere i dati su cui è stata fatta.
   ========================================================================== */

const statoInizialeFase1 = {
  analisi: {
    azienda: "", settore: "generico", capitalizzazione: null, valuta: null,
    fonte: { azienda: null, settore: null, capitalizzazione: null },
    identificatoDa: null, asa: [], creata: null, eseguitaIl: null,
  },
  ingresso: { numerico: { SP: null, CE: null, RF: null }, estratti: [], parametriDerivati: [], provenienza: null },
  esiti: null,
  esitoIA: null,
  elaborazione: null,
  attivita: [],
  notifica: null,
};

const nuovoId = () => (typeof crypto !== "undefined" && crypto.randomUUID ? crypto.randomUUID() : `id-${Math.random().toString(36).slice(2)}-${Date.now()}`);
const voceLog = (livello, testo) => ({ id: nuovoId(), ora: ora(), livello, testo });

function reducerFase1(stato, azione) {
  switch (azione.tipo) {
    case "LOG":
      return { ...stato, attivita: [voceLog(azione.livello || "info", azione.testo), ...stato.attivita].slice(0, 120) };

    case "ANAGRAFICA": {
      const fonte = { ...stato.analisi.fonte };
      for (const chiave of Object.keys(azione.patch || {})) if (chiave in fonte) fonte[chiave] = "manuale";
      return { ...stato, analisi: { ...stato.analisi, ...azione.patch, fonte, creata: stato.analisi.creata || new Date().toISOString() } };
    }

    case "ASA_AGGIUNTA":
      return { ...stato, analisi: { ...stato.analisi, asa: [...stato.analisi.asa, { id: nuovoId(), nome: "", quota: 0, settore: stato.analisi.settore }] } };

    case "ASA_MODIFICATA":
      return { ...stato, analisi: { ...stato.analisi, asa: stato.analisi.asa.map((a) => (a.id === azione.id ? { ...a, ...azione.patch } : a)) } };

    case "ASA_RIMOSSA":
      return { ...stato, analisi: { ...stato.analisi, asa: stato.analisi.asa.filter((a) => a.id !== azione.id) } };

    case "NUMERICO_CARICATO":
      return {
        ...stato,
        ingresso: { ...stato.ingresso, numerico: { ...stato.ingresso.numerico, [azione.slot]: azione.dati } },
        attivita: [voceLog("ok", `${azione.slot} riclassificato importato (${azione.dati.nomeFile}).`), ...stato.attivita],
      };

    case "INGRESSO_FASE0": {
      // L'anagrafica arriva dalla Fase 0 già derivata dai documenti. Un campo
      // già fissato a mano qui in Fase 1 non viene toccato; tutti gli altri
      // recepiscono ciò che la Fase 0 ha rilevato (anche a scapito di un
      // valore preesistente non manuale, perché la Fase 0 può nel frattempo
      // aver letto un documento più autorevole).
      const a = azione.analisi || {};
      const fonte = { ...stato.analisi.fonte };
      const patch = {};
      if (fonte.azienda !== "manuale") { patch.azienda = a.azienda || azione.azienda || stato.analisi.azienda || ""; fonte.azienda = a.fonte?.azienda || fonte.azienda; }
      if (fonte.settore !== "manuale" && a.settore) { patch.settore = a.settore; fonte.settore = a.fonte?.settore || fonte.settore; }
      if (fonte.capitalizzazione !== "manuale" && a.capitalizzazione != null) {
        patch.capitalizzazione = a.capitalizzazione; patch.valuta = a.valuta || null;
        fonte.capitalizzazione = a.fonte?.capitalizzazione || fonte.capitalizzazione;
      }
      return {
        ...stato,
        analisi: { ...stato.analisi, ...patch, fonte, identificatoDa: a.identificatoDa || stato.analisi.identificatoDa, creata: stato.analisi.creata || new Date().toISOString() },
        ingresso: azione.ingresso,
        attivita: [voceLog("ok", azione.messaggio), ...stato.attivita],
      };
    }

    case "PROGRESSO":
      return { ...stato, elaborazione: azione.elaborazione };

    case "ANALISI_ESEGUITA":
      return {
        ...stato,
        esiti: azione.esiti,
        esitoIA: azione.esitoIA,
        elaborazione: null,
        analisi: { ...stato.analisi, eseguitaIl: azione.esiti.eseguitaIl },
        attivita: [voceLog("ok", `Analisi forense completata: punteggio ${azione.esiti.punteggio.punteggio}/100, ${azione.esiti.punteggio.rosse} red flag e ${azione.esiti.punteggio.gialle} elementi in attenzione.`), ...stato.attivita],
      };

    case "STATO_RIPRISTINATO":
      return { ...statoInizialeFase1, ...azione.stato, attivita: [voceLog("ok", azione.messaggio)] };

    case "AZZERATO":
      return { ...statoInizialeFase1, attivita: [voceLog("info", "Analisi azzerata. Puoi ripartire da un nuovo salvataggio di Fase 0.")] };

    case "NOTIFICA":
      return { ...stato, notifica: azione.notifica };

    case "FINE_ELABORAZIONE":
      return { ...stato, elaborazione: null };

    default:
      return stato;
  }
}

/* ==========================================================================
   SALVATAGGIO E RIPRISTINO — io/salvataggio.js
   --------------------------------------------------------------------------
   Il file di salvataggio ha tre destinatari diversi e li serve tutti:
     · statoApplicazione — gli stati React così come sono, per riprendere il
       lavoro dal punto esatto in cui è stato interrotto;
     · metriche / deltaPatrimoniali — blocchi già calcolati, pensati per essere
       consumati dai moduli successivi (rendiconto finanziario indiretto e
       analisi del circolante ricostruiscono i flussi proprio dai Δ);
     · risultanzeRischio — l'esito della diagnosi, in forma leggibile da chi
       non ha l'applicazione davanti.

   Il caricamento accetta tre formati e li riconosce da solo:
     formato 2 → salvataggio di Fase 1 (ripristino completo);
     formato 1 → salvataggio di Fase 0 (importazione come materiale d'ingresso);
     eredità   → file privi di intestazione, riconosciuti dalla struttura.
   Tutto ciò che rientra viene sanificato: un salvataggio resta un file esterno.
   ========================================================================== */

const FORMATO_FASE1 = 2;
const NOME_FASE1 = "Validazione e Qualità Contabile — Fase 1";

function componiSalvataggioFase1(stato, derivati) {
  const { indicatori, delta, benchmark, voci } = derivati;
  return {
    applicazione: NOME_FASE1,
    formatoSalvataggio: FORMATO_FASE1,
    fase: 1,
    generato: new Date().toISOString(),
    azienda: stato.analisi.azienda || null,
    settore: stato.analisi.settore,

    // ── Stato completo, per riprendere il lavoro ──
    statoApplicazione: {
      analisi: stato.analisi,
      ingresso: stato.ingresso,
      esiti: stato.esiti,
      esitoIA: stato.esitoIA,
    },

    // ── Configurazione delle aree strategiche d'affari ──
    configurazioneASA: stato.analisi.asa.map((a) => ({
      nome: a.nome, quotaRicaviPct: a.quota, settore: a.settore,
      postaSensibile: settorePerId(a.settore).posta,
    })),

    // ── Metriche calcolate, con formula e provenienza ──
    metriche: ELENCO_INDICATORI(indicatori).map((i) => ({
      id: i.id, label: i.label, unita: i.unita,
      valore: arrotonda(i.valore, 4), precedente: arrotonda(i.precedente, 4),
      variazionePct: arrotonda(i.variazione, 2), formula: i.formula, disponibile: i.disponibile,
    })),

    // ── Blocco Δ patrimoniali: base dei moduli di rendiconto finanziario ──
    deltaPatrimoniali: delta.map((d) => ({
      voce: d.voce, label: d.label, natura: d.natura,
      corrente: d.corrente, precedente: d.precedente, delta: d.delta,
      variazionePct: arrotonda(d.variazionePct, 2),
      effettoCassa: d.effettoCassa, origineDato: d.percorso,
    })),

    // ── Voci di bilancio risolte: consente di rifare i calcoli senza i JSON originali ──
    vociRisolte: Object.fromEntries(Object.entries(voci).map(([k, v]) => [k, { corrente: v.corrente, precedente: v.precedente, origineDato: v.percorso }])),

    // ── Materiale documentale già tradotto (Nota Integrativa, Relazione sulla Gestione, filings) ──
    estrattiTradotti: stato.ingresso.estratti,
    parametriDerivati: stato.ingresso.parametriDerivati,
    benchmarkApplicati: benchmark,

    // ── Risultanze dell'analisi di rischio ──
    risultanzeRischio: stato.esiti
      ? {
          punteggio: stato.esiti.punteggio,
          sintesiEsecutiva: stato.esiti.sintesiEsecutiva,
          moduli: MODULI.map((m) => ({
            modulo: m.id, titolo: m.titolo, livello: stato.esiti.moduli[m.id]?.livello || "non_determinabile",
            sintesi: stato.esiti.moduli[m.id]?.sintesi || null,
            direttrici: m.direttrici.map((d) => {
              const e = stato.esiti.direttrici[d.id];
              return {
                id: d.id, titolo: d.titolo, livello: e?.livello || "non_determinabile",
                ragionamento: e?.ragionamento || "", dati: e?.dati || [], fonti: e?.fonti || [],
                confidenza: e?.confidenza || "bassa", origine: e?.origine || "assente",
              };
            }),
          })),
          domandeAlManagement: stato.esiti.domande,
          documentiMancanti: stato.esiti.documentiMancanti,
        }
      : null,
  };
}

/* --- Sanificazione in ingresso ------------------------------------------- */

function sanificaEstrattoFase1(e, i) {
  if (!e || typeof e !== "object") return null;
  const testo = typeof e.traduzioneIt === "string" ? e.traduzioneIt : (typeof e.traduzione_it === "string" ? e.traduzione_it : null);
  const originale = typeof e.testoOriginale === "string" ? e.testoOriginale : (typeof e.testo_originale === "string" ? e.testo_originale : null);
  if (!testo && !originale) return null;
  return {
    id: typeof e.id === "string" ? e.id : `est-${i}`,
    tema: typeof e.tema === "string" ? e.tema : null,
    pagina: Number.isFinite(e.pagina) ? e.pagina : null,
    testoOriginale: originale || "",
    traduzioneIt: testo || "",
    rilevanza: ["alta", "media", "bassa"].includes(e.rilevanza) ? e.rilevanza : "media",
    documento: typeof e.documento === "string" ? e.documento : (typeof e.nomeFile === "string" ? e.nomeFile : null),
    tipoDocumento: typeof e.tipoDocumento === "string" ? e.tipoDocumento : (typeof e.tipo === "string" ? e.tipo : null),
    layer: typeof e.layer === "string" ? e.layer : null,
    // Provenienza temporale del giudizio, per i soli documenti di vigilanza.
    // Senza questi due campi un rilievo resta una frase; con questi diventa un
    // punto di una serie, che è ciò che la Fase 4 legge davvero.
    esercizioRif: ESERCIZI_ID.includes(e.esercizioRif) ? e.esercizioRif : null,
    organo: e.organo === "revisore" || e.organo === "sindaci" ? e.organo : null,
  };
}

/** Estrae il materiale utile da un salvataggio di Fase 0 (formato 1). */
function importaDaFase0(dati) {
  const st = dati.statoApplicazione || {};
  const estratti = [];

  // Percorso principale: la mappa documento → estratti, che porta con sé i metadati.
  const mappa = st.estrattiPerDocumento && typeof st.estrattiPerDocumento === "object" ? st.estrattiPerDocumento : {};
  for (const gruppo of Object.values(mappa)) {
    const meta = gruppo?.meta || {};
    for (const [i, e] of (Array.isArray(gruppo?.estratti) ? gruppo.estratti : []).entries()) {
      if (e?.derivato) continue; // i parametri di terzi viaggiano nel blocco benchmark, non qui
      const s = sanificaEstrattoFase1({
        ...e, documento: meta.nomeFile, tipoDocumento: meta.tipo, layer: meta.layer,
        esercizioRif: meta.esercizioRif ?? null,
        organo: meta.organo ?? organoDelTipo(meta.tipo),
      }, i);
      if (s) estratti.push(s);
    }
  }

  // Ripiego: se la mappa non c'è, si usano le informazioni già consolidate.
  if (!estratti.length && Array.isArray(dati.informazioniConsolidate)) {
    for (const [i, c] of dati.informazioniConsolidate.entries()) {
      const s = sanificaEstrattoFase1({
        id: `cons-${i}`, tema: c.tema, traduzioneIt: c.testo,
        pagina: c.fonteePrincipale?.pagina ?? c.fontePrincipale?.pagina ?? null,
        documento: c.fonteePrincipale?.documento ?? c.fontePrincipale?.documento ?? null,
        tipoDocumento: c.fonteePrincipale?.tipo ?? c.fontePrincipale?.tipo ?? null,
      }, i);
      if (s) estratti.push(s);
    }
  }

  /* Il salvataggio porta la serie per anno; la Fase 1 lavora sul bilancio più
     recente e sul suo comparativo. Gli alias vengono quindi ricalcolati qui:
     `SP` è il prospetto dell'esercizio più recente presente, qualunque anno
     sia. La serie completa resta nel salvataggio e nella Fase 0, che è dove la
     si consulta. */
  const serie = conAlias(migraVersoAnni(st.numerico));
  const numerico = { SP: null, CE: null, RF: null };
  for (const slot of ["SP", "CE", "RF"]) {
    const n = serie?.[slot];
    if (n && typeof n === "object" && n.dati) {
      numerico[slot] = { nomeFile: String(n.nomeFile || `${slot}.json`), dati: n.dati, importatoIl: n.importatoIl || null };
    }
  }

  const parametriDerivati = Array.isArray(dati.parametriDerivati)
    ? dati.parametriDerivati.filter((p) => p && typeof p.metrica === "string")
    : [];

  const fonteAnalisi = st.analisi?.fonte && typeof st.analisi.fonte === "object" ? st.analisi.fonte : {};
  const analisi = {
    azienda: typeof dati.azienda === "string" ? dati.azienda : (st.analisi?.azienda || ""),
    settore: SETTORI.some((s) => s.id === st.analisi?.settore) ? st.analisi.settore : (SETTORI.some((s) => s.id === dati.settore) ? dati.settore : null),
    capitalizzazione: Number.isFinite(st.analisi?.capitalizzazione) ? st.analisi.capitalizzazione : null,
    valuta: typeof st.analisi?.valuta === "string" ? st.analisi.valuta : null,
    fonte: {
      azienda: ["documento", "manuale"].includes(fonteAnalisi.azienda) ? fonteAnalisi.azienda : null,
      settore: ["documento", "manuale"].includes(fonteAnalisi.settore) ? fonteAnalisi.settore : null,
      capitalizzazione: ["documento", "manuale"].includes(fonteAnalisi.capitalizzazione) ? fonteAnalisi.capitalizzazione : null,
    },
    identificatoDa: typeof st.analisi?.identificatoDa === "string" ? st.analisi.identificatoDa : null,
  };

  return {
    ingresso: {
      numerico, estratti, parametriDerivati,
      provenienza: { applicazione: dati.applicazione || "Fase 0", generato: dati.generato || null, documenti: Object.keys(mappa).length },
    },
    azienda: analisi.azienda, // retrocompatibilità con i chiamanti che leggono solo il nome
    analisi,
    riepilogo: { estratti: estratti.length, parametri: parametriDerivati.length, numerici: Object.values(numerico).filter(Boolean).length },
  };
}

/** Ripristina un salvataggio di Fase 1 (formato 2), sanificando gli esiti. */
function ripristinaFase1(dati) {
  const st = dati.statoApplicazione || {};
  const ingresso = {
    numerico: { SP: null, CE: null, RF: null },
    estratti: (Array.isArray(st.ingresso?.estratti) ? st.ingresso.estratti : []).map(sanificaEstrattoFase1).filter(Boolean),
    parametriDerivati: Array.isArray(st.ingresso?.parametriDerivati) ? st.ingresso.parametriDerivati : [],
    provenienza: st.ingresso?.provenienza || null,
  };
  for (const slot of ["SP", "CE", "RF"]) {
    const n = st.ingresso?.numerico?.[slot];
    if (n && typeof n === "object" && n.dati) ingresso.numerico[slot] = { nomeFile: String(n.nomeFile || `${slot}.json`), dati: n.dati, importatoIl: n.importatoIl || null };
  }

  const asa = (Array.isArray(st.analisi?.asa) ? st.analisi.asa : []).map((a, i) => ({
    id: typeof a.id === "string" ? a.id : `asa-${i}`,
    nome: String(a.nome || ""),
    quota: Number.isFinite(a.quota) ? a.quota : 0,
    settore: SETTORI.some((s) => s.id === a.settore) ? a.settore : "generico",
  }));

  let esiti = null;
  if (st.esiti && typeof st.esiti === "object" && st.esiti.direttrici) {
    const direttrici = {};
    for (const spec of TUTTE_LE_DIRETTRICI) {
      const e = st.esiti.direttrici[spec.id];
      direttrici[spec.id] = {
        id: spec.id,
        livello: LIVELLI_VALIDI.includes(e?.livello) ? e.livello : "non_determinabile",
        ragionamento: typeof e?.ragionamento === "string" ? e.ragionamento : "",
        dati: Array.isArray(e?.dati) ? e.dati.filter((x) => x && x.etichetta) : [],
        fonti: Array.isArray(e?.fonti) ? e.fonti.filter(Boolean) : [],
        confidenza: ["alta", "media", "bassa"].includes(e?.confidenza) ? e.confidenza : "bassa",
        origine: e?.origine || "assente",
        divergenza: e?.divergenza || null,
        soglieRilevate: e?.soglieRilevate || null,
      };
    }
    const moduli = {};
    const livelli = {};
    for (const m of MODULI) {
      const suoi = m.direttrici.map((d) => direttrici[d.id]);
      const livello = livelloModulo(suoi);
      livelli[m.id] = livello;
      moduli[m.id] = {
        id: m.id, livello,
        sintesi: st.esiti.moduli?.[m.id]?.sintesi || null,
        rosse: suoi.filter((d) => d.livello === "rosso").length,
        gialle: suoi.filter((d) => d.livello === "giallo").length,
        nonDeterminabili: suoi.filter((d) => d.livello === "non_determinabile").length,
      };
    }
    esiti = {
      direttrici, moduli,
      punteggio: calcolaPunteggio(direttrici, livelli), // ricalcolato: le soglie possono essere cambiate
      sintesiEsecutiva: st.esiti.sintesiEsecutiva || null,
      settoreRiconosciuto: st.esiti.settoreRiconosciuto || null,
      domande: Array.isArray(st.esiti.domande) ? st.esiti.domande : [],
      documentiMancanti: Array.isArray(st.esiti.documentiMancanti) ? st.esiti.documentiMancanti : [],
      eseguitaIl: st.esiti.eseguitaIl || dati.generato || null,
    };
  }

  return {
    stato: {
      analisi: {
        azienda: typeof st.analisi?.azienda === "string" ? st.analisi.azienda : (dati.azienda || ""),
        settore: SETTORI.some((s) => s.id === st.analisi?.settore) ? st.analisi.settore : (SETTORI.some((s) => s.id === dati.settore) ? dati.settore : "generico"),
        capitalizzazione: Number.isFinite(st.analisi?.capitalizzazione) ? st.analisi.capitalizzazione : null,
        valuta: typeof st.analisi?.valuta === "string" ? st.analisi.valuta : null,
        fonte: {
          azienda: ["documento", "manuale"].includes(st.analisi?.fonte?.azienda) ? st.analisi.fonte.azienda : null,
          settore: ["documento", "manuale"].includes(st.analisi?.fonte?.settore) ? st.analisi.fonte.settore : null,
          capitalizzazione: ["documento", "manuale"].includes(st.analisi?.fonte?.capitalizzazione) ? st.analisi.fonte.capitalizzazione : null,
        },
        identificatoDa: typeof st.analisi?.identificatoDa === "string" ? st.analisi.identificatoDa : null,
        asa,
        creata: st.analisi?.creata || dati.generato || new Date().toISOString(),
        eseguitaIl: st.analisi?.eseguitaIl || null,
      },
      ingresso, esiti, esitoIA: st.esitoIA || null,
    },
    riepilogo: { estratti: ingresso.estratti.length, parametri: ingresso.parametriDerivati.length, numerici: Object.values(ingresso.numerico).filter(Boolean).length, valutata: !!esiti },
  };
}

/**
 * Punto unico di ingresso del caricamento: riconosce il formato e instrada.
 * @returns {{modo: "ripristino"|"importazione", stato: Object, messaggio: string}}
 */
function caricaSalvataggio(dati) {
  if (!dati || typeof dati !== "object") throw new Error("il file non contiene un oggetto JSON");
  const st = dati.statoApplicazione;
  if (!st || typeof st !== "object") throw new Error("struttura non riconosciuta: manca il blocco «statoApplicazione»");

  const eFase1 = dati.fase === 1 || dati.formatoSalvataggio === 2 || !!st.esiti || !!st.ingresso;
  if (eFase1) {
    const { stato, riepilogo } = ripristinaFase1(dati);
    return {
      modo: "ripristino", stato,
      messaggio: `Analisi di Fase 1 ripristinata${stato.analisi.azienda ? ` — ${stato.analisi.azienda}` : ""}: ${riepilogo.estratti} estratti, ${riepilogo.parametri} parametri esterni, ${riepilogo.numerici} riclassificati` +
        `${riepilogo.valutata ? ", risultanze di rischio incluse" : ", nessuna valutazione ancora eseguita"}.`,
    };
  }

  const { ingresso, azienda, analisi, riepilogo } = importaDaFase0(dati);
  if (!riepilogo.estratti && !riepilogo.numerici) throw new Error("il salvataggio non contiene né estratti documentali né dati numerici");
  return {
    modo: "importazione",
    stato: { ingresso, azienda, analisi },
    messaggio: `Materiale di Fase 0 importato${azienda ? ` — ${azienda}` : ""}: ${riepilogo.estratti} estratti tradotti, ${riepilogo.parametri} parametri esterni di confronto, ${riepilogo.numerici} riclassificati numerici.`,
  };
}
/* ==========================================================================
   VISTA FASE 1 — diagnosi del contesto
   --------------------------------------------------------------------------
   Come la Fase 0, riceve stato e dispatch dal guscio. Conserva invece i propri
   comandi di merito — azienda, settore, avvio dell'analisi — perché sono
   parametri della diagnosi, non dell'applicazione.
   ========================================================================== */
/**
 * Badge di provenienza per un singolo campo anagrafico: "documento" quando è
 * stato letto dal frontespizio in Fase 0, "manuale" quando l'operatore lo ha
 * corretto, nessun colore acceso quando non è ancora noto.
 */
function BadgeFonte({ fonte }) {
  if (fonte === "documento") return <span className="qoe-eyebrow" style={{ color: C.update }} title="Rilevato automaticamente dall'analisi dei documenti in Fase 0">da documento</span>;
  if (fonte === "manuale") return <span className="qoe-eyebrow" style={{ color: C.ambra }} title="Corretto manualmente dall'operatore">manuale</span>;
  return <span className="qoe-eyebrow" style={{ color: C.muto }}>non rilevato</span>;
}

/**
 * Anagrafica dell'emittente (azienda, settore, capitalizzazione). Per
 * default è di sola lettura: i tre dati arrivano dalla lettura dei documenti
 * in Fase 0, non da un'immissione manuale. "correggi" apre gli stessi tre
 * campi in modifica per i casi in cui la lettura automatica manchi o sia
 * imprecisa — la correzione, una volta fatta, non viene più sovrascritta da
 * un'identificazione automatica successiva.
 */
function AnagraficaBarra({ analisi, modifica, onAttivaModifica, onChiudiModifica, onPatch }) {
  if (modifica) {
    return (
      <div className="flex flex-wrap items-center gap-2">
        <input
          value={analisi.azienda}
          onChange={(e) => onPatch({ azienda: e.target.value })}
          placeholder="Azienda analizzata"
          className="rounded-md border px-3 py-1.5 text-sm"
          style={{ borderColor: C.riga, background: C.carta, minWidth: 200 }}
        />
        <select
          value={analisi.settore}
          onChange={(e) => onPatch({ settore: e.target.value })}
          className="rounded-md border px-3 py-1.5 text-sm"
          style={{ borderColor: C.riga, background: C.carta }}
        >
          {SETTORI.map((s) => <option key={s.id} value={s.id}>{s.label}</option>)}
        </select>
        <input
          type="number" min="0" step="1000000"
          value={analisi.capitalizzazione ?? ""}
          onChange={(e) => onPatch({ capitalizzazione: e.target.value === "" ? null : Number(e.target.value) })}
          placeholder="Capitalizzazione"
          title="Serve al clustering per collocare l'azienda nella fascia di taglia corretta"
          className="rounded-md border px-3 py-1.5 text-sm"
          style={{ borderColor: C.riga, background: C.carta, width: 170, fontFamily: F.mono }}
        />
        <button onClick={onChiudiModifica} className="qoe-btn rounded-md border px-3 py-1.5 text-sm" style={{ borderColor: C.riga, background: C.carta }}>
          Fatto
        </button>
      </div>
    );
  }

  const haAzienda = !!(analisi.azienda || "").trim();
  return (
    <div className="flex flex-wrap items-center gap-3 rounded-md border px-3 py-1.5 text-sm" style={{ borderColor: C.riga, background: C.carta }}>
      <div className="flex items-center gap-1.5">
        <span style={{ fontWeight: 600 }}>{haAzienda ? analisi.azienda : "Azienda non ancora rilevata"}</span>
        <BadgeFonte fonte={analisi.fonte?.azienda} />
      </div>
      <span style={{ color: C.rigaTenue }}>·</span>
      <div className="flex items-center gap-1.5">
        <span style={{ color: C.muto }}>{settorePerId(analisi.settore).label}</span>
        <BadgeFonte fonte={analisi.fonte?.settore} />
      </div>
      <span style={{ color: C.rigaTenue }}>·</span>
      <div className="flex items-center gap-1.5">
        <span style={{ color: C.muto, fontFamily: F.mono }}>
          {analisi.capitalizzazione != null ? `${fmtImporto(analisi.capitalizzazione)} ${analisi.valuta || ""}`.trim() : "capitalizzazione non rilevata"}
        </span>
        <BadgeFonte fonte={analisi.fonte?.capitalizzazione} />
      </div>
      <button onClick={onAttivaModifica} title="Correggi manualmente azienda, settore o capitalizzazione"
        className="qoe-eyebrow underline ml-1" style={{ color: C.update }}>
        correggi
      </button>
    </div>
  );
}

function VistaFase1({ stato, dispatch, aperti, setAperti, onSalva, onCarica, daConsegnare, clustering, softSignals }) {
  const [tab, setTab] = useState("dashboard");
  const [modificaAnagrafica, setModificaAnagrafica] = useState(false);

  const statoRef = useRef(stato);
  statoRef.current = stato;

  /* ---- Catena derivata: voci → indicatori → Δ → benchmark → calcolo ------
     Tutto ricalcolato a ogni cambiamento dell'ingresso o del settore. È
     volutamente sincrono e senza cache esterna: sono poche centinaia di
     operazioni e la trasparenza vale più della micro-ottimizzazione. */
  const derivati = useMemo(() => {
    const { voci, righeIndicizzate } = leggiVoci(stato.ingresso.numerico);
    return {
      voci, righeIndicizzate,
      indicatori: calcolaIndicatori(voci),
      delta: calcolaDeltaPatrimoniali(voci),
      benchmark: estraiBenchmark(stato.ingresso.parametriDerivati),
    };
  }, [stato.ingresso.numerico, stato.ingresso.parametriDerivati]);

  const esitiCalcolo = useMemo(
    () => valutazioneDeterministica({
      indicatori: derivati.indicatori,
      benchmark: derivati.benchmark,
      estratti: stato.ingresso.estratti,
      settore: stato.analisi.settore,
      voci: derivati.voci,
    }),
    [derivati, stato.ingresso.estratti, stato.analisi.settore]
  );

  const contesto = useMemo(() => ({
    azienda: stato.analisi.azienda,
    settore: stato.analisi.settore,
    asa: stato.analisi.asa,
    indicatori: derivati.indicatori,
    delta: derivati.delta,
    benchmark: derivati.benchmark,
    estratti: stato.ingresso.estratti,
    esitiCalcolo,
  }), [stato.analisi, derivati, stato.ingresso.estratti, esitiCalcolo]);

  const haIngresso = stato.ingresso.estratti.length > 0 || Object.values(stato.ingresso.numerico).some(Boolean);

  /* ---- Esecuzione dell'analisi: un modulo per volta --------------------- */
  const avviaAnalisi = useCallback(async () => {
    if (!haIngresso) {
      dispatch({ tipo: "NOTIFICA", notifica: { gravita: "alta", testo: "Nessun materiale in ingresso: carica il salvataggio di Fase 0 oppure almeno un JSON riclassificato." } });
      return;
    }
    dispatch({ tipo: "LOG", livello: "info", testo: `Avvio analisi forense su ${stato.ingresso.estratti.length} estratti e ${Object.values(stato.ingresso.numerico).filter(Boolean).length} riclassificati.` });

    try {
      const { esiti, esitoIA } = await eseguiDiagnosiForense({
        contesto, esitiCalcolo,
        onProgresso: (p) => dispatch({ tipo: "PROGRESSO", elaborazione: p }),
        onLog: (l) => dispatch({ tipo: "LOG", livello: l.livello, testo: l.testo }),
      });
      dispatch({ tipo: "ANALISI_ESEGUITA", esiti, esitoIA });
      setTab("dashboard");
      setAperti({ A: true });
    } catch (err) {
      dispatch({ tipo: "FINE_ELABORAZIONE" });
      dispatch({ tipo: "LOG", livello: "errore", testo: `Analisi interrotta: ${err.message || "errore imprevisto"}.` });
      dispatch({ tipo: "NOTIFICA", notifica: { gravita: "alta", testo: `L'analisi si è interrotta (${err.message || "errore imprevisto"}). Gli esiti già calcolati restano disponibili nella scheda Dati e calcoli.` } });
    }
  }, [contesto, esitiCalcolo, haIngresso, stato.ingresso]);  const importaNumerico = useCallback(async (file, slot) => {
    try {
      const testo = await file.text();
      const dati = JSON.parse(testo);
      dispatch({ tipo: "NUMERICO_CARICATO", slot, dati: { nomeFile: file.name, dati, importatoIl: new Date().toISOString() } });
    } catch {
      dispatch({ tipo: "LOG", livello: "errore", testo: `${file.name} non è un JSON valido. Riesporta il file dall'applicazione ${slot} riclassificato.` });
    }
  }, []);

  const punteggio = stato.esiti?.punteggio || null;
  return (
    <>
      {/* ── Barra della fase ─────────────────────────────────────────── */}
      <div className="border-b" style={{ borderColor: C.rigaTenue, background: C.carta }}>
        <div className="mx-auto max-w-7xl px-6 py-2.5 flex flex-wrap items-center gap-3">
          <AnagraficaBarra
            analisi={stato.analisi}
            modifica={modificaAnagrafica}
            onAttivaModifica={() => setModificaAnagrafica(true)}
            onChiudiModifica={() => setModificaAnagrafica(false)}
            onPatch={(patch) => dispatch({ tipo: "ANAGRAFICA", patch })}
          />
          <button onClick={avviaAnalisi} disabled={!!stato.elaborazione}
            className="qoe-btn flex items-center gap-2 rounded-md px-4 py-1.5 text-sm"
            style={{ background: stato.elaborazione ? C.muto : C.inchiostro, color: "#fff", opacity: stato.elaborazione ? 0.7 : 1 }}>
            {stato.elaborazione ? <Loader2 size={14} className="animate-spin" /> : <Play size={14} />}
            {stato.esiti ? "Rivaluta il rischio" : "Avvia analisi forense"}
          </button>

          <nav className="ml-auto flex rounded-md overflow-hidden border" style={{ borderColor: C.riga }}>
            {[["dashboard", "Rischio"], ["dati", "Dati e calcoli"]].map(([k, l]) => (
              <button key={k} onClick={() => setTab(k)} className="qoe-btn px-3 py-1.5"
                style={{ background: tab === k ? C.inchiostro : C.carta, color: tab === k ? "#fff" : C.muto, fontFamily: F.mono, fontSize: 12 }}>
                {l}
              </button>
            ))}
          </nav>
        </div>
      </div>

      {/* La Fase 0 ha acquisito materiale che qui non è ancora arrivato. */}
      {daConsegnare && (
        <div className="mx-auto max-w-7xl px-6 pt-4">
          <div className="flex items-start gap-3 rounded-md border px-4 py-3" style={{ borderColor: C.ambra, background: C.ambraTenue }}>
            <AlertTriangle size={16} className="mt-0.5 shrink-0" style={{ color: C.ambra }} />
            <p className="text-sm flex-1">
              L'ingestione contiene materiale non ancora consegnato a questa fase. La diagnosi sta lavorando su una fotografia precedente:
              torna alla Fase 0 e premi «Consegna alla Fase 1» per allinearla.
            </p>
          </div>
        </div>
      )}

      {/* ── Notifica dinamica ────────────────────────────────────────── */}
      {stato.notifica && (
        <div className="mx-auto max-w-7xl px-6 pt-4">
          <div className="flex items-start gap-3 rounded-md border px-4 py-3"
            style={{ borderColor: stato.notifica.gravita === "alta" ? C.flag : C.riga, background: stato.notifica.gravita === "alta" ? C.flagTenue : C.carta }}>
            <Info size={16} className="mt-0.5 shrink-0" style={{ color: stato.notifica.gravita === "alta" ? C.flag : C.muto }} />
            <p className="text-sm flex-1">{stato.notifica.testo}</p>
            <button onClick={() => dispatch({ tipo: "NOTIFICA", notifica: null })} aria-label="Chiudi notifica"><X size={14} style={{ color: C.muto }} /></button>
          </div>
        </div>
      )}

      <main className="mx-auto max-w-7xl px-6 py-6 grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-6">
          {tab === "dashboard" && (
            <>
              <PannelloPunteggio punteggio={punteggio} esiti={stato.esiti} elaborazione={stato.elaborazione} haIngresso={haIngresso} />
              {MODULI.map((m) => (
                <React.Fragment key={m.id}>
                  <SchedaModulo
                    modulo={m}
                    esitoModulo={stato.esiti?.moduli?.[m.id] || null}
                    direttrici={stato.esiti?.direttrici || null}
                    esitiCalcolo={esitiCalcolo}
                    aperto={!!aperti[m.id]}
                    onToggle={() => setAperti((a) => ({ ...a, [m.id]: !a[m.id] }))}
                  />
                  {m.id === "A" && <PannelloClustering clustering={clustering} />}
                  {m.id === "D" && <PannelloSoftSignals softSignals={softSignals} />}
                </React.Fragment>
              ))}
              {stato.esiti && <SchedaConclusioni esiti={stato.esiti} />}
            </>
          )}

          {tab === "dati" && (
            <>
              <PannelloIngresso
                ingresso={stato.ingresso}
                derivati={derivati}
                onCaricaSalvataggio={onCarica}
                onImportaNumerico={importaNumerico}
              />
              <EditorASA asa={stato.analisi.asa} settorePrevalente={stato.analisi.settore} dispatch={dispatch} />
              <TabellaIndicatori indicatori={derivati.indicatori} benchmark={derivati.benchmark} />
              <TabellaDelta delta={derivati.delta} />
            </>
          )}

        </div>

        <aside className="space-y-6">
          <RiepilogoLaterale
            stato={stato} derivati={derivati} esitiCalcolo={esitiCalcolo}
            punteggio={punteggio} onSalva={onSalva} onCarica={onCarica}
          />
          <FeedAttivita attivita={stato.attivita} elaborazione={stato.elaborazione} />
        </aside>
      </main>    </>
  );
}
/**
 * SEMAFORO
 * Tre luci sempre visibili, una sola accesa: si legge lo stato e insieme la
 * scala su cui è misurato, senza bisogno di una legenda. Il quarto stato
 * (non determinabile) spegne tutte e tre le luci e lascia il contorno vuoto:
 * l'assenza di giudizio si vede a colpo d'occhio e non somiglia a un verde.
 */
function Semaforo({ livello, dimensione = 10 }) {
  const ordine = ["verde", "giallo", "rosso"];
  const nd = livello === "non_determinabile" || !livello;
  return (
    <span className="inline-flex items-center gap-1" role="img" aria-label={`Livello di rischio: ${RISCHIO[livello || "non_determinabile"].label}`}>
      {ordine.map((l) => {
        const acceso = !nd && l === livello;
        return (
          <span key={l} style={{
            width: dimensione, height: dimensione, borderRadius: "50%",
            background: acceso ? RISCHIO[l].colore : "transparent",
            border: `1.5px solid ${acceso ? RISCHIO[l].colore : C.riga}`,
            opacity: nd ? 0.5 : acceso ? 1 : 0.35,
            display: "inline-block",
          }} />
        );
      })}
    </span>
  );
}

function Etichetta({ livello }) {
  const r = RISCHIO[livello || "non_determinabile"];
  return (
    <span className="qoe-eyebrow rounded px-2 py-0.5" style={{ background: r.tenue, color: r.colore }}>{r.breve}</span>
  );
}

/* ── Quality Score ──────────────────────────────────────────────────── */
const RAGGIO = 62;
const ARCO = Math.PI * RAGGIO;

function PannelloPunteggio({ punteggio, esiti, elaborazione, haIngresso }) {
  if (elaborazione) {
    return (
      <section className="rounded-lg border p-6" style={{ borderColor: C.update, background: C.updateTenue }}>
        <div className="flex items-center gap-3">
          <Loader2 size={18} className="animate-spin" style={{ color: C.update }} />
          <div className="flex-1">
            <div className="qoe-eyebrow" style={{ color: C.update }}>Modulo {elaborazione.modulo} di {elaborazione.totale}</div>
            <p className="text-sm mt-0.5">{elaborazione.titolo}</p>
          </div>
        </div>
        <div className="mt-3 h-1 rounded-full overflow-hidden" style={{ background: C.riga }}>
          <div className="h-full transition-all" style={{ width: `${(elaborazione.indice / elaborazione.totale) * 100}%`, background: C.update }} />
        </div>
      </section>
    );
  }

  if (!punteggio) {
    return (
      <section className="rounded-lg border p-6" style={{ borderColor: C.riga, background: C.carta }}>
        <div className="qoe-eyebrow" style={{ color: C.muto }}>Punteggio di qualità contabile</div>
        <p className="mt-2 text-sm" style={{ color: C.muto }}>
          {haIngresso
            ? "Il materiale è caricato. Avvia l'analisi forense per ottenere i semafori dei quattro moduli e il punteggio complessivo."
            : "Carica il salvataggio della Fase 0 dal pulsante «Carica dati salvati», oppure importa i JSON riclassificati dalla scheda Dati e calcoli."}
        </p>
      </section>
    );
  }

  const p = punteggio;
  return (
    <section className="rounded-lg border" style={{ borderColor: C.riga, background: C.carta }}>
      <div className="p-6 flex flex-col sm:flex-row items-center gap-6">
        <div className="shrink-0 text-center">
          <svg viewBox="0 0 160 96" width="180" height="108" role="img" aria-label={`Punteggio ${p.punteggio} su 100`}>
            <path d="M 18 80 A 62 62 0 0 1 142 80" fill="none" stroke={C.rigaTenue} strokeWidth="11" strokeLinecap="round" />
            <path d="M 18 80 A 62 62 0 0 1 142 80" fill="none" stroke={p.colore} strokeWidth="11" strokeLinecap="round"
              strokeDasharray={`${(p.punteggio / 100) * ARCO} ${ARCO}`} />
            <text x="80" y="70" textAnchor="middle" style={{ fontFamily: F.display, fontWeight: 800, fontSize: 34, fill: C.inchiostro }}>{p.punteggio}</text>
            <text x="80" y="88" textAnchor="middle" className="qoe-eyebrow" style={{ fontFamily: F.mono, fontSize: 9, letterSpacing: "0.14em", fill: C.muto }}>SU 100</text>
          </svg>
        </div>

        <div className="flex-1 min-w-0">
          <div className="qoe-eyebrow" style={{ color: C.muto }}>Punteggio di qualità contabile del contesto</div>
          <h2 className="mt-1 text-xl" style={{ fontFamily: F.display, fontWeight: 700, color: p.colore }}>{p.fascia}</h2>
          <p className="mt-1 text-sm leading-relaxed" style={{ color: C.muto }}>{p.notaFascia}</p>

          <div className="mt-3 flex flex-wrap gap-2">
            <span className="qoe-eyebrow rounded px-2 py-1" style={{ background: C.flagTenue, color: C.flag }}>{p.rosse} red flag</span>
            <span className="qoe-eyebrow rounded px-2 py-1" style={{ background: C.ambraTenue, color: C.ambra }}>{p.gialle} in attenzione</span>
            <span className="qoe-eyebrow rounded px-2 py-1" style={{ background: C.fondo, color: C.muto }}>
              {p.direttriciValutate} di {p.direttriciTotali} direttrici valutate
            </span>
          </div>

          <div className="mt-3">
            <div className="flex items-center justify-between qoe-eyebrow" style={{ color: C.muto }}>
              <span>Copertura dell'analisi</span><span>{p.copertura}%</span>
            </div>
            <div className="mt-1 h-1 rounded-full overflow-hidden" style={{ background: C.rigaTenue }}>
              <div className="h-full" style={{ width: `${p.copertura}%`, background: C.update }} />
            </div>
          </div>

          {p.vincoloGovernance && (
            <p className="mt-3 text-xs leading-relaxed rounded px-3 py-2" style={{ background: C.flagTenue, color: C.flag }}>
              Punteggio limitato a 55: con il modulo Governance in rosso, nessun altro risultato può essere considerato presidiato.
            </p>
          )}
        </div>
      </div>

      {/* Striscia dei quattro semafori: la lettura d'insieme prima del dettaglio */}
      <div className="grid grid-cols-2 sm:grid-cols-4 border-t" style={{ borderColor: C.rigaTenue }}>
        {MODULI.map((m) => {
          const liv = esiti?.moduli?.[m.id]?.livello || "non_determinabile";
          return (
            <div key={m.id} className="px-4 py-3 border-r last:border-r-0" style={{ borderColor: C.rigaTenue }}>
              <div className="flex items-center gap-2">
                <Semaforo livello={liv} dimensione={8} />
                <span className="qoe-eyebrow" style={{ color: C.muto }}>Modulo {m.id}</span>
              </div>
              <div className="mt-1 text-xs leading-snug">{m.titolo}</div>
            </div>
          );
        })}
      </div>
    </section>
  );
}

/* ── Scheda espandibile di modulo ───────────────────────────────────── */
function SchedaModulo({ modulo, esitoModulo, direttrici, esitiCalcolo, aperto, onToggle }) {
  const Icona = modulo.icona;
  const livello = esitoModulo?.livello || "non_determinabile";
  const r = RISCHIO[livello];

  return (
    <section className="rounded-lg border overflow-hidden" style={{ borderColor: livello === "rosso" ? C.flag : C.riga, background: C.carta }}>
      <button onClick={onToggle} className="qoe-btn w-full text-left p-4 flex items-start gap-3" aria-expanded={aperto}>
        <span className="mt-0.5" style={{ color: r.colore }}><Icona size={16} /></span>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="qoe-eyebrow" style={{ color: C.muto }}>Modulo {modulo.id}</span>
            <span className="qoe-eyebrow" style={{ color: C.muto }}>· {modulo.occhiello}</span>
          </div>
          <h3 className="mt-0.5 text-base" style={{ fontFamily: F.display, fontWeight: 600 }}>{modulo.titolo}</h3>
          <p className="mt-1 text-xs leading-relaxed" style={{ color: C.muto }}>{modulo.domandaChiave}</p>
          {esitoModulo?.sintesi && aperto === false && (
            <p className="mt-2 text-sm leading-relaxed">{esitoModulo.sintesi}</p>
          )}
        </div>
        <div className="flex flex-col items-end gap-2 shrink-0">
          <Semaforo livello={livello} />
          <Etichetta livello={livello} />
          {esitoModulo && (
            <span className="qoe-eyebrow" style={{ color: C.muto }}>
              {esitoModulo.rosse}R · {esitoModulo.gialle}G · {esitoModulo.nonDeterminabili}N.D.
            </span>
          )}
          <span style={{ color: C.muto }}>{aperto ? <ChevronDown size={14} /> : <ChevronRight size={14} />}</span>
        </div>
      </button>

      {aperto && (
        <div className="border-t" style={{ borderColor: C.rigaTenue }}>
          {esitoModulo?.sintesi && (
            <p className="px-4 pt-4 text-sm leading-relaxed" style={{ color: C.inchiostro }}>{esitoModulo.sintesi}</p>
          )}
          <div className="p-4 space-y-3">
            {modulo.direttrici.map((d) => (
              <RigaDirettrice key={d.id} spec={d} esito={direttrici?.[d.id] || esitiCalcolo?.[d.id] || null} />
            ))}
          </div>
        </div>
      )}
    </section>
  );
}

/* ── Riga di direttrice: ragionamento, dati a supporto, fonte ───────── */
function RigaDirettrice({ spec, esito }) {
  const [apertaFonte, setApertaFonte] = useState(false);
  const livello = esito?.livello || "non_determinabile";
  const r = RISCHIO[livello];

  return (
    <article className="rounded-md border p-3" style={{ borderColor: C.rigaTenue, background: livello === "rosso" ? C.flagTenue : C.carta, borderLeft: `3px solid ${r.colore}` }}>
      <div className="flex items-start gap-2">
        <Semaforo livello={livello} dimensione={8} />
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="qoe-eyebrow" style={{ color: C.muto }}>{spec.id}</span>
            <h4 className="text-sm" style={{ fontWeight: 600 }}>{spec.titolo}</h4>
          </div>
          <p className="mt-0.5 text-xs" style={{ color: C.muto }}>{spec.domanda}</p>
        </div>
        <div className="flex flex-col items-end gap-1 shrink-0">
          <Etichetta livello={livello} />
          {esito?.origine && esito.origine !== "assente" && (
            <span className="qoe-eyebrow" style={{ color: C.muto }}>
              {{
                calcolo: "da calcolo",
                ia: "da documenti",
                misto: "calcolo + documenti",
              }[esito.origine] || esito.origine}
            </span>
          )}
        </div>
      </div>

      {esito?.ragionamento && (
        <p className="mt-2 text-sm leading-relaxed whitespace-pre-line">{esito.ragionamento}</p>
      )}
      {!esito && (
        <p className="mt-2 text-sm" style={{ color: C.muto }}>Non ancora valutata: avvia l'analisi forense.</p>
      )}

      {esito?.divergenza && (
        <p className="mt-2 text-xs rounded px-2 py-1" style={{ background: C.ambraTenue, color: C.ambra }}>
          Letture discordanti — {esito.divergenza}. Prevale la più severa.
        </p>
      )}

      {/* Una direttrice scoperta senza un'indicazione su dove cercare è un
          vicolo cieco: qui si dice in quale sezione di quale documento il dato
          si trova di norma, così l'assenza diventa un compito e non un verdetto. */}
      {livello === "non_determinabile" && DOVE_CERCARE[spec.id] && (
        <div className="mt-2 rounded-md px-3 py-2" style={{ background: C.fondo }}>
          <div className="qoe-eyebrow mb-1" style={{ color: C.muto }}>Dove si trova di norma</div>
          <ul className="space-y-0.5">
            {DOVE_CERCARE[spec.id].map(([documento, punto], i) => (
              <li key={i} className="text-xs leading-snug">
                <span style={{ fontFamily: F.mono, fontSize: 11, color: C.update }}>{documento}</span>
                <span style={{ color: C.muto }}> · {punto}</span>
              </li>
            ))}
          </ul>
        </div>
      )}

      {!!esito?.dati?.length && (
        <div className="mt-2 flex flex-wrap gap-1.5">
          {esito.dati.map((d, i) => (
            <span key={i} className="rounded px-2 py-1 text-xs" style={{ background: C.fondo }}>
              <span style={{ color: C.muto }}>{d.etichetta}: </span>
              <span style={{ fontFamily: F.mono, fontSize: 11 }}>{d.valore}</span>
            </span>
          ))}
        </div>
      )}

      {!!esito?.fonti?.length && (
        <div className="mt-2">
          <button onClick={() => setApertaFonte((v) => !v)} className="qoe-btn qoe-eyebrow flex items-center gap-1" style={{ color: C.update }}>
            {apertaFonte ? <ChevronDown size={11} /> : <ChevronRight size={11} />}
            {plurale(esito.fonti.length, "fonte documentale", "fonti documentali")}
          </button>
          {apertaFonte && (
            <ul className="mt-2 space-y-2">
              {esito.fonti.map((f, i) => (
                <li key={i} className="rounded px-3 py-2 text-xs leading-relaxed" style={{ background: C.updateTenue }}>
                  <div className="qoe-eyebrow" style={{ color: C.update }}>
                    {f.tipo ? `${f.tipo} · ` : ""}{f.documento}{f.pagina ? `, p. ${f.pagina}` : ""}
                  </div>
                  <p className="mt-1" style={{ color: C.inchiostro }}>{f.citazione}</p>
                </li>
              ))}
            </ul>
          )}
        </div>
      )}
    </article>
  );
}

/* ── Sintesi esecutiva, domande e lacune ────────────────────────────── */
function SchedaConclusioni({ esiti }) {
  return (
    <section className="rounded-lg border" style={{ borderColor: C.riga, background: C.carta }}>
      <Intestazione icona={<ShieldAlert size={14} />} titolo="Sintesi e passi successivi"
        nota="Ciò che il revisore deve portare al tavolo prima di passare ai modelli statistici." />
      <div className="px-4 pb-4 space-y-4">
        {esiti.sintesiEsecutiva && <p className="text-sm leading-relaxed">{esiti.sintesiEsecutiva}</p>}

        {!!esiti.domande.length && (
          <div>
            <div className="qoe-eyebrow mb-2" style={{ color: C.muto }}>Domande da porre al management</div>
            <ul className="space-y-1.5">
              {esiti.domande.map((d, i) => (
                <li key={i} className="flex gap-2 text-sm leading-relaxed">
                  <span style={{ fontFamily: F.mono, color: C.muto, fontSize: 11 }}>{String(i + 1).padStart(2, "0")}</span>
                  <span>{d}</span>
                </li>
              ))}
            </ul>
          </div>
        )}

        {!!esiti.documentiMancanti.length && (
          <div>
            <div className="qoe-eyebrow mb-2" style={{ color: C.muto }}>Documenti che scioglierebbero i «non determinabile»</div>
            <ul className="flex flex-wrap gap-1.5">
              {esiti.documentiMancanti.map((d, i) => (
                <li key={i} className="rounded px-2 py-1 text-xs" style={{ background: C.esternoTenue, color: C.esterno }}>{d}</li>
              ))}
            </ul>
          </div>
        )}
      </div>
    </section>
  );
}

/* ── Scheda dati in ingresso ────────────────────────────────────────── */
function PannelloIngresso({ ingresso, derivati, onCaricaSalvataggio, onImportaNumerico }) {
  const slots = [
    { k: "SP", l: "Stato Patrimoniale riclassificato" },
    { k: "CE", l: "Conto Economico riclassificato" },
    { k: "RF", l: "Rendiconto Finanziario riclassificato" },
  ];
  const temi = {};
  for (const e of ingresso.estratti) temi[e.tema || "n.d."] = (temi[e.tema || "n.d."] || 0) + 1;

  return (
    <section className="rounded-lg border" style={{ borderColor: C.riga, background: C.carta }}>
      <Intestazione icona={<Database size={14} />} titolo="Materiale in ingresso"
        nota="La Fase 1 non legge PDF: consuma ciò che la Fase 0 ha già filtrato e tradotto, più i riclassificati numerici."
        badge={
          <button onClick={onCaricaSalvataggio} className="qoe-btn flex items-center gap-2 rounded-md border px-3 py-1.5 text-xs"
            style={{ borderColor: C.update, color: C.update, background: C.updateTenue }}>
            <FolderOpen size={12} /> Carica salvataggio Fase 0
          </button>
        } />

      <div className="px-4 pb-4 space-y-4">
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          {slots.map(({ k, l }) => {
            const caricato = ingresso.numerico[k];
            return (
              <label key={k} className="cursor-pointer rounded-md border p-3 flex flex-col gap-2"
                style={{ borderColor: caricato ? C.baseline : C.riga, background: caricato ? C.baselineTenue : C.carta }}>
                <input type="file" accept=".json,application/json" className="hidden"
                  onChange={(e) => e.target.files?.[0] && onImportaNumerico(e.target.files[0], k)} />
                <div className="flex items-center justify-between">
                  <span className="qoe-eyebrow" style={{ color: caricato ? C.baseline : C.muto }}>{k}</span>
                  {caricato ? <Check size={14} style={{ color: C.baseline }} /> : <FileText size={14} style={{ color: C.muto }} />}
                </div>
                <span className="text-xs leading-snug">{l}</span>
                <span className="text-xs truncate" style={{ color: C.muto, fontFamily: F.mono, fontSize: 11 }}>
                  {caricato ? caricato.nomeFile : "Nessun file"}
                </span>
              </label>
            );
          })}
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          {[
            { l: "Estratti tradotti", v: ingresso.estratti.length },
            { l: "Parametri esterni", v: ingresso.parametriDerivati.length },
            { l: "Righe numeriche indicizzate", v: derivati.righeIndicizzate },
            { l: "Indicatori calcolabili", v: `${ELENCO_INDICATORI(derivati.indicatori).filter((i) => i.disponibile).length} / ${ELENCO_INDICATORI(derivati.indicatori).length}` },
          ].map((x) => (
            <div key={x.l} className="rounded-md border p-3" style={{ borderColor: C.rigaTenue }}>
              <div className="text-lg" style={{ fontFamily: F.display, fontWeight: 700 }}>{x.v}</div>
              <div className="qoe-eyebrow mt-0.5" style={{ color: C.muto }}>{x.l}</div>
            </div>
          ))}
        </div>

        {!!Object.keys(temi).length && (
          <div>
            <div className="qoe-eyebrow mb-2" style={{ color: C.muto }}>Estratti per tema</div>
            <div className="flex flex-wrap gap-1.5">
              {Object.entries(temi).sort((a, b) => b[1] - a[1]).map(([t, n]) => (
                <span key={t} className="rounded px-2 py-1 text-xs" style={{ background: C.fondo }}>
                  {t.replace(/_/g, " ")} <span style={{ fontFamily: F.mono, color: C.muto }}>{n}</span>
                </span>
              ))}
            </div>
          </div>
        )}

        {ingresso.provenienza && (
          <p className="text-xs" style={{ color: C.muto }}>
            Origine: {ingresso.provenienza.applicazione}
            {ingresso.provenienza.generato ? ` · salvataggio del ${new Date(ingresso.provenienza.generato).toLocaleDateString("it-IT")}` : ""}
            {ingresso.provenienza.documenti ? ` · ${ingresso.provenienza.documenti} documenti di origine` : ""}
          </p>
        )}
      </div>
    </section>
  );
}

/* ── Configurazione delle Aree Strategiche d'Affari ─────────────────── */
function EditorASA({ asa, settorePrevalente, dispatch }) {
  const totale = asa.reduce((s, a) => s + (Number(a.quota) || 0), 0);
  return (
    <section className="rounded-lg border" style={{ borderColor: C.riga, background: C.carta }}>
      <Intestazione icona={<Building2 size={14} />} titolo="Aree strategiche d'affari (ASA)"
        nota="Un gruppo con più business ha più talloni d'Achille: ogni ASA porta con sé la posta sensibile del proprio settore, e il modulo B le valuta separatamente."
        badge={
          <button onClick={() => dispatch({ tipo: "ASA_AGGIUNTA" })} className="qoe-btn rounded-md border px-3 py-1.5 text-xs"
            style={{ borderColor: C.riga, color: C.inchiostro }}>Aggiungi ASA</button>
        } />
      <div className="px-4 pb-4">
        {asa.length === 0 ? (
          <p className="text-sm" style={{ color: C.muto }}>
            Nessuna ASA configurata: l'azienda è trattata come mono-business sul settore «{settorePerId(settorePrevalente).label}».
          </p>
        ) : (
          <div className="space-y-2">
            {asa.map((a) => (
              <div key={a.id} className="flex flex-wrap items-center gap-2 rounded-md border p-2" style={{ borderColor: C.rigaTenue }}>
                <input value={a.nome} placeholder="Nome dell'area" className="rounded border px-2 py-1.5 text-sm flex-1"
                  style={{ borderColor: C.riga, minWidth: 160 }}
                  onChange={(e) => dispatch({ tipo: "ASA_MODIFICATA", id: a.id, patch: { nome: e.target.value } })} />
                <div className="flex items-center gap-1">
                  <input type="number" min="0" max="100" value={a.quota} className="rounded border px-2 py-1.5 text-sm w-20"
                    style={{ borderColor: C.riga, fontFamily: F.mono }}
                    onChange={(e) => dispatch({ tipo: "ASA_MODIFICATA", id: a.id, patch: { quota: Number(e.target.value) } })} />
                  <span className="qoe-eyebrow" style={{ color: C.muto }}>% ricavi</span>
                </div>
                <select value={a.settore} className="rounded border px-2 py-1.5 text-sm"
                  style={{ borderColor: C.riga }}
                  onChange={(e) => dispatch({ tipo: "ASA_MODIFICATA", id: a.id, patch: { settore: e.target.value } })}>
                  {SETTORI.map((s) => <option key={s.id} value={s.id}>{s.label}</option>)}
                </select>
                <button onClick={() => dispatch({ tipo: "ASA_RIMOSSA", id: a.id })} className="qoe-btn p-1.5" aria-label="Rimuovi area">
                  <X size={14} style={{ color: C.muto }} />
                </button>
              </div>
            ))}
            <p className="text-xs" style={{ color: totale === 100 ? C.muto : C.ambra }}>
              Somma delle quote: {fmtNum(totale, 0)}%{totale !== 100 ? " — le quote non chiudono a 100%, il peso relativo delle poste sensibili resterà approssimato." : ""}
            </p>
          </div>
        )}
      </div>
    </section>
  );
}

/* ── Indicatori calcolati ───────────────────────────────────────────── */
function TabellaIndicatori({ indicatori, benchmark }) {
  const [aperto, setAperto] = useState(null);
  const lista = ELENCO_INDICATORI(indicatori);
  const mappaMetrica = { margine_ebitda: "margine_ebitda", margine_ebit: "margine_ebit", dso: "dso", dpo: "dpo", ciclo_circolante: "ciclo_circolante", leva_finanziaria: "leva_finanziaria", crescita_ricavi: "crescita_ricavi", costo_debito: "costo_debito" };

  return (
    <section className="rounded-lg border" style={{ borderColor: C.riga, background: C.carta }}>
      <Intestazione icona={<Activity size={14} />} titolo="Indicatori calcolati"
        nota="Aritmetica sui riclassificati, non stime del modello. Ogni riga mostra la formula e le voci da cui è stata ricavata." />
      <div className="px-4 pb-4">
        <div className="divide-y" style={{ borderColor: C.rigaTenue }}>
          {lista.map((i) => {
            const rif = riferimento(benchmark, mappaMetrica[i.id]);
            const espanso = aperto === i.id;
            return (
              <div key={i.id} className="py-2" style={{ borderColor: C.rigaTenue }}>
                <button onClick={() => setAperto(espanso ? null : i.id)} className="qoe-btn w-full flex items-center gap-3 text-left">
                  <span style={{ color: C.muto }}>{espanso ? <ChevronDown size={12} /> : <ChevronRight size={12} />}</span>
                  <span className="text-sm flex-1">{i.label}</span>
                  {rif && (
                    <span className="qoe-eyebrow" style={{ color: C.esterno }}>
                      rif. {rif.perimetro} {fmtNum(rif.valore, 1)}{rif.unita || ""}
                    </span>
                  )}
                  {i.variazione !== null && (
                    <span className="qoe-eyebrow" style={{ color: i.variazione > 0 ? C.flag : C.baseline }}>
                      {segno(i.variazione)}{fmtNum(i.variazione, 1)}%
                    </span>
                  )}
                  <span className="text-sm" style={{ fontFamily: F.mono, color: i.disponibile ? C.inchiostro : C.muto, minWidth: 80, textAlign: "right" }}>
                    {fmtIndicatore(i)}
                  </span>
                </button>
                {espanso && (
                  <div className="mt-2 ml-6 rounded-md p-3 text-xs" style={{ background: C.fondo }}>
                    <div><span style={{ color: C.muto }}>Formula: </span><span style={{ fontFamily: F.mono }}>{i.formula}</span></div>
                    <div className="mt-1"><span style={{ color: C.muto }}>Esercizio precedente: </span>
                      <span style={{ fontFamily: F.mono }}>{i.precedente !== null ? fmtNum(i.precedente, 2) : "non disponibile"}</span></div>
                    <ul className="mt-2 space-y-1">
                      {i.componenti.map((c, k) => (
                        <li key={k} className="flex justify-between gap-3">
                          <span style={{ color: C.muto }}>{c.voce}</span>
                          <span style={{ fontFamily: F.mono }}>
                            {fmtImporto(c.corrente)}{c.precedente !== null ? ` ← ${fmtImporto(c.precedente)}` : ""}
                          </span>
                        </li>
                      ))}
                    </ul>
                    {i.componenti.some((c) => c.percorso) && (
                      <p className="mt-2" style={{ color: C.muto }}>
                        Origine dei dati: {i.componenti.filter((c) => c.percorso).map((c) => c.percorso).join(" · ")}
                      </p>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

/* ── Δ patrimoniali ─────────────────────────────────────────────────── */
